import json, os, re, sys, glob, collections

ROOT = os.path.expanduser('~/.claude/projects')
DIRS = [d for d in glob.glob(os.path.join(ROOT, '*')) if 'sc4sap' in d.lower()]
SKILLS = ['ask-consultant', 'create-object', 'analyze-symptom', 'analyze-cbo-obj', 'package-to-process']
pat = re.compile(r'<command-name>/?sc4sap:(%s)</command-name>' % '|'.join(SKILLS))
argpat = re.compile(r'<command-args>(.*?)</command-args>', re.S)

hits = []
agent_usage = collections.defaultdict(list)  # subagent_type -> list of (in, out, cache_read, cache_create, model)

def text_of(msg):
    c = msg.get('content')
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        return '\n'.join(p.get('text', '') for p in c if isinstance(p, dict) and p.get('type') == 'text')
    return ''

files = []
for d in DIRS:
    files += glob.glob(os.path.join(d, '**', '*.jsonl'), recursive=True)

for f in files:
    is_sub = os.sep + 'subagents' + os.sep in f
    sub_type = None
    tot = [0, 0, 0, 0]
    model = None
    try:
        with open(f, encoding='utf-8') as fh:
            for line in fh:
                try:
                    o = json.loads(line)
                except Exception:
                    continue
                m = o.get('message') or {}
                if not is_sub and o.get('type') == 'user':
                    t = text_of(m)
                    mm = pat.search(t)
                    if mm:
                        a = argpat.search(t)
                        hits.append((mm.group(1), (a.group(1).strip() if a else ''), o.get('timestamp', '')[:10], os.path.basename(f)))
                if is_sub and o.get('type') == 'assistant':
                    u = m.get('usage') or {}
                    tot[0] += u.get('input_tokens', 0)
                    tot[1] += u.get('output_tokens', 0)
                    tot[2] += u.get('cache_read_input_tokens', 0)
                    tot[3] += u.get('cache_creation_input_tokens', 0)
                    model = m.get('model') or model
    except Exception as e:
        continue
    if is_sub:
        meta = f[:-6] + '.meta.json'
        if os.path.exists(meta):
            try:
                sub_type = json.load(open(meta, encoding='utf-8')).get('agentType')
            except Exception:
                pass
        agent_usage[sub_type or '?'].append((*tot, model))

out = {'hits': hits, 'agents': {k: v for k, v in agent_usage.items()}}
json.dump(out, open(sys.argv[1], 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('files', len(files), 'hits', len(hits))
for k, v in sorted(agent_usage.items(), key=lambda kv: -len(kv[1]))[:25]:
    print(k, len(v))

