import json, os, glob, collections, statistics as st

ROOT = os.path.expanduser('~/.claude/projects')
P = {'claude-sonnet-5-5': (2, 10, 0.2, 2.5), 'claude-haiku-5-5': (0.1, 0.5, 0.01, 0.125),
     'REDACTED': (0.5, 2.5, 0.05, 0.625), 'claude-opus-5-5': (4, 20, 0.2, 5)}

def cost(u, model):
    i, o = u.get('input_tokens', 0), u.get('output_tokens', 0)
    cr, cw = u.get('cache_read_input_tokens', 0), u.get('cache_creation_input_tokens', 0)
    key = model
    if model == 'claude-haiku-5-5' and i + cr + cw > 100_000:
        key = 'REDACTED'
    p = P.get(key, P['claude-sonnet-5-5'])
    return (i * p[0] + o * p[1] + cr * p[2] + cw * p[3]) / 1e6, o * p[1] / 1e6

def cat(tools):
    if not tools:
        return 'no-tool (reasoning / final report)'
    s = set()
    for t in tools:
        if t.startswith('mcp__'):
            h = t.split('__')[-1]
            s.add('MCP ' + ('GetWhereUsed' if h == 'GetWhereUsed' else 'DDIC read' if h in ('GetTable', 'GetStructure', 'GetDataElement', 'GetDomain', 'GetView', 'GetTypeInfo') else 'source/other read'))
        elif t in ('Write', 'Edit'):
            s.add('Write/Edit (inventory, index)')
        elif t == 'Bash':
            s.add('Bash (scripts)')
        else:
            s.add('local Read/Grep/Glob')
    # one bucket per request: priority order
    for k in ['Write/Edit (inventory, index)', 'MCP GetWhereUsed', 'MCP DDIC read', 'MCP source/other read', 'Bash (scripts)', 'local Read/Grep/Glob']:
        if k in s:
            return k
    return '?'

agg = collections.defaultdict(lambda: [0, 0.0, 0.0])  # turns, cost, outcost
runs = []
for meta in glob.glob(os.path.join(ROOT, '*sc4sap*', '**', 'subagents', '*.meta.json'), recursive=True):
    try:
        if json.load(open(meta, encoding='utf-8')).get('agentType') != 'sc4sap:sap-stocker':
            continue
    except Exception:
        continue
    f = meta[:-10] + '.jsonl'
    reqs = collections.OrderedDict()  # message.id -> {usage, model, tools}
    for line in open(f, encoding='utf-8'):
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get('type') != 'assistant':
            continue
        m = o['message']
        r = reqs.setdefault(m.get('id') or id(o), {'u': m.get('usage') or {}, 'model': m.get('model'), 'tools': []})
        for c in m.get('content') or []:
            if isinstance(c, dict) and c.get('type') == 'tool_use':
                r['tools'].append(c['name'])
    total = 0.0
    for r in reqs.values():
        c, oc = cost(r['u'], r['model'])
        k = cat(r['tools'])
        agg[k][0] += 1; agg[k][1] += c; agg[k][2] += oc
        total += c
    if reqs:
        runs.append((total, len(reqs), next(iter(reqs.values()))['model']))

T = sum(v[1] for v in agg.values())
print('runs', len(runs), 'total $%.2f' % T, 'median/run $%.3f' % st.median([r[0] for r in runs]), 'median turns', st.median([r[1] for r in runs]))
for k, v in sorted(agg.items(), key=lambda kv: -kv[1][1]):
    print(f'{k:38s} turns {v[0]:5d}  cost ${v[1]:7.2f}  {100*v[1]/T:5.1f}%  of which output ${v[2]:.3f}')

