/**
 * Where one account's SAP systems live, and where its sessions run.
 *
 *   <accounts>/<userId>/home/profiles/<alias>/       the account's systems
 *                                                     (its SC4SAP_HOME_DIR)
 *   <accounts>/<userId>/.sc4sap/active-profile.txt   its default system
 *   <accounts>/<userId>/ws/p-<alias>/                 a session's cwd on <alias>
 *   <accounts>/<userId>/ws/scripts                    → this app's scripts/
 *
 * The plugin already reads both halves of a profile from places a session can
 * set: the profile directories from `SC4SAP_HOME_DIR` (bridge, profile CLI,
 * vendor MCP server and hooks all honour it), and which one is live from
 * `<cwd>/.sc4sap/active-profile.txt`, read once when the MCP server starts.
 * So an account gets its own home, and each of its systems its own cwd with
 * the pointer fixed to that system. Two accounts may both call a system
 * `DEV`; one account may run a session on DEV and another on QAS at once; and
 * choosing a different default changes the next session and nothing running.
 *
 * Passwords go to the OS keychain under a service of the account's own, so
 * two accounts with the same alias and SAP user do not share an entry. The
 * plugin parses `keychain:<service>/<account>` at the first `/`, which is why
 * the service is joined with a dot.
 *
 * A caller with no account — a smoke test, a curl — gets the operator's
 * setup exactly as before: `~/.sc4sap` and the one provisioned workspace.
 */
import {
  copyFileSync,
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { APP_SCRIPTS_DIR } from "./run-files.ts";

/** What `SessionManager` and the routes call a caller with no account. */
export const ANONYMOUS = "anonymous";

const ALIAS = /^[A-Za-z0-9_-]{1,64}$/;

/** The workspace files a session cwd copies — see `provision-workspace.ts`. */
const WORKSPACE_SETTINGS = ["settings.json", "settings.local.json"];

export type AccountSpace = {
  userId: string;
  /** `SC4SAP_HOME_DIR` for this account; `undefined` for the operator's own. */
  home: string | undefined;
  /** Where the profile CLI runs. Its pointer is the account's default system. */
  root: string;
  /** OS keychain service the account's SAP passwords are filed under. */
  keychainService: string;
};

export function isAlias(value: unknown): value is string {
  return typeof value === "string" && ALIAS.test(value);
}

/** Every account's folder sits under this, beside the operator's workspace. */
export function accountsRoot(workspace: string): string {
  return resolve(process.env.SC4SAP_ACCOUNTS_DIR ?? join(dirname(workspace), "accounts"));
}

export function accountSpace(workspace: string, userId: string): AccountSpace {
  if (userId === ANONYMOUS) {
    return { userId, home: undefined, root: workspace, keychainService: "sc4sap" };
  }
  const root = join(accountsRoot(workspace), userId);
  return {
    userId,
    home: join(root, "home"),
    root,
    keychainService: `sc4sap-web.${userId}`,
  };
}

/** The profile directories this space reads — its home, or the operator's. */

