/**
 * Plans, prices, and whether an account may start work.
 *
 * Two paid plans, because the cost that matters — Claude usage — can sit with
 * either side:
 *
 *   byok    the account runs on its own Anthropic key (the one `/setup`
 *           already collects). The fee pays for the service, not for tokens.
 *   credit  the account runs on the operator's key with a monthly usage
 *           allowance included; usage past it needs a top-up.
 *
 * How the prices were reached is written up in `docs/pricing.md`. They are
 * VAT-inclusive won, the way a Korean consumer price is shown.
 *
 * Shared by server and client: the billing screen draws these, and the server
 * decides entitlement from the same numbers.
 */

export type PlanId = "byok" | "credit";
export type BillingCycle = "monthly" | "yearly";
export type SubscriptionStatus = "trialing" | "active" | "past_due" | "canceled";

export type Plan = {
  id: PlanId;
  /** VAT-inclusive won. */
  monthly: number;
  /** VAT-inclusive won, billed once a year — two months free. */
  yearly: number;
  /** Claude usage included per month, at list price in USD. 0: the account's own key. */
  includedUsd: number;
};

export const PLANS: Record<PlanId, Plan> = {
  byok: { id: "byok", monthly: 29_000, yearly: 290_000, includedUsd: 0 },
  credit: { id: "credit", monthly: 79_000, yearly: 790_000, includedUsd: 35 },
};

/**
 * First-month price for an account that has never paid: the "your API key"
 * plan, monthly, `won` for its first month and the list price after. Only
 * that plan — on "usage included" the month's allowance alone costs more
 * than this (docs/pricing.md).
 */
export const INTRO = { plan: "byok" as PlanId, cycle: "monthly" as BillingCycle, won: 9_900 } as const;

/** What the first payment for a plan and cycle costs this account. */
export function firstCharge(plan: PlanId, cycle: BillingCycle, introEligible: boolean): number {
  if (introEligible && plan === INTRO.plan && cycle === INTRO.cycle) return INTRO.won;
  return cycle === "monthly" ? PLANS[plan].monthly : PLANS[plan].yearly;
}

/** A top-up for the credit plan: won paid, USD of usage added. */
export const TOP_UP = { won: 10_000, usd: 5 } as const;

/** Free trial, from an account's first session: days, and the usage it may spend on the operator's key. */
export const TRIAL = { days: 7, includedUsd: 3 } as const;

/** What the client is told about an account's subscription. No payment details. */
export type BillingView = {
  /** False while billing is switched off for this deployment — see `billingEnforced`. */
  enforced: boolean;
  /** May start a session now. */
  entitled: boolean;
  plan: PlanId | "trial" | null;
  status: SubscriptionStatus | null;
  /** ISO time the paid or trial period ends; null with no subscription. */
  periodEnd: string | null;
  /** Has never paid, so the first-month price (`INTRO`) applies. */
  introEligible: boolean;
  /** Allowance and use of it, for a metered plan (trial, usage included); null otherwise. */
  usage: { usedUsd: number; allowanceUsd: number } | null;
  /** The allowance is used up: covered, but no new work until it resets or the plan changes. */
  exhausted: boolean;
  /** Cancelled, running to `periodEnd`. */
  canceled: boolean;
  /**
   * Never had a plan or a trial: its trial starts with its first session
   * (`entitledNow`), so it is not asked to pay before it has tried anything.
   */
  trialAvailable: boolean;
};

/** Days a failed renewal is retried before access stops — billing terms 제7조. */
export const RETRY_DAYS = 3;

/**
 * Whether a subscription covers `now`. A cancelled one runs to the end of the
 * period that was paid for, as the billing terms promise (제8조); one whose
 * renewal payment failed keeps working while the payment is retried (제7조).
 */
export function coversNow(
  sub: { status: SubscriptionStatus; currentPeriodEnd: Date } | null | undefined,
  now = new Date(),
): boolean {
  if (!sub) return false;
  const grace = sub.status === "past_due" ? RETRY_DAYS * 24 * 60 * 60 * 1000 : 0;
  return sub.currentPeriodEnd.getTime() + grace > now.getTime();
}

export function formatWon(won: number, locale: string): string {
  return new Intl.NumberFormat(locale, { style: "currency", currency: "KRW" }).format(won);
}
import "server-only";
import { ObjectId } from "mongodb";
import { users, type UserDoc } from "@/lib/mongo";
import { PLANS, TRIAL } from "@/lib/billing";

/**
 * Usage against an allowance — the trial's and the "usage included" plan's.
 *
 * Kept on the subscription itself (`subscription.usage`) rather than summed
 * from the spend ledger at check time: the ledger also holds history from
 * before the plan began, and a check that runs on every new session should
 * be one field read, not an aggregate.
 *
 *   trial   cumulative over the trial — the trial's whole allowance
 *   credit  per calendar month — the billing terms' "매월" — reset when a
 *           cost lands in a new month
 *   byok    not metered: the account's own key, billed by Anthropic
 *
 * Fed by `appendTurns` and `recordRun` with what each save newly cost, at
 * list price (`src/server/pricing.ts`).
 */
export async function meterUsage(userId: string, month: string, usd: number): Promise<void> {
  if (!(usd > 0) || !ObjectId.isValid(userId)) return;
  const col = await users();
  const _id = new ObjectId(userId);
  await col.updateOne(
    { _id, "subscription.plan": "trial" },
    { $inc: { "subscription.usage.usd": usd }, $set: { "subscription.usage.month": month } },
  );
  const same = await col.updateOne(
    { _id, "subscription.plan": "credit", "subscription.usage.month": month },
    { $inc: { "subscription.usage.usd": usd } },
  );
  if (same.matchedCount === 0) {
    await col.updateOne(
      { _id, "subscription.plan": "credit" },
      { $set: { "subscription.usage": { month, usd } } },
    );
  }
}

/** `YYYY-MM` in this server's time zone — the ledger's month, see `monthKey`. */
export function currentMonth(now = new Date()): string {
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
}

/**
 * The allowance and what is used of it, or `null` for a plan that is not
 * metered (or no plan). A credit plan's usage from an earlier month reads as
 * zero: the month has turned and nothing has landed in the new one yet.
 */
export function usageOf(doc: UserDoc, now = new Date()): { usedUsd: number; allowanceUsd: number } | null {
  const sub = doc.subscription;
  if (!sub) return null;
  if (sub.plan === "trial") {
    return { usedUsd: sub.usage?.usd ?? 0, allowanceUsd: TRIAL.includedUsd };
  }
  if (sub.plan === "credit") {
    const used = sub.usage?.month === currentMonth(now) ? sub.usage.usd : 0;
    return { usedUsd: used, allowanceUsd: PLANS.credit.includedUsd };
  }
  return null;
}

