 * session that has only just started.
 *
 * This deletes the stored conversation too. The rail is a list of
 * conversations now, not of running processes, so × means what it means in
 * every other chat list.
 */
const closeSession = async (id: string): Promise<void> => {
  if (closing.current.has(id)) return;
  closing.current.add(id);

  const backend = attached[id] ?? id;
  closed.current.add(backend);
  removedChats.current.add(id);

  setSessions((current) =>
    current.filter((session) => session.id !== backend),
  );
  setChats((current) => current.filter((chat) => chat.id !== id));
  setActiveId((current) => (current === id ? null : current));
  setAttached((current) => {
    const next = { ...current };
    delete next[id];
    return next;
  });

  try {
    await api.closeSession(backend);
  } catch (err) {
    const message = (err as Error).message;
    // 404 is the outcome that was asked for: the session is already gone,
    // whether this tab closed it twice or another one got there first.
    if (!/unknown session/i.test(message)) {
      fail(message);
      closed.current.delete(backend);
    }
  }

  try {
    await api.deleteChat(id);
  } catch (err) {
        heading={sessionsT.deleteHeading(deleting.title ?? sessionsT.newConversation)}
        description={sessionsT.deleteBody}
        confirmLabel={sessionsT.deleteConfirm}
        confirmIcon="trash"
        cancelLabel={sessionsT.cancel}
        onConfirm={() => {
          const id = deleting.id;
          setDeleting(null);
          void closeSession(id);
        }}
        onCancel={() => setDeleting(null)}
      />
    )}

    {deletingMany && (
      <ConfirmModal
        kind={sessionsT.deleteKind}
        heading={sessionsT.deleteManyHeading(deletingMany.length)}
        description={sessionsT.deleteManyBody}
        confirmLabel={sessionsT.deleteConfirm}
        confirmIcon="trash"
        cancelLabel={sessionsT.cancel}
        onConfirm={() => {
          const ids = deletingMany.map((item) => item.id);
          setDeletingMany(null);
          for (const id of ids) void closeSession(id);
        }}
        onCancel={() => setDeletingMany(null)}
      />
    )}

