/**
 * Below `MAX_SESSIONS_PER_ACCOUNT` before a new session opens.
 *
 * Closes the account's longest-idle sessions that nobody is using: idle, no
 * stream open on it, no approval or background task outstanding. A session
 * on screen is never closed — its composer would lock on "closed" until the
 * next list poll. Nothing closable left → `SessionLimitError`.
 */
#makeRoom(userId: string): void {
  const open = [...this.#sessions.values()].filter(
    (live) =>
      live.userId === userId &&
      (live.record.status === "starting" ||
        live.record.status === "idle" ||
        live.record.status === "busy"),
  );
  let excess = open.length - MAX_SESSIONS_PER_ACCOUNT + 1;
  if (excess <= 0) return;
  const closable = open
    .filter(
      (live) =>
        live.record.status === "idle" &&
        live.subscribers.size === 0 &&
        live.pending.size === 0 &&
        live.backgroundTasks.size === 0,
    )
    .sort((a, b) => a.lastActiveAt - b.lastActiveAt);
  if (closable.length < excess) throw new SessionLimitError(MAX_SESSIONS_PER_ACCOUNT);
  for (const live of closable) {
    if (excess-- <= 0) break;
    void this.close(live.record.id);
  }
}

