import "server-only";
import { ObjectId } from "mongodb";
import { users, type UserDoc } from "@/lib/mongo";
import { hashPassword, verifyPassword } from "@/lib/auth/password";
import type { Account } from "@/lib/account";
import { TRIAL, coversNow, type BillingView } from "@/lib/billing";
import { usageOf } from "@/lib/billing-store";
import {
  BILLING_TERMS_VERSION,
  PRIVACY_VERSION,
  TERMS_VERSION,
  type ConsentInput,
} from "@/lib/consent";

/**
 * The user store, and the one place a `UserDoc` turns into the `Account` the
 * screens render.
 *
 * Nothing above this file sees a password hash — `toAccount` is the only exit
 * from the collection, and it does not carry one.
 */

/** The plan every PoC account is on. There is no billing to read it from yet. */
const PLAN = "PoC — bring your own key";

/**
 * Addresses are matched case-insensitively, because nobody thinks of
 * `Kim@corp.com` and `kim@corp.com` as two accounts and the unique index has to
 * agree with that. The address is also stored as typed, and that is the one
 * shown back to the user.
 */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export function toAccount(doc: UserDoc): Account {
  return {
    id: String(doc._id),
    // Family name first, matching the order the sign-up form asks for it in.
    name: `${doc.lastName} ${doc.firstName}`.trim(),
    firstName: doc.firstName,
    email: doc.displayEmail,
    // Neither is collected at sign-up; both are settings-screen material.
    role: null,
    organization: null,
    plan: PLAN,
    memberSince: doc.createdAt.toISOString().slice(0, 10),
    // Rows written before favourites were stored have no field at all.
    favorites: doc.favorites ?? [],
    // The presence of the sub-document, never its contents. See `Account`.
    hasConnection: doc.connection != null,
    // Rows from before the setting existed ask about writes only, which is
    // the level a proof of concept wants and the one the settings screen
    // shows as chosen.
    approval: doc.approval ?? "writes",
    needsConsent:
      doc.consents?.terms !== TERMS_VERSION || doc.consents?.privacy !== PRIVACY_VERSION,
    billing: billingView(doc),
  };
}

/**
 * Billing is off unless `BILLING_ENFORCED=1`: every account is entitled, and
 * the paywall never shows. On by setting the variable once payments are wired
 * to the PG — until then an enforced paywall would lock out every account
 * with nothing it could do about it.
 */
export function billingEnforced(): boolean {
  return process.env.BILLING_ENFORCED === "1";
}

function billingView(doc: UserDoc): BillingView {
  const sub = doc.subscription;
  const enforced = billingEnforced();
  const usage = usageOf(doc);
  const exhausted = usage !== null && usage.usedUsd >= usage.allowanceUsd;
  return {
    enforced,
    entitled: !enforced || (coversNow(sub) && !exhausted),
    usage,
    exhausted,
    canceled: sub?.status === "canceled",
    trialAvailable: enforced && !sub,
    plan: sub?.plan ?? null,
    status: sub?.status ?? null,
    periodEnd: sub ? sub.currentPeriodEnd.toISOString() : null,
    introEligible: !doc.everPaid,
  };
}

export async function updateApproval(
  userId: string,
  approval: "all" | "writes" | "never",
): Promise<boolean> {
  if (!ObjectId.isValid(userId)) return false;
  const result = await (await users()).updateOne(
    { _id: new ObjectId(userId) },
    { $set: { approval } },
  );
  return result.matchedCount === 1;
}

export async function findByEmail(email: string): Promise<UserDoc | null> {
  return (await users()).findOne({ email: normalizeEmail(email) });
}

export async function findById(id: string): Promise<UserDoc | null> {
  if (!ObjectId.isValid(id)) return null;
  return (await users()).findOne({ _id: new ObjectId(id) });
}

/**
 * `duplicate` rather than a thrown error, because two sign-ups racing on the
 * same address is an ordinary outcome, not an exceptional one: the loser is
 * caught by the unique index rather than by the check above it, and both paths
 * have to answer the caller the same way.
 */
export type CreateResult =
  | { ok: true; user: UserDoc }
  | { ok: false; reason: "duplicate" };

export async function createUser(input: {
  lastName: string;
  firstName: string;
  email: string;
  password: string;
  /** The boxes ticked on the form; the route has checked the required ones. */
  consent: ConsentInput;
  /** The invitation code spent on this account. */
  invite: string;
    agreedAt: Date;
    /** 마케팅 정보 수신 — optional, and withdrawable from Settings. */
    marketing: boolean;
    marketingAt: Date | null;
  };
  /**
   * The account's plan — see `lib/billing.ts`. Absent: never subscribed.
   * Written by the billing routes; payment details are the PG's to keep and
   * never land here, only the PG's billing key reference.
   */
  /**
   * Set at the first successful payment and never cleared: the first-month
   * price (`INTRO` in `lib/billing.ts`) is for an account that has never paid.
   */
  everPaid?: boolean;
  /** The invitation code this account was created with — see `lib/invites.ts`. */
  invite?: string;
  subscription?: {
    plan: "trial" | "byok" | "credit";
    cycle: "monthly" | "yearly" | null;
    status: "trialing" | "active" | "past_due" | "canceled";
    startedAt: Date;
    currentPeriodEnd: Date;
    /** The billing terms version agreed before the first payment; null for a trial. */
    billingTerms: string | null;
    /**
     * Usage against the allowance — see `lib/billing-store.ts`. Cumulative for
     * a trial, per calendar month (`month`) for the usage-included plan.
     */
    usage?: { month: string; usd: number };
    /** When the member cancelled; the plan runs to `currentPeriodEnd` and stops. */
  /** ADT base URL — scheme, host and port, no path. */
  adtUrl: string;
  sapUser: string;
  /** AES-256-GCM. Never the password. */
  sapPasswordSealed: string;
  sapVersion: "S4" | "ECC";
  abapRelease: string;
  client: string;
  language: string;
  /** AES-256-GCM. Never the key, and never any part of it. */
  apiKeySealed: string;
  /**
   * The plugin-side scope: industry reference, blocklist profile, and the
   * tables let through it. Stored per account, not yet read by the backend —
   * see `lib/setup.ts`. Optional because rows written before this existed
   * do not have it; readers fall back to the plugin's own defaults.
   */
  industry?: string;
  blocklist?: "minimal" | "standard" | "strict";
  allowTables?: string[];
  /** When setup last completed. Rewritten if it is run again. */

