    usage: { usedUsd: 1.2, allowanceUsd: 3 },
    exhausted: false,
    canceled: false,
    trialAvailable: false,
  };
  switch (state) {
    case "exhausted":
      return {
        ...base,
        plan: "credit",
        status: "active",
        periodEnd: new Date(Date.now() + 12 * DAY).toISOString(),
        usage: { usedUsd: 35, allowanceUsd: 35 },
        exhausted: true,
        introEligible: false,
      };
    case "trial":
      return { ...base, entitled: true, periodEnd: new Date(Date.now() + 4.5 * DAY).toISOString() };
    case "pending":
      return { ...base, plan: null, status: null, periodEnd: null, usage: null, trialAvailable: true };
    case "over":
    default:
      return base;
  }
}

