import assert from "node:assert/strict";
import { sessionsToClose, SessionLimitError } from "../../../../../../../Documents/Projects/sc4sap_project/sc4sap_web/src/server/session-manager.ts";

const s = (id: string, status: "starting" | "idle" | "busy" | "closed" | "error", at: number, inUse = false) =>
  ({ id, status, lastActiveAt: at, inUse });

// Room left
assert.deepEqual(sessionsToClose([], 3), []);
assert.deepEqual(sessionsToClose([s("a", "idle", 1), s("b", "busy", 2)], 3), []);
// Dead sessions do not count
assert.deepEqual(sessionsToClose([s("a", "idle", 1), s("b", "closed", 2), s("c", "error", 3)], 3), []);
// At the limit: oldest idle, not in use, goes
assert.deepEqual(sessionsToClose([s("a", "idle", 5), s("b", "idle", 1), s("c", "busy", 0)], 3), ["b"]);
// On-screen / approval-waiting idle is skipped
assert.deepEqual(sessionsToClose([s("a", "idle", 1, true), s("b", "idle", 9), s("c", "busy", 0)], 3), ["b"]);
// Nothing closable: busy, starting, in use
assert.equal(sessionsToClose([s("a", "busy", 1), s("b", "starting", 2), s("c", "idle", 3, true)], 3), null);
// Over the limit (env lowered): close enough to get one below
assert.deepEqual(sessionsToClose([s("a", "idle", 3), s("b", "idle", 1), s("c", "idle", 2), s("d", "idle", 4)], 2), ["b", "c", "a"]);
// limit 1: every open idle must go
assert.deepEqual(sessionsToClose([s("a", "idle", 2)], 1), ["a"]);
assert.match(new SessionLimitError(3).message, /^3 sessions are already running/);
console.log("cap tests: all passed");

