  if (opensSession) {
    // A new session may pick up an SDK conversation only if it is one of this
    // account's stored chats. The backend can check the sessions it has open;
    // after a restart it has none, and only this side knows whose chat is whose.
    const refusal = await checkResume(auth.account.id, body);
    if (refusal) return refusal;
    // A metered plan's run may not spend past what is left of its allowance:
    // the SDK stops at `maxBudgetUsd`, so one long run cannot overshoot.
    body = capBudget(body, remainingUsd(auth.account));
  }

