  // listing too, so the session it warms has the same shape and is claimed
  // rather than thrown away (`#shapeKey` includes the budget).
  if (targetPath === "/sessions" && request.method === "GET") {
    const remaining = remainingUsd(auth.account);
    if (remaining !== null) headers.set("x-sc4sap-max-budget", String(Math.max(0.01, remaining)));
