import { getAccount } from "@/lib/auth/session";
import { recordConsent } from "@/lib/auth/users";
import { consentComplete, readConsentInput } from "@/lib/consent";

/**
 * `POST /api/consent` — agree to the current terms and privacy notice.
 *
 * Reached from `/consent`, by an account made through Google (which never saw
 * the sign-up form's boxes) or one being asked again after a version bump.
 * `getAccount` rather than a guard: every guard sends an account without
 * consent here, so using one would refuse the request that fixes it.
 *
 * The three required boxes are checked again here; the optional marketing
 * one is recorded as sent.
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  const account = await getAccount();
  if (!account) return Response.json({ error: "Not signed in." }, { status: 401 });

  const body = (await request.json().catch(() => null)) as unknown;
  const input = readConsentInput(body);
  if (!consentComplete(input)) {
    return Response.json(
      { error: "Agree to the terms, the privacy notice and the age statement to continue." },
      { status: 400 },
    );
  }

  try {
    await recordConsent(account.id, input);
  } catch (err) {
    return Response.json(
      { error: `Could not reach the user store: ${(err as Error).message}` },
      { status: 503 },
    );
  }
  return Response.json({ ok: true });
}
