/** The profile directories this space reads — its home, or the operator's. */
export function profilesHome(space: AccountSpace): string {
  return space.home ?? process.env.SC4SAP_HOME_DIR ?? join(homedir(), ".sc4sap");
}

export function hasProfile(space: AccountSpace, alias: string): boolean {
  return isAlias(alias) && existsSync(join(profilesHome(space), "profiles", alias, "sap.env"));
}

/** The account's default system, or `null` when it has none yet. */
export function defaultAlias(space: AccountSpace): string | null {
  const pointer = join(space.root, ".sc4sap", "active-profile.txt");
  if (!existsSync(pointer)) return null;
  const alias = readFileSync(pointer, "utf8").trim();
  return isAlias(alias) ? alias : null;
}

/**
 * Makes another of the account's systems its default.
 *
 * The alias is checked against the list rather than passed through: it reaches
 * a child process argument, and "it exists" is the same check the caller would
 * have to make anyway to give a useful error. The CLI would also refuse an
 * unknown alias — this refuses it without spawning anything.
 *
 * Nothing is closed. A running session keeps the system it started on — its
 * own cwd holds its own pointer — and only sessions opened afterwards without
 * naming a system pick up the new default.
 */
export async function setDefaultProfile(
  pluginPath: string,
  space: AccountSpace,
  alias: string,
): Promise<SwitchOutcome> {
  if (!isAlias(alias)) {
    return { ok: false, error: "alias must match [A-Za-z0-9_-]" };
  }

  const before = await listProfiles(pluginPath, space);
  if (!before.profiles.some((p) => p.alias === alias)) {
    return { ok: false, error: `unknown profile: ${alias}` };
  }

  await cli<{ ok: boolean; active: string }>(pluginPath, space, ["switch", alias]);

  return { ok: true, list: await listProfiles(pluginPath, space) };
}

