/**
 * Removes everything this server holds for one account: each SAP system's
 * password from the OS keychain, then the account's folder — its profiles,
 * its default pointer and every session cwd.
 *
 * For the web app's account deletion (a member leaving, or a year without
 * signing in — see `lib/retention.ts` there). Refused for a space with no
 * home of its own: that is the operator's setup, never an account's.
 *
 * A keychain entry that will not delete is reported and skipped rather than
 * stopping the folder from going: the folder holds the URL and user, and a
 * password left behind under a service no folder points at any more is the
 * smaller leftover.
 */
export async function deleteAccountSpace(
  pluginPath: string,
  space: AccountSpace,
): Promise<{ keychainFailures: string[] }> {
  if (!space.home) throw new Error("refusing to delete the operator's own space");
  const keychainFailures: string[] = [];
  const profilesDir = join(profilesHome(space), "profiles");
  if (existsSync(profilesDir)) {
    for (const alias of readdirSync(profilesDir)) {
      const env = join(profilesDir, alias, "sap.env");
      if (!existsSync(env)) continue;
      const ref = /^SAP_PASSWORD=keychain:(.+)$/m.exec(readFileSync(env, "utf8"))?.[1]?.trim();
      if (!ref) continue;
      // The plugin parses `keychain:<service>/<account>` at the first `/`.
      const slash = ref.indexOf("/");
      if (slash <= 0) continue;
      try {
        await cliJson(pluginPath, space, ["keychain-delete"], {
          service: ref.slice(0, slash),
          account: ref.slice(slash + 1),
        });
      } catch (err) {
        keychainFailures.push(`${alias}: ${(err as Error).message}`);
      }
    }
  }
  rmSync(space.root, { recursive: true, force: true });
  return { keychainFailures };
}
