import "server-only";
import { ObjectId } from "mongodb";
import { BACKEND } from "@/lib/backend";
import { sendMail, type Mail } from "@/lib/mail";
import {
  chatMessages,
  chats,
  projects,
  resets,
  retainedRecords,
  runSpend,
  sessions,
  spendMonths,
  toolCalls,
  users,
  type UserDoc,
} from "@/lib/mongo";

/**
 * What the privacy policy promises about time, done once a day.
 *
 *   inactive accounts  a year after the last sign-in or use (`lastSeenAt`,
 *                      else `createdAt`) the account is deleted; 30 days
 *                      before, its member is told by e-mail. Using the app in
 *                      between clears the notice (`touchSeen`).
 *   marketing consent  every two years from the opt-in, the member is told
 *                      that they are opted in and how to opt out
 *                      (「정보통신망법」 제50조 제8항, 시행령 제62조의3).
 *
 * Run by `POST /api/cron/retention` — see that route for how it is called.
 * Every step is idempotent: a run that dies halfway is finished by the next.
 */

const DAY_MS = 24 * 60 * 60 * 1000;
export const INACTIVE_DAYS = 365;
export const NOTICE_DAYS = 30;
const MARKETING_DAYS = 2 * 365;
/** 「전자상거래법」 제6조: contract and payment records, 5 years. */
const RETAIN_YEARS = 5;

export type RetentionReport = {
  noticed: number;
  deleted: number;
  marketingReminded: number;
  purgedRecords: number;
  failures: string[];
};

export async function runRetention(now = new Date()): Promise<RetentionReport> {
  const report: RetentionReport = { noticed: 0, deleted: 0, marketingReminded: 0, purgedRecords: 0, failures: [] };
  const col = await users();
  const idleSince = new Date(now.getTime() - (INACTIVE_DAYS - NOTICE_DAYS) * DAY_MS);
  const goneSince = new Date(now.getTime() - INACTIVE_DAYS * DAY_MS);
  const noticedBefore = new Date(now.getTime() - NOTICE_DAYS * DAY_MS);
  // The last sign-in, or the sign-up for a row from before it was kept.
  const lastUse = (since: Date) => ({
    $or: [{ lastSeenAt: { $lte: since } }, { lastSeenAt: { $exists: false }, createdAt: { $lte: since } }],
  });

  // Delete first, so an account noticed today is never also deleted today.
  for (const doc of await col
    .find({ ...lastUse(goneSince), dormantNoticeAt: { $lte: noticedBefore } })
    .toArray()) {
    try {
      await deleteAccount(doc, "inactive", now);
      report.deleted += 1;
    } catch (err) {
      report.failures.push(`delete ${String(doc._id)}: ${(err as Error).message}`);
    }
  }

  for (const doc of await col.find({ ...lastUse(idleSince), dormantNoticeAt: { $exists: false } }).toArray()) {
    const deleteOn = new Date(Math.max(now.getTime(), lastUseOf(doc).getTime() + INACTIVE_DAYS * DAY_MS) + DAY_MS);
    const sent = await sendMail(inactivityMail(doc, deleteOn));
    if ("error" in sent) {
      // Not marked: deleting an account whose notice never left would break
      // the promise the notice exists to keep. Tried again tomorrow.
      report.failures.push(`notice ${String(doc._id)}: ${sent.error}`);
      continue;
    }
    await col.updateOne({ _id: doc._id }, { $set: { dormantNoticeAt: now } });
    report.noticed += 1;
  }

  const remindBefore = new Date(now.getTime() - MARKETING_DAYS * DAY_MS);
  for (const doc of await col
    .find({
      "consents.marketing": true,
      "consents.marketingAt": { $lte: remindBefore },
      $or: [{ marketingNoticeAt: { $exists: false } }, { marketingNoticeAt: { $lte: remindBefore } }],
    })
    .toArray()) {
    const sent = await sendMail(marketingMail(doc));
    if ("error" in sent) {
      report.failures.push(`marketing ${String(doc._id)}: ${sent.error}`);
      continue;
    }
    await col.updateOne({ _id: doc._id }, { $set: { marketingNoticeAt: now } });
    report.marketingReminded += 1;
  }

  report.purgedRecords = (await (await retainedRecords()).deleteMany({ purgeAfter: { $lte: now } })).deletedCount;
  return report;
}

function lastUseOf(doc: UserDoc): Date {
  return doc.lastSeenAt ?? doc.createdAt;
}

/**
 * Deletes one account: the backend's copy first (sessions, SAP passwords,
 * account folder), then every row here. A backend that cannot be reached
 * stops the deletion — the rows are what would let it be retried.
 *
 * An account that ever paid leaves one `retained_records` row with who it was
 * and its subscription, for the period the law requires; nothing else.
 */
export async function deleteAccount(
  doc: UserDoc,
  reason: "inactive" | "member",
  now = new Date(),
): Promise<void> {
  if (!doc._id) throw new Error("no id");
  const userId = String(doc._id);

  const response = await fetch(`${BACKEND}/account`, {
    method: "DELETE",
    headers: { "x-sc4sap-user": userId },
    cache: "no-store",
  });
  if (!response.ok) throw new Error(`backend answered ${response.status}`);

  if (doc.everPaid) {
    const purgeAfter = new Date(now);
    purgeAfter.setFullYear(purgeAfter.getFullYear() + RETAIN_YEARS);
    await (await retainedRecords()).insertOne({
      userId,
      email: doc.email,
      name: `${doc.lastName} ${doc.firstName}`.trim(),
      subscription: doc.subscription ?? null,
      deletedAt: now,
      purgeAfter,
      reason,
    });
  }

  const chatIds = (await (await chats()).find({ userId }, { projection: { _id: 1 } }).toArray()).map((c) =>
    String(c._id),
  );
  await (await chatMessages()).deleteMany({ $or: [{ userId }, { chatId: { $in: chatIds } }] });
  await (await chats()).deleteMany({ userId });
  await (await projects()).deleteMany({ userId });
  await (await toolCalls()).deleteMany({ userId });
  await (await runSpend()).deleteMany({ userId });
  await (await spendMonths()).deleteMany({ userId });
  await (await sessions()).deleteMany({ userId });
  await (await resets()).deleteMany({ $or: [{ userId }, { email: doc.email }] });
  await (await users()).deleteOne({ _id: new ObjectId(userId) });
}

const date = (d: Date): string =>
  new Intl.DateTimeFormat("ko-KR", { dateStyle: "long", timeZone: "Asia/Seoul" }).format(d);

function inactivityMail(doc: UserDoc, deleteOn: Date): Mail {
  const text = [
    `${doc.lastName}${doc.firstName}님, 안녕하세요. SC4SAP입니다.`,
    "",
    "회원님의 계정은 1년 가까이 이용 기록이 없습니다.",
    `${date(deleteOn)}까지 로그인하지 않으시면 계정을 삭제합니다.`,
    "삭제하면 대화 기록, 프로젝트, SAP 접속 정보가 모두 지워지고 되돌릴 수 없습니다.",
    "법령에 따라 보관해야 하는 계약·결제 기록은 그 기간 동안만 따로 보관합니다.",
    "",
    "계속 쓰시려면 그 전에 한 번 로그인해 주세요. 로그인하면 이 안내는 취소됩니다.",
  ].join("\n");
  return { to: doc.displayEmail, subject: "[SC4SAP] 1년 미이용 계정 삭제 예정 안내", text, html: htmlOf(text) };
}

function marketingMail(doc: UserDoc): Mail {
  const since = doc.consents?.marketingAt ? date(doc.consents.marketingAt) : "";
  const text = [
    `${doc.lastName}${doc.firstName}님, 안녕하세요. SC4SAP입니다.`,
    "",
    `회원님은 ${since}부터 SC4SAP 제품 소식 이메일 수신에 동의하셨습니다.`,
    "법에 따라 2년마다 수신 동의 여부를 알려 드립니다.",
    "계속 받으시려면 아무것도 하지 않으셔도 됩니다.",
    "더 받고 싶지 않으시면 설정 → 요금제와 알림에서 언제든 수신을 끌 수 있습니다.",
  ].join("\n");
  return { to: doc.displayEmail, subject: "[SC4SAP] 광고성 정보 수신 동의 확인 안내", text, html: htmlOf(text) };
}

function htmlOf(text: string): string {
  const escaped = text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return `<div style="font-family:sans-serif;font-size:14px;line-height:1.6">${escaped.replace(/\n/g, "<br>")}</div>`;
}

