/**
 * What the privacy policy promises about time, done once a day.
 *
 *   inactive accounts  a year after the last sign-in or use (`lastSeenAt`,
 *                      else `createdAt`) the account is deleted; 30 days
 *                      before, its member is told by e-mail. Using the app in
 *                      between clears the notice (`touchSeen`).
 *   marketing consent  every two years from the opt-in, the member is told
 *                      that they are opted in and how to opt out
 *                      (「정보통신망법」 제50조 제8항, 시행령 제62조의3).
 *
 * Run by `POST /api/cron/retention` — see that route for how it is called.
 * Every step is idempotent: a run that dies halfway is finished by the next.
 */

const DAY_MS = 24 * 60 * 60 * 1000;
export const INACTIVE_DAYS = 365;
export const NOTICE_DAYS = 30;
const MARKETING_DAYS = 2 * 365;
/** 「전자상거래법」 제6조: contract and payment records, 5 years. */
const RETAIN_YEARS = 5;

export type RetentionReport = {
  noticed: number;
  deleted: number;
  marketingReminded: number;
  purgedRecords: number;
  failures: string[];
};

export async function runRetention(now = new Date()): Promise<RetentionReport> {
  const report: RetentionReport = { noticed: 0, deleted: 0, marketingReminded: 0, purgedRecords: 0, failures: [] };
  const col = await users();
  const idleSince = new Date(now.getTime() - (INACTIVE_DAYS - NOTICE_DAYS) * DAY_MS);
  const goneSince = new Date(now.getTime() - INACTIVE_DAYS * DAY_MS);
  const noticedBefore = new Date(now.getTime() - NOTICE_DAYS * DAY_MS);
  // The last sign-in, or the sign-up for a row from before it was kept.
  const lastUse = (since: Date) => ({
    $or: [{ lastSeenAt: { $lte: since } }, { lastSeenAt: { $exists: false }, createdAt: { $lte: since } }],
  });

  // Delete first, so an account noticed today is never also deleted today.
  for (const doc of await col
    .find({ ...lastUse(goneSince), dormantNoticeAt: { $lte: noticedBefore } })
    .toArray()) {
    try {
      await deleteAccount(doc, "inactive", now);
      report.deleted += 1;
    } catch (err) {
      report.failures.push(`delete ${String(doc._id)}: ${(err as Error).message}`);
    }
  }

  for (const doc of await col.find({ ...lastUse(idleSince), dormantNoticeAt: { $exists: false } }).toArray()) {
    const deleteOn = new Date(Math.max(now.getTime(), lastUseOf(doc).getTime() + INACTIVE_DAYS * DAY_MS) + DAY_MS);
    const sent = await sendMail(inactivityMail(doc, deleteOn));
    if ("error" in sent) {
      // Not marked: deleting an account whose notice never left would break
      // the promise the notice exists to keep. Tried again tomorrow.
      report.failures.push(`notice ${String(doc._id)}: ${sent.error}`);
      continue;
    }
    await col.updateOne({ _id: doc._id }, { $set: { dormantNoticeAt: now } });
    report.noticed += 1;
  }

  const remindBefore = new Date(now.getTime() - MARKETING_DAYS * DAY_MS);
  for (const doc of await col
    .find({
      "consents.marketing": true,
      "consents.marketingAt": { $lte: remindBefore },
      $or: [{ marketingNoticeAt: { $exists: false } }, { marketingNoticeAt: { $lte: remindBefore } }],
    })
    .toArray()) {
    const sent = await sendMail(marketingMail(doc));
    if ("error" in sent) {
      report.failures.push(`marketing ${String(doc._id)}: ${sent.error}`);
      continue;
    }
    await col.updateOne({ _id: doc._id }, { $set: { marketingNoticeAt: now } });
    report.marketingReminded += 1;
  }

  report.purgedRecords = (await (await retainedRecords()).deleteMany({ purgeAfter: { $lte: now } })).deletedCount;
  return report;
}

