import { timingSafeEqual } from "node:crypto";
import { runRetention } from "@/lib/retention";

/**
 * `POST /api/cron/retention` — the daily retention run (`lib/retention.ts`).
 *
 * Not behind a sign-in: a scheduler calls it, with `Authorization: Bearer
 * <CRON_SECRET>`. Without `CRON_SECRET` set it answers 503 — an endpoint that
 * deletes accounts must not be reachable with an empty secret. Run it once a
 * day with `npm run retention` (scripts/retention.mjs) from Task Scheduler or
 * cron; more often is harmless, every step is idempotent.
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function authorised(header: string | null): boolean {
  const secret = process.env.CRON_SECRET;
  if (!secret || !header?.startsWith("Bearer ")) return false;
  const given = Buffer.from(header.slice("Bearer ".length));
  const wanted = Buffer.from(secret);
  return given.length === wanted.length && timingSafeEqual(given, wanted);
}

export async function POST(request: Request): Promise<Response> {
  if (!process.env.CRON_SECRET) {
    return Response.json({ error: "CRON_SECRET is not set." }, { status: 503 });
  }
  if (!authorised(request.headers.get("authorization"))) {
    return Response.json({ error: "Not allowed." }, { status: 401 });
  }
  return Response.json(await runRetention());
}
EOF
cat > scripts/retention.mjs <<'EOF'
#!/usr/bin/env node
/**
 * Runs the daily retention job: `POST /api/cron/retention` on this app.
 *
 *   npm run retention            against http://localhost:3000
 *   APP_URL=https://… npm run retention
 *
 * Reads CRON_SECRET from the environment or from web/.env.local. Schedule it
 * once a day (Windows Task Scheduler, cron). Prints the report; exits 1 when
 * the run failed or reported failures.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function fromEnvFile(name) {
  try {
    const text = readFileSync(join(dirname(fileURLToPath(import.meta.url)), "..", ".env.local"), "utf8");
    const line = text.split(/\r?\n/).find((l) => l.startsWith(`${name}=`));
    return line ? line.slice(name.length + 1).trim().replace(/^["']|["']$/g, "") : undefined;
  } catch {
    return undefined;
  }
}

const secret = process.env.CRON_SECRET ?? fromEnvFile("CRON_SECRET");
if (!secret) {
  console.error("CRON_SECRET is not set (environment or web/.env.local).");
  process.exit(1);
}
const base = process.env.APP_URL ?? "http://localhost:3000";
const response = await fetch(`${base}/api/cron/retention`, {
  method: "POST",
  headers: { authorization: `Bearer ${secret}` },
});
const body = await response.json().catch(() => null);
console.log(JSON.stringify(body, null, 2));
process.exit(response.ok && body && body.failures?.length === 0 ? 0 : 1);
EOF
