import { apiSignedIn } from "@/lib/auth/api-guard";
import { PLANS, chargeFor, type BillingCycle, type PlanId } from "@/lib/billing";

/**
 * `POST /api/billing/checkout` — start paying for a plan.
 *
 * Body: `{ plan, cycle, agree }`. `agree` is the billing-terms box on the
 * billing screen; a payment without it is refused, because the terms have to
 * be shown and agreed before the order (「전자상거래법」 제13조·제14조).
 *
 * Not wired to the payment provider yet. Toss Payments' card billing (빌링)
 * will be: issue a billing key through its widget with the customer key
 * `sc4sap-<account id>`, confirm it here with `TOSS_SECRET_KEY`, charge the
 * first period, then store `subscription` on the user row with the billing
 * key reference — never a card number. Until `TOSS_SECRET_KEY` is set this
 * answers 501 with `notReady: true`, which the screen explains.
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const CYCLES: BillingCycle[] = ["monthly", "yearly"];

export async function POST(request: Request): Promise<Response> {
  const auth = await apiSignedIn();
  if ("response" in auth) return auth.response;
  if (auth.account.needsConsent) {
    return Response.json({ error: "Agree to the current terms first." }, { status: 403 });
  }

  const body = (await request.json().catch(() => null)) as
    | { plan?: unknown; cycle?: unknown; agree?: unknown }
    | null;
  const plan = body?.plan;
  const cycle = body?.cycle;
  if (typeof plan !== "string" || !Object.hasOwn(PLANS, plan)) {
    return Response.json({ error: "Unknown plan." }, { status: 400 });
  }
  if (!CYCLES.includes(cycle as BillingCycle)) {
    return Response.json({ error: "Unknown billing cycle." }, { status: 400 });
  }
  if (body?.agree !== true) {
    return Response.json({ error: "Agree to the Paid Service Terms first." }, { status: 400 });
  }

