// Throwaway check of lib/retention.ts against the dev database, synthetic rows only.
import assert from "node:assert/strict";
import { ObjectId } from "mongodb";
import { chatMessages, chats, retainedRecords, users } from "./src/lib/mongo";
import { runRetention } from "./src/lib/retention";

const DAY = 864e5;
const now = new Date();
const ago = (d: number) => new Date(now.getTime() - d * DAY);
const base = (n: number) => ({
  _id: new ObjectId(),
  email: `retention-test-${n}@example.test`,
  displayEmail: `retention-test-${n}@example.test`,
  lastName: "테스트",
  firstName: String(n),
  passwordHash: "x",
});
const u1 = { ...base(1), createdAt: ago(400) }; // never seen, no notice → notice
const u2 = { ...base(2), createdAt: ago(500), lastSeenAt: ago(400), dormantNoticeAt: ago(31), everPaid: true }; // → delete
const u3 = { ...base(3), createdAt: ago(900), lastSeenAt: ago(5), consents: { terms: "x", privacy: "x", age: true, agreedAt: ago(800), marketing: true, marketingAt: ago(800), overseas: true } }; // → reminder
const u4 = { ...base(4), createdAt: ago(400), lastSeenAt: ago(10) }; // untouched
const all = [u1, u2, u3, u4];

const col = await users();
await col.insertMany(all as never[]);
const chatId = new ObjectId();
await (await chats()).insertOne({ _id: chatId, userId: String(u2._id), title: "t", createdAt: now, updatedAt: now } as never);
await (await chatMessages()).insertOne({ chatId: String(chatId), userId: String(u2._id), seq: 0, role: "user", text: "t", at: now } as never);

try {
  const report = await runRetention(now);
  console.log(JSON.stringify(report));
  assert.equal(report.failures.length, 0, report.failures.join("; "));
  assert.ok((await col.findOne({ _id: u1._id }))?.dormantNoticeAt, "u1 noticed");
  assert.equal(await col.findOne({ _id: u2._id }), null, "u2 deleted");
  assert.equal(await (await chats()).countDocuments({ userId: String(u2._id) }), 0, "u2 chats gone");
  assert.equal(await (await chatMessages()).countDocuments({ userId: String(u2._id) }), 0, "u2 messages gone");
  const kept = await (await retainedRecords()).findOne({ userId: String(u2._id) });
  assert.ok(kept && kept.purgeAfter.getFullYear() === now.getFullYear() + 5, "u2 retained record, 5 years");
  assert.ok((await col.findOne({ _id: u3._id }))?.marketingNoticeAt, "u3 reminded");
  const four = await col.findOne({ _id: u4._id });
  assert.ok(four && !four.dormantNoticeAt, "u4 untouched");
  // A second run changes nothing: idempotent.
  const again = await runRetention(now);
  assert.deepEqual([again.noticed, again.deleted, again.marketingReminded], [0, 0, 0]);
  console.log("retention checks: all passed");
} finally {
  await col.deleteMany({ email: /^retention-test-\d@example\.test$/ });
  await (await chats()).deleteMany({ userId: String(u2._id) });
  await (await chatMessages()).deleteMany({ userId: String(u2._id) });
  await (await retainedRecords()).deleteMany({ email: /^retention-test-\d@example\.test$/ });
  process.exit(0);
}

