// Throwaway check of lib/retention.ts against the dev database, synthetic rows only.
import assert from "node:assert/strict";
import { ObjectId } from "mongodb";
import { chatMessages, chats, retainedRecords, users } from "./src/lib/mongo.ts";
import { runRetention } from "./src/lib/retention.ts";

const DAY = 864e5;
const now = new Date();
const ago = (d: number) => new Date(now.getTime() - d * DAY);
const base = (n: number) => ({
  _id: new ObjectId(),
  email: `retention-test-${n}@example.test`,
  displayEmail: `retention-test-${n}@example.test`,
  lastName: "테스트",
  firstName: String(n),
  passwordHash: "x",
});
const u1 = { ...base(1), createdAt: ago(400) };
const u2 = { ...base(2), createdAt: ago(500), lastSeenAt: ago(400), dormantNoticeAt: ago(31), everPaid: true };
const u3 = { ...base(3), createdAt: ago(900), lastSeenAt: ago(5), consents: { terms: "x", privacy: "x", age: true, agreedAt: ago(800), marketing: true, marketingAt: ago(800), overseas: true } };
const u4 = { ...base(4), createdAt: ago(400), lastSeenAt: ago(10) };
const u5 = { ...base(5), createdAt: ago(500), lastSeenAt: ago(400), dormantNoticeAt: ago(40), subscription: { plan: "credit", cycle: "monthly", status: "active", startedAt: ago(20), currentPeriodEnd: new Date(now.getTime() + 10 * DAY), billingTerms: "x" } };

const col = await users();
await col.insertMany([u1, u2, u3, u4, u5] as never[]);
const chatId = new ObjectId();
await (await chats()).insertOne({ _id: chatId, userId: String(u2._id), title: "t", createdAt: now, updatedAt: now } as never);
await (await chatMessages()).insertOne({ chatId: String(chatId), userId: String(u2._id), seq: 0, role: "user", text: "t", at: now } as never);

let ok = false;
try {
  const report = await runRetention(now);
  console.log(JSON.stringify(report));
  assert.equal(report.failures.length, 0, report.failures.join("; "));
  assert.ok((await col.findOne({ _id: u1._id }))?.dormantNoticeAt, "u1 noticed");
  assert.equal(await col.findOne({ _id: u2._id }), null, "u2 deleted");
  assert.equal(await (await chatMessages()).countDocuments({ userId: String(u2._id) }), 0, "u2 messages gone");
  assert.equal(await (await retainedRecords()).countDocuments({ userId: String(u2._id) }), 1, "one retained record");
  assert.ok((await col.findOne({ _id: u3._id }))?.marketingNoticeAt, "u3 reminded");
  assert.ok(!(await col.findOne({ _id: u4._id }))?.dormantNoticeAt, "u4 untouched");
  assert.ok(await col.findOne({ _id: u5._id }), "u5 paying, kept");
  const again = await runRetention(now);
  assert.deepEqual([again.noticed, again.deleted, again.marketingReminded], [0, 0, 0], "second run idempotent");
  console.log("retention checks: all passed");
  ok = true;
} finally {
  await col.deleteMany({ email: /^retention-test-\d@example\.test$/ });
  await (await chats()).deleteMany({ userId: String(u2._id) });
  await (await chatMessages()).deleteMany({ userId: String(u2._id) });
  await (await retainedRecords()).deleteMany({ email: /^retention-test-\d@example\.test$/ });
  console.log("synthetic rows removed");
  process.exit(ok ? 0 : 1);
}

