1	"use client";
2	
3	/**
4	 * Who this account is, and the two things about it that can be changed.
5	 *
6	 * An identity card first, then rows. The card is the answer to the question
7	 * most visits to this screen are actually asking — which account am I in — and
8	 * it is a card rather than a first row because a name and an address are read
9	 * as a person, not as two settings.
10	 *
11	 * Nothing below it is a live input. These are read far more often than they
12	 * are changed, and a form of open fields answers "what is my name" while
13	 * asking "is this a value, or a value I am in the middle of changing". The
14	 * pencil is what says the row can move.
15	 *
16	 * Email is shown and has no pencil. It is the unique key every session, reset
17	 * and Google link hangs off, so changing it is a flow of its own — verify the
18	 * new address before it becomes the one that can receive a reset — rather than
19	 * a field on a form. What it carries instead is the mark of whoever vouches
20	 * for it: Google’s, or ours.
21	 *
22	 * The password row has no pencil on an account that has no password. That is
23	 * every Google account, which is the case worth naming — there is nothing to
24	 * change, and a control that opened a dialog to say so would be a control that
25	 * does nothing. Written as "has a password" rather than "is not Google"
26	 * because an account can be both, and that one keeps its pencil.
27	 */
28	import { useRouter } from "next/navigation";
29	import { useState } from "react";
30	import { GoogleMark } from "@/components/GoogleMark";
31	import { Icon } from "@/components/Icon";
32	import { Sc4Mark } from "@/components/Sc4Mark";
33	import { EditButton, EditModal, SettingRow } from "@/components/settings/EditModal";
34	import { isPasswordValid } from "@/lib/password";
35	import { useLocale } from "@/lib/i18n/client";
36	import type { Messages } from "@/lib/i18n/messages";
37	
38	/** What an `/api/account/*` route answers with when it refuses. */
39	type Refusal = { error?: string; field?: string };
40	
41	async function send(
42	  url: string,
43	  method: "POST" | "PATCH",
44	  body: Record<string, unknown>,
45	  serverAnswered: (status: number) => string,
46	): Promise<Refusal | null> {
47	  const response = await fetch(url, {
48	    method,
49	    headers: { "Content-Type": "application/json" },
50	    body: JSON.stringify(body),
51	  });
52	  if (response.ok) return null;
53	  // A refusal that is not JSON is still a refusal; the status is what is
54	  // certain, so it carries the message when the body cannot.
55	  return (
56	    ((await response.json().catch(() => null)) as Refusal | null) ?? {
57	      error: serverAnswered(response.status),
58	    }
59	  );
60	}
61	
62	export function AccountSettings({
63	  lastName: storedLast,
64	  firstName: storedFirst,
65	  email,
66	  memberSince,
67	  hasPassword,
68	  isGoogle,
69	}: {
70	  lastName: string;
71	  firstName: string;
72	  email: string;
73	  memberSince: string;
74	  hasPassword: boolean;
75	  /** The row has been linked to a Google account. */
76	  isGoogle: boolean;
77	}) {
78	  const router = useRouter();
79	  const { t: messages } = useLocale();
80	  const t = messages.settings;
81	  const [editing, setEditing] = useState<"name" | "password" | null>(null);
82	  // Held here rather than in the row, so the confirmation survives the dialog
83	  // that produced it closing.
84	  const [done, setDone] = useState<"name" | "password" | null>(null);
85	
86	  const name = `${storedLast} ${storedFirst}`.trim();
87	
88	  return (
89	    <section className="panel">
90	      <div className="identity">
91	        {/* Round, like the one in the account menu, and for the same reason:
92	            this slot stands for a person rather than a control. */}
93	        <span className="identity-avatar" aria-hidden="true">
94	          <Icon name="user" />
95	        </span>
96	        <div className="identity-main">
97	          <p className="identity-name">{name || t.unnamed}</p>
98	          <p className="identity-email">{email}</p>
99	        </div>
100	      </div>
101	
102	      <div className="setting-rows">
103	        <SettingRow
104	          label={t.name}
105	          value={name || t.notSet}
106	          hint={done === "name" ? t.saved : t.memberSince(memberSince)}
107	          action={
108	            <EditButton label={t.editName} onClick={() => setEditing("name")} />
109	          }
110	        />
111	
112	        <SettingRow
113	          label={t.password}
114	          // Never the length of the real one: a mask that matched it would be
115	          // telling anyone reading over a shoulder how long it is.
116	          value={hasPassword ? "••••••••••" : t.notSet}
117	          hint={
118	            done === "password"
119	              ? t.passwordChanged
120	              : hasPassword
121	                ? t.passwordHint
122	                : t.noPassword
123	          }
124	          action={
125	            hasPassword ? (
126	              <EditButton
127	                label={t.changePassword}
128	                onClick={() => setEditing("password")}
129	              />
130	            ) : undefined
131	          }
132	        />
133	
134	        <SettingRow
135	          label={t.email}
136	          value={email}
137	          hint={t.emailHint}
138	          // Whose account this is, in the one slot the row has for it. Centred
139	          // against the value rather than the label, which is where the pencil
140	          // on the rows above sits.
141	          action={
142	            <span className="setting-mark" aria-hidden="true">
143	              {isGoogle ? <GoogleMark /> : <Sc4Mark className="setting-sc4" />}
144	            </span>
145	          }
146	        />
147	      </div>
148	
149	      {editing === "name" && (
150	        <NameDialog
151	          t={t}
152	          lastName={storedLast}
153	          firstName={storedFirst}
154	          onDone={() => {
155	            setEditing(null);
156	            setDone("name");
157	            // The rail and the dashboard both draw this name from the server's
158	            // copy of the account, which the state above does not touch.
159	            router.refresh();
160	          }}
