cd /c/Users/pssps/Documents/Projects/sc4sap_project/sc4sap_web/web/src; mkdir -p app/api/account/delete; cat > app/api/account/delete/route.ts <<'EOF'
import { findById } from "@/lib/auth/users";
import { verifyPassword } from "@/lib/auth/password";
import { endSession } from "@/lib/auth/session";
import { deleteAccount } from "@/lib/retention";
import { jsonError, readJson, readSecret, readString, signedIn } from "../shared";

/**
 * `POST /api/account/delete` — the member deletes their own account (탈퇴).
 *
 * Proof first, as for a password change: a signed-in tab is not the owner at
 * the keyboard. An account with a password types it; one without (Google)
 * types its own e-mail address, which at least says it was meant.
 *
 * Then the same deletion the inactivity job runs (`deleteAccount`): the
 * backend's sessions, SAP passwords and folder, then every row here; an
 * account that ever paid keeps only the record the law requires. A running
 * plan simply ends with it — refunds are asked for separately, as the Refund
 * Policy says, and the dialog says so before the button.
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  const auth = await signedIn();
  if ("response" in auth) return auth.response;

  const body = await readJson(request);
  if (!body) return jsonError(400, "Expected a JSON object.");

  const doc = await findById(auth.account.id);
  if (!doc) return jsonError(404, "That account no longer exists.");

  if (doc.passwordHash) {
    const password = readSecret(body, "password");
    if (!password) return jsonError(400, "Enter your password.", "password");
    if (!(await verifyPassword(password, doc.passwordHash))) {
      return jsonError(400, "That is not your password.", "password");
    }
  } else if (readString(body, "email").toLowerCase() !== doc.email) {
    return jsonError(400, "Type your e-mail address exactly as shown.", "email");
  }

  try {
    await deleteAccount(doc, "member");
  } catch (err) {
    // Nothing of the rows is gone yet when the backend refuses, so the
    // member can simply try again.
    return jsonError(503, `The account could not be deleted: ${(err as Error).message}`);
  }
  await endSession();
  return Response.json({ ok: true });
}
EOF
