  } else if (readString(body, "email").toLowerCase() !== doc.email) {
    return jsonError(400, "Type your e-mail address exactly as shown.", "email");
  }

  try {
    await deleteAccount(doc, "member");
  } catch (err) {
    // Nothing of the rows is gone yet when the backend refuses, so the
    // member can simply try again.
    return jsonError(503, `The account could not be deleted: ${(err as Error).message}`);
  }
  await endSession();
  return Response.json({ ok: true });
}
