/**
 * The last step before deletion: the password for an account that has one,
 * the e-mail address typed out for one that does not. The server checks the
 * same thing again (`/api/account/delete`).
 */
function DeleteDialog({
  t,
  email,
  hasPassword,
  onDone,
  onCancel,
}: {
  t: Messages["settings"];
  email: string;
  hasPassword: boolean;
  onDone: () => void;
  onCancel: () => void;
}) {
  const [proof, setProof] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<Refusal | null>(null);

  const complete = hasPassword ? proof !== "" : proof.trim().toLowerCase() === email.toLowerCase();

  async function remove(): Promise<void> {
    setBusy(true);
    setError(null);
    const refusal = await send(
      "/api/account/delete",
      "POST",
      hasPassword ? { password: proof } : { email: proof.trim() },
      t.serverAnswered,
    );
    if (refusal) {
      setBusy(false);
      setError(refusal);
      return;
    }
    onDone();
  }

  return (
    <EditModal
      kind={t.deleteKind}
      heading={t.deleteHeading}
      description={t.deleteBody}
      submitLabel={t.deleteSubmit}
      busy={busy}
      disabled={!complete}
      error={error?.error ?? null}
      onSubmit={() => void remove()}
      onCancel={onCancel}
    >
      <label className="field field-wide">
        <span className="field-label">{hasPassword ? t.deletePassword : t.deleteEmail(email)}</span>
        <input
          type={hasPassword ? "password" : "email"}
          value={proof}
          onChange={(event) => setProof(event.target.value)}
          className={error ? "is-invalid" : undefined}
          autoComplete={hasPassword ? "current-password" : "off"}
          disabled={busy}
        />
      </label>
    </EditModal>
  );
}
