// Throwaway end-to-end check of POST /api/account/delete, synthetic account only.
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { ObjectId } from "mongodb";
import { chats, sessions, users } from "./src/lib/mongo.ts";
import { hashPassword } from "./src/lib/auth/password.ts";

const email = "delete-test@example.test";
const password = randomBytes(12).toString("base64url");
const token = randomBytes(32).toString("base64url");
const _id = new ObjectId();
const now = new Date();
const col = await users();
await col.insertOne({
  _id, email, displayEmail: email, lastName: "테스트", firstName: "탈퇴",
  passwordHash: await hashPassword(password), createdAt: now,
  consents: { terms: "old", privacy: "old", age: true, agreedAt: now, marketing: false, marketingAt: null },
} as never);
await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(token).digest("hex"), userId: String(_id), createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
await (await chats()).insertOne({ userId: String(_id), title: "t", createdAt: now, updatedAt: now } as never);

const call = (body: unknown) =>
  fetch("http://localhost:3000/api/account/delete", {
    method: "POST",
    headers: { "content-type": "application/json", cookie: `sc4sap_session=${token}` },
    body: JSON.stringify(body),
  });
let ok = false;
try {
  const wrong = await call({ password: "not-it" });
  assert.equal(wrong.status, 400, "wrong password refused");
  assert.ok(await col.findOne({ _id }), "still there after a wrong password");
  const right = await call({ password });
  console.log("delete:", right.status, await right.text());
  assert.equal(right.status, 200);
  assert.equal(await col.findOne({ _id }), null, "user gone");
  assert.equal(await (await chats()).countDocuments({ userId: String(_id) }), 0, "chats gone");
  assert.equal(await (await sessions()).countDocuments({ userId: String(_id) }), 0, "sessions gone");
  console.log("delete checks: all passed (account had not agreed to the current terms)");
  ok = true;
} finally {
  await col.deleteMany({ email });
  await (await sessions()).deleteMany({ userId: String(_id) });
  await (await chats()).deleteMany({ userId: String(_id) });
  process.exit(ok ? 0 : 1);
}

