// Throwaway two-account isolation check through the running app. Synthetic accounts only.
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { ObjectId } from "mongodb";
import { chats, sessions, users } from "./src/lib/mongo.ts";
import { saveConnection } from "./src/lib/setup-store.ts";
import { EMPTY_DRAFT } from "./src/lib/setup.ts";
import { PRIVACY_VERSION, TERMS_VERSION } from "./src/lib/consent.ts";
import { deleteAccount } from "./src/lib/retention.ts";

const APP = "http://localhost:3000";
const ACCOUNTS = join(process.cwd(), "..", "accounts");
const now = new Date();

async function makeAccount(tag: string) {
  const _id = new ObjectId();
  const email = `iso-${tag}@example.test`;
  await (await users()).insertOne({
    _id, email, displayEmail: email, lastName: "격리", firstName: tag, createdAt: now,
    consents: { terms: TERMS_VERSION, privacy: PRIVACY_VERSION, age: true, agreedAt: now, marketing: false, marketingAt: null, overseas: true },
  } as never);
  await saveConnection(String(_id), {
    ...EMPTY_DRAFT,
    adtUrl: `http://${tag.toLowerCase()}.sap.invalid:50000`,
    sapUser: `ISO_${tag}`,
    sapPassword: randomBytes(12).toString("base64url"),
    abapRelease: "758",
    client: "100",
  });
  const token = randomBytes(32).toString("base64url");
  await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(token).digest("hex"), userId: String(_id), createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
  const call = async (path: string, init: RequestInit = {}) => {
    const r = await fetch(APP + path, { ...init, headers: { "content-type": "application/json", cookie: `sc4sap_session=${token}`, ...(init.headers ?? {}) } });
    const text = await r.text();
    let body: any; try { body = JSON.parse(text); } catch { body = text.slice(0, 120); }
    return { status: r.status, body };
  };
  return { id: String(_id), email, call };
}

const A = await makeAccount("A");
const B = await makeAccount("B");
const results: string[] = [];
const check = (name: string, cond: boolean, detail = "") => { results.push(`${cond ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`); };
let sa: string | undefined;
try {
  const ra = await A.call("/api/sessions", { method: "POST", body: "{}" });
  const rb = await B.call("/api/sessions", { method: "POST", body: "{}" });
  check("A opens a session", ra.status === 201, String(ra.status) + " " + JSON.stringify(ra.body).slice(0, 120));
  check("B opens a session", rb.status === 201, String(rb.status));
  sa = ra.body?.session?.id; const sb = rb.body?.session?.id;

  const la = (await A.call("/api/sessions")).body.sessions.map((s: any) => s.id);
  const lb = (await B.call("/api/sessions")).body.sessions.map((s: any) => s.id);
  check("A's list has only A's session", la.includes(sa) && !la.includes(sb));
  check("B's list has only B's session", lb.includes(sb) && !lb.includes(sa));

  const g = await B.call(`/api/sessions/${sa}`);
  check("B cannot read A's session", g.status === 404 || g.status === 403, String(g.status));
  const m = await B.call(`/api/sessions/${sa}/messages`, { method: "POST", body: JSON.stringify({ text: "hi" }) });
  check("B cannot send into A's session", m.status === 404 || m.status === 403, String(m.status));
  const st = await B.call(`/api/sessions/${sa}/stream`);
  check("B cannot open A's stream", st.status === 404 || st.status === 403, String(st.status));
  const d = await B.call(`/api/sessions/${sa}`, { method: "DELETE" });
  check("B cannot close A's session", d.status === 404 || d.status === 403, String(d.status));
  const still = (await A.call("/api/sessions")).body.sessions.map((s: any) => s.id);
  check("A's session survives B's attempts", still.includes(sa));

  const chatId = new ObjectId();
  await (await chats()).insertOne({ _id: chatId, userId: A.id, title: "A only", createdAt: now, updatedAt: now } as never);
  const cl = await B.call("/api/chats");
  check("B's chat list lacks A's chat", !JSON.stringify(cl.body).includes(String(chatId)), String(cl.status));
  const cr = await B.call(`/api/chats/${chatId}`);
  check("B cannot read A's chat", cr.status === 404 || cr.status === 403, String(cr.status));
  const ca = await A.call(`/api/chats/${chatId}`);
  check("A reads its own chat", ca.status === 200, String(ca.status));

  const pa = await A.call("/api/profiles");
  const pb = await B.call("/api/profiles");
  const urlsA = JSON.stringify(pa.body); const urlsB = JSON.stringify(pb.body);
  check("A's SAP list shows only A's system", urlsA.includes("a.sap.invalid") && !urlsA.includes("b.sap.invalid"), String(pa.status));
  check("B's SAP list shows only B's system", urlsB.includes("b.sap.invalid") && !urlsB.includes("a.sap.invalid"), String(pb.status));

  for (const acc of [A, B]) {
    const home = join(ACCOUNTS, acc.id, "home", "profiles");
    const envs = existsSync(home) ? readdirSync(home).map((p) => join(home, p, "sap.env")).filter(existsSync) : [];
    const refs = envs.map((e) => /^SAP_PASSWORD=(.*)$/m.exec(readFileSync(e, "utf8"))?.[1] ?? "");
    check(`${acc.email.slice(4, 5)}'s password sits under its own keychain service`, refs.length > 0 && refs.every((r) => r.startsWith(`keychain:sc4sap-web.${acc.id}/`)), refs.join(","));
  }
} finally {
  for (const acc of [A, B]) {
    const doc = await (await users()).findOne({ email: acc.email });
    try { if (doc) await deleteAccount(doc, "member"); } catch (e) { results.push(`FAIL cleanup ${acc.email}: ${(e as Error).message}`); }
    check(`${acc.email.slice(4, 5)}'s folder removed`, !existsSync(join(ACCOUNTS, acc.id)));
    check(`${acc.email.slice(4, 5)}'s user row removed`, !(await (await users()).findOne({ email: acc.email })));
  }
  console.log(results.join("\n"));
  process.exit(results.some((r) => r.startsWith("FAIL")) ? 1 : 0);
}

