  check("B's SAP list shows only B's system", urlsB.includes("b.sap.invalid") && !urlsB.includes("a.sap.invalid"), String(pb.status));

  for (const acc of [A, B]) {
    const home = join(ACCOUNTS, acc.id, "home", "profiles");
    const envs = existsSync(home) ? readdirSync(home).map((p) => join(home, p, "sap.env")).filter(existsSync) : [];
    const refs = envs.map((e) => /^SAP_PASSWORD=(.*)$/m.exec(readFileSync(e, "utf8"))?.[1] ?? "");
    check(`${acc.email.slice(4, 5)}'s password sits under its own keychain service`, refs.length > 0 && refs.every((r) => r.startsWith(`keychain:sc4sap-web.${acc.id}/`)), refs.join(","));
  }
} finally {
  for (const acc of [A, B]) {
    const doc = await (await users()).findOne({ email: acc.email });
    try { if (doc) await deleteAccount(doc, "member"); } catch (e) { results.push(`FAIL cleanup ${acc.email}: ${(e as Error).message}`); }
    check(`${acc.email.slice(4, 5)}'s folder removed`, !existsSync(join(ACCOUNTS, acc.id)));
    check(`${acc.email.slice(4, 5)}'s user row removed`, !(await (await users()).findOne({ email: acc.email })));
  }
  console.log(results.join("\n"));
  process.exit(results.some((r) => r.startsWith("FAIL")) ? 1 : 0);
}

