/**
 * Sending a page of this app to the reader's Obsidian vault.
 *
 * The vault is on the reader's machine and this app is not, so nothing here
 * goes through the server: the browser copies the Markdown to the clipboard
 * and opens `obsidian://new?…&clipboard`, and Obsidian — if it is installed —
 * writes the note from what is on the clipboard. Through the clipboard rather
 * than `content=`, because a spec with its pictures inline is far longer than
 * any URL a browser or the OS will hand to another program.
 *
 * Where to put it — the vault's name and a folder in it — is this browser's
 * own setting (`localStorage`): a vault is a folder on one machine, and the
 * same account on another machine has a different one, or none.
 */

export type ObsidianTarget = {
  /** The vault's name as Obsidian shows it. Empty: whichever vault is open. */
  vault: string;
  /** A folder inside the vault, `/`-separated. Empty: the vault's root. */
  folder: string;
};

const KEY = "sc4sap.obsidian";

export const DEFAULT_TARGET: ObsidianTarget = { vault: "", folder: "SC4SAP" };

export function readTarget(): ObsidianTarget {
  try {
    const raw = JSON.parse(localStorage.getItem(KEY) ?? "null") as Partial<ObsidianTarget> | null;
    if (!raw) return DEFAULT_TARGET;
    return {
      vault: typeof raw.vault === "string" ? raw.vault : "",
      folder: typeof raw.folder === "string" ? raw.folder : DEFAULT_TARGET.folder,
    };
  } catch {
    // Storage refused or unreadable — the default still works.
    return DEFAULT_TARGET;
  }
}

export function saveTarget(target: ObsidianTarget): void {
  try {
    localStorage.setItem(KEY, JSON.stringify({ vault: target.vault.trim(), folder: cleanFolder(target.folder) }));
  } catch {
    // Not kept past this tab; nothing else depends on it.
  }
}

/** `/a//b/` → `a/b`, without `..` or the characters a file name cannot hold. */
export function cleanFolder(folder: string): string {
  return folder
    .split(/[\\/]+/)
    .map((part) => noteName(part))
    .filter((part) => part !== "" && part !== "." && part !== "..")
    .join("/");
}

/** A title made safe for a note's file name: no `\ / : * ? " < > | # ^ [ ]`, at most 100 characters. */
export function noteName(title: string): string {
  return title
    .replace(/[\\/:*?"<>|#^[\]]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 100)
    .trim();
}

/**
 * The note with Obsidian properties on top. Any front matter the Markdown
 * already carries is replaced, not stacked: two `---` blocks would leave the
 * second as visible text.
 */
export function withProperties(markdown: string, properties: Record<string, string | string[]>): string {
  const body = markdown.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");
  const yaml = Object.entries(properties)
    .filter(([, value]) => (Array.isArray(value) ? value.length > 0 : value !== ""))
    .map(([key, value]) =>
      Array.isArray(value)
        ? `${key}:\n${value.map((item) => `  - ${quote(item)}`).join("\n")}`
        : `${key}: ${quote(value)}`,
    )
    .join("\n");
  return `---\n${yaml}\n---\n\n${body}`;
}

function quote(value: string): string {
  return /^[\w .\-/가-힣ぁ-んァ-ン一-龥]*$/.test(value) && value.trim() === value ? value : JSON.stringify(value);
}

/** The `obsidian://new` link for a note whose content is on the clipboard. */
export function newNoteUrl(target: ObsidianTarget, title: string): string {
  const name = noteName(title) || "SC4SAP";
  const folder = cleanFolder(target.folder);
  const params = [
    ...(target.vault.trim() ? [`vault=${encodeURIComponent(target.vault.trim())}`] : []),
    `file=${encodeURIComponent(folder ? `${folder}/${name}` : name)}`,
    "clipboard",
  ];
  return `obsidian://new?${params.join("&")}`;
}

/**
 * Copies the note and hands it to Obsidian. Throws when the clipboard refuses
 * (no permission, page not focused) — then nothing has been opened either.
 */
export async function sendToObsidian(title: string, markdown: string): Promise<void> {
  await navigator.clipboard.writeText(markdown);
  window.location.href = newNoteUrl(readTarget(), title);
}

