"use client";

/**
 * Where "Send to Obsidian" puts a note: the vault and a folder in it.
 *
 * Read from and written to this browser only (`lib/obsidian.ts`) — a vault is
 * a folder on one machine. Rendered empty on the server and filled after
 * mount, because the server cannot see `localStorage`.
 */
import { useEffect, useState } from "react";
import { EditButton, EditModal, SettingRow } from "@/components/settings/EditModal";
import { Icon } from "@/components/Icon";
import { DEFAULT_TARGET, cleanFolder, readTarget, saveTarget, type ObsidianTarget } from "@/lib/obsidian";
import { useLocale } from "@/lib/i18n/client";

export function ObsidianSettings() {
  const { t: messages } = useLocale();
  const t = messages.obsidian;
  const [target, setTarget] = useState<ObsidianTarget>(DEFAULT_TARGET);
  const [editing, setEditing] = useState(false);
  const [vault, setVault] = useState("");
  const [folder, setFolder] = useState("");
  const [saved, setSaved] = useState(false);

  useEffect(() => setTarget(readTarget()), []);

  return (
    <section className="panel">
      <div className="panel-head">
        <h2>
          <Icon name="notebook" /> {t.heading}
        </h2>
        <p className="panel-note">{t.note}</p>
      </div>
      <div className="setting-rows">
        <SettingRow
          label={t.vault}
          value={target.vault || t.anyVault}
          hint={saved ? t.saved : t.vaultHint}
          action={
            <EditButton
              label={t.edit}
              onClick={() => {
                setVault(target.vault);
                setFolder(target.folder);
                setEditing(true);
              }}
            />
          }
        />
        <SettingRow label={t.folder} value={target.folder || t.rootFolder} hint={t.folderHint} />
      </div>

      {editing && (
        <EditModal
          kind={t.heading}
          heading={t.editHeading}
          description={t.note}
          submitLabel={t.save}
          onSubmit={() => {
            const next = { vault: vault.trim(), folder: cleanFolder(folder) };
            saveTarget(next);
            setTarget(next);
            setEditing(false);
            setSaved(true);
          }}
          onCancel={() => setEditing(false)}
        >
          <label className="field">
            <span className="field-label">{t.vault}</span>
            <input type="text" value={vault} onChange={(e) => setVault(e.target.value)} placeholder={t.vaultPlaceholder} />
            <span className="field-hint">{t.vaultHint}</span>
          </label>
          <label className="field">
            <span className="field-label">{t.folder}</span>
            <input type="text" value={folder} onChange={(e) => setFolder(e.target.value)} placeholder="SC4SAP" />
            <span className="field-hint">{t.folderHint}</span>
          </label>
        </EditModal>
      )}
    </section>
  );
}
