"use client";

/**
 * "Send to Obsidian" for a page of Markdown — see `lib/obsidian.ts`.
 *
 * The text is asked for at the press, not passed in up front, so a long
 * transcript is turned into Markdown once, when someone wants it, rather than
 * on every render.
 */
import { useState } from "react";
import { Icon } from "@/components/Icon";
import { sendToObsidian, withProperties } from "@/lib/obsidian";
import { useLocale } from "@/lib/i18n/client";

export function ObsidianButton({
  title,
  markdown,
  properties = {},
  disabled = false,
  className = "ghost",
}: {
  title: string;
  markdown: () => string;
  properties?: Record<string, string | string[]>;
  disabled?: boolean;
  className?: string;
}) {
  const { t: messages } = useLocale();
  const t = messages.obsidian;
  const [note, setNote] = useState<string | null>(null);

  async function send(): Promise<void> {
    setNote(null);
    try {
      await sendToObsidian(
        title,
        withProperties(markdown(), {
          created: new Date().toISOString().slice(0, 10),
          source: "SC4SAP",
          tags: ["sc4sap"],
          ...properties,
        }),
      );
      setNote(t.sent);
    } catch {
      setNote(t.clipboardRefused);
    }
  }

  return (
    <>
      <button type="button" className={className} onClick={() => void send()} disabled={disabled} title={t.sendHint}>
        <Icon name="notebook" /> {t.send}
      </button>
      {note && (
        <span className="obsidian-note" role="status">
          {note}
        </span>
      )}
    </>
  );
}
