/**
 * An account's own reference notes — Markdown from its Obsidian vault — and
 * the two tools a session reads them with.
 *
 *   <accounts>/<userId>/notes/<vault-relative path>.md
 *
 * Kept in the account's folder, so deleting the account (`deleteAccountSpace`)
 * takes them along and no other account's session can reach them: the tools
 * are built per session over this one folder, and every path is resolved and
 * checked to stay inside it.
 *
 * Uploaded from the browser in batches (the request body is capped at 32 MB),
 * the first with `reset` to replace what was there. Limits are per account:
 * `MAX_FILES` notes, `MAX_BYTES` in all.
 *
 * Search is plain term matching, not embeddings: a vault of a thousand notes
 * is a few megabytes, read in well under a second, and the agent asks again
 * with other words when the first try misses. What comes back is short — the
 * paths and a snippet around the first hit — so a search costs a few hundred
 * tokens and the agent reads in full only the note it picks.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";
import type { AccountSpace } from "./accounts.ts";

export const MAX_FILES = 1_000;
export const MAX_BYTES = 50 * 1024 * 1024;
/** One note handed to the agent in full, at most. */
const READ_LIMIT = 40_000;
const SNIPPET = 220;
const RESULTS = 8;

export const NOTE_TOOLS = ["mcp__notes__SearchNotes", "mcp__notes__ReadNote"] as const;

export function notesDir(space: AccountSpace): string {
  return join(space.root, "notes");
}

export type NoteFile = { path: string; text: string };
export type NotesSummary = { count: number; bytes: number; updatedAt: string | null };

/**
 * A vault-relative path made safe: `/` separated, no `..`, no drive or root,
 * ending in `.md`. `null` for anything that is not a Markdown note.
 */
export function cleanNotePath(path: string): string | null {
  const parts = path
    .replace(/\\/g, "/")
    .split("/")
    .map((part) => part.trim())
    .filter((part) => part !== "" && part !== ".");
  if (parts.length === 0 || parts.some((part) => part === ".." || /[<>:"|?*\x00-\x1f]/.test(part))) return null;
  // Obsidian's own folder, and anything hidden, is configuration, not notes.
  if (parts.some((part) => part.startsWith("."))) return null;
  const joined = parts.join("/");
  return /\.md$/i.test(joined) ? joined : null;
}

function inside(dir: string, path: string): string | null {
  const full = resolve(dir, path);
  const rel = relative(dir, full);
  return rel && !rel.startsWith("..") && !rel.includes(`..${sep}`) && !resolve(rel).startsWith(rel) ? full : null;
}

function walk(dir: string, base = dir): string[] {
  if (!existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, base));
    else if (entry.isFile() && entry.name.toLowerCase().endsWith(".md")) {
      out.push(relative(base, full).split(sep).join("/"));
    }
  }
  return out;
}

export function summarize(space: AccountSpace): NotesSummary {
  const dir = notesDir(space);
  const files = walk(dir);
  let bytes = 0;
  let latest = 0;
  for (const file of files) {
    const stat = statSync(join(dir, file));
    bytes += stat.size;
    latest = Math.max(latest, stat.mtimeMs);
  }
  return { count: files.length, bytes, updatedAt: latest ? new Date(latest).toISOString() : null };
}

export type StoreOutcome =
  | { ok: true; summary: NotesSummary; skipped: number }
  | { ok: false; error: string };

/** Writes one batch. `reset` first empties the folder: the vault is replaced, not merged. */
export function storeNotes(space: AccountSpace, files: readonly NoteFile[], reset: boolean): StoreOutcome {
  if (!space.home) return { ok: false, error: "not an account" };
  const dir = notesDir(space);
  if (reset) rmSync(dir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
  mkdirSync(dir, { recursive: true });

  const before = summarize(space);
  let count = before.count;
  let bytes = before.bytes;
  let skipped = 0;
  for (const file of files) {
    const path = typeof file.path === "string" ? cleanNotePath(file.path) : null;
    if (!path || typeof file.text !== "string") {
      skipped += 1;
      continue;
    }
    const full = inside(dir, path);
    if (!full) {
      skipped += 1;
      continue;
    }
    const size = Buffer.byteLength(file.text, "utf8");
    const replacing = existsSync(full) ? statSync(full).size : null;
    if (replacing === null && count + 1 > MAX_FILES) {
      return { ok: false, error: `at most ${MAX_FILES} notes per account` };
    }
    if (bytes - (replacing ?? 0) + size > MAX_BYTES) {
      return { ok: false, error: `at most ${MAX_BYTES / 1024 / 1024} MB of notes per account` };
    }
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, file.text, "utf8");
    if (replacing === null) count += 1;
    bytes += size - (replacing ?? 0);
  }
  return { ok: true, summary: summarize(space), skipped };
}

export function deleteNotes(space: AccountSpace): void {
  if (!space.home) return;
  rmSync(notesDir(space), { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
}

/** Lower-cased terms of two characters or more, so 한 글자 particles do not match everything. */
