const READ_LIMIT = 40_000;
const SNIPPET = 220;
const RESULTS = 8;

export const NOTE_TOOLS = ["mcp__notes__SearchNotes", "mcp__notes__ReadNote"] as const;

export function notesDir(space: AccountSpace): string {
  return join(space.root, "notes");
