"use client";

/**
 * Reference notes: a folder of the member's Obsidian vault, uploaded so the
 * agent can search it (`src/server/notes.ts`).
 *
 * The browser reads the folder (`webkitdirectory`) and sends only the `.md`
 * files, in batches under the request limit; the first batch replaces what
 * was there. Obsidian's own `.obsidian/` and any hidden folder are skipped —
 * they are settings, not notes. The folder's own name is dropped from each
 * path, so a note is filed by where it sits inside the vault.
 */
import { useEffect, useRef, useState } from "react";
import { Icon } from "@/components/Icon";
import { SettingRow } from "@/components/settings/EditModal";
import { useLocale } from "@/lib/i18n/client";

type Summary = { count: number; bytes: number; updatedAt: string | null };

const MAX_FILES = 1_000;
const MAX_BYTES = 50 * 1024 * 1024;
/** Well under the backend's 32 MB body limit, so one batch is never refused for size. */
const BATCH_BYTES = 4 * 1024 * 1024;

export function NotesSettings() {
  const { t: messages, tag } = useLocale();
  const t = messages.notes;
  const [summary, setSummary] = useState<Summary | null>(null);
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<string | null>(null);
  const picker = useRef<HTMLInputElement>(null);

  async function load(): Promise<void> {
    const response = await fetch("/api/notes").catch(() => null);
    if (response?.ok) setSummary((await response.json()) as Summary);
  }
  useEffect(() => {
    void load();
  }, []);

  async function upload(list: FileList): Promise<void> {
    const files = [...list].filter((file) => {
      const path = file.webkitRelativePath || file.name;
      return /\.md$/i.test(path) && !path.split("/").some((part) => part.startsWith("."));
    });
    if (files.length === 0) {
      setNote(t.noMarkdown);
      return;
    }
    const total = files.reduce((sum, file) => sum + file.size, 0);
    if (files.length > MAX_FILES || total > MAX_BYTES) {
      setNote(t.tooMany(MAX_FILES, MAX_BYTES / 1024 / 1024));
      return;
    }
    setBusy(true);
    setNote(null);
    try {
      let batch: { path: string; text: string }[] = [];
      let size = 0;
      let first = true;
      let sent = 0;
      const flush = async (): Promise<void> => {
        const response = await fetch("/api/notes", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ reset: first, files: batch }),
        });
        if (!response.ok) {
          const body = (await response.json().catch(() => null)) as { error?: string } | null;
          throw new Error(body?.error ?? String(response.status));
        }
        first = false;
        sent += batch.length;
        setNote(t.uploading(sent, files.length));
        batch = [];
        size = 0;
      };
      for (const file of files) {
        // `Vault/sub/note.md` → `sub/note.md`.
        const path = (file.webkitRelativePath || file.name).split("/").slice(file.webkitRelativePath ? 1 : 0).join("/");
        const text = await file.text();
        if (size + text.length > BATCH_BYTES && batch.length > 0) await flush();
        batch.push({ path, text });
        size += text.length;
      }
      if (batch.length > 0) await flush();
      setNote(t.uploaded(sent));
      await load();
    } catch (err) {
      setNote(t.failed((err as Error).message));
    } finally {
      setBusy(false);
      if (picker.current) picker.current.value = "";
    }
  }

  async function clear(): Promise<void> {
    setBusy(true);
    const response = await fetch("/api/notes", { method: "DELETE" }).catch(() => null);
    setBusy(false);
    setNote(response?.ok ? t.cleared : t.failed(String(response?.status ?? "network")));
    await load();
  }

  const value = !summary
    ? "—"
    : summary.count === 0
      ? t.none
      : t.summary(summary.count, (summary.bytes / 1024 / 1024).toFixed(1));
  const when = summary?.updatedAt
    ? new Intl.DateTimeFormat(tag, { dateStyle: "medium", timeStyle: "short" }).format(new Date(summary.updatedAt))
    : null;

  return (
    <section className="panel">
      <div className="panel-head">
        <h2>
          <Icon name="books" /> {t.heading}
        </h2>
        <p className="panel-note">{t.note}</p>
      </div>
      <div className="setting-rows">
        <SettingRow
          label={t.label}
          value={value}
          hint={note ?? (when ? t.updated(when) : t.hint)}
          action={
            <span className="notes-actions">
              <input
                ref={picker}
                type="file"
                hidden
                multiple
                // Not in React's types; every current browser honours it.
                {...({ webkitdirectory: "", directory: "" } as Record<string, string>)}
                onChange={(event) => event.target.files && void upload(event.target.files)}
              />
              <button type="button" className="ghost" disabled={busy} onClick={() => picker.current?.click()}>
                <Icon name={busy ? "circle-notch" : "folder-open"} /> {t.choose}
              </button>
              {summary && summary.count > 0 && (
                <button type="button" className="ghost" disabled={busy} onClick={() => void clear()}>
                  <Icon name="trash" /> {t.clear}
                </button>
              )}
            </span>
          }
        />
      </div>
    </section>
  );
}

