// Throwaway end-to-end check of reference notes through the running app. Synthetic accounts only.
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { ObjectId } from "mongodb";
import { sessions, users } from "./src/lib/mongo.ts";
import { saveConnection } from "./src/lib/setup-store.ts";
import { EMPTY_DRAFT } from "./src/lib/setup.ts";
import { PRIVACY_VERSION, TERMS_VERSION } from "./src/lib/consent.ts";
import { deleteAccount } from "./src/lib/retention.ts";

const APP = "http://localhost:3000";
const now = new Date();

async function makeAccount(tag: string) {
  const _id = new ObjectId();
  const email = `notes-${tag}@example.test`;
  await (await users()).insertOne({
    _id, email, displayEmail: email, lastName: "노트", firstName: tag, createdAt: now,
    consents: { terms: TERMS_VERSION, privacy: PRIVACY_VERSION, age: true, agreedAt: now, marketing: false, marketingAt: null, overseas: true },
  } as never);
  await saveConnection(String(_id), { ...EMPTY_DRAFT, adtUrl: `http://${tag.toLowerCase()}.sap.invalid:50000`, sapUser: `N_${tag}`, sapPassword: randomBytes(12).toString("base64url"), abapRelease: "758", client: "100" });
  const token = randomBytes(32).toString("base64url");
  await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(token).digest("hex"), userId: String(_id), createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
  const call = async (path: string, init: RequestInit = {}) => {
    const r = await fetch(APP + path, { ...init, headers: { ...(init.body ? { "content-type": "application/json" } : {}), cookie: `sc4sap_session=${token}` } });
    const text = await r.text();
    let body: any; try { body = JSON.parse(text); } catch { body = text.slice(0, 200); }
    return { status: r.status, body };
  };
  return { id: String(_id), email, token, call };
}

for (const old of await (await users()).find({ email: /^notes-[AB]@example\.test$/ }).toArray()) await deleteAccount(old, "member");
const A = await makeAccount("A");
const B = await makeAccount("B");
const out: string[] = [];
const check = (name: string, ok: boolean, detail = "") => out.push(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);
try {
  const up = await A.call("/api/notes", { method: "POST", body: JSON.stringify({ reset: true, files: [
    { path: "SD/출하 규칙.md", text: "# 출하 규칙\n사내 규칙 코드명 BLUEFALCON-7: 컨테이너 최소 적재율은 82%입니다." },
    { path: ".obsidian/app.md", text: "x" },
  ] }) });
  check("A uploads notes", up.status === 200 && up.body?.summary?.count === 1, JSON.stringify(up.body).slice(0, 120));
  const gb = await B.call("/api/notes");
  check("B sees none of A's notes", gb.status === 200 && gb.body.count === 0, JSON.stringify(gb.body));

  const s = await A.call("/api/sessions", { method: "POST", body: JSON.stringify({ model: "claude-haiku-4-5" }) });
  check("A opens a session", s.status === 201, String(s.status));
  const id = s.body.session.id as string;
  const send = await A.call(`/api/sessions/${id}/messages`, { method: "POST", body: JSON.stringify({ text: "내 참고 노트에서 SearchNotes 도구로 BLUEFALCON-7 을 찾아서, 컨테이너 최소 적재율 숫자만 한 줄로 답해 주세요. SAP 도구는 쓰지 마세요." }) });
  check("message accepted", send.status === 202, String(send.status));

  const stream = await fetch(`${APP}/api/sessions/${id}/stream`, { headers: { cookie: `sc4sap_session=${A.token}` } });
  const reader = stream.body!.getReader();
  const decoder = new TextDecoder();
  let buf = "", tools: string[] = [], text = "", done = false;
  const deadline = Date.now() + 150_000;
  while (!done && Date.now() < deadline) {
    const { value, done: end } = await Promise.race([reader.read(), new Promise<any>((r) => setTimeout(() => r({ value: undefined, done: false }), 5000))]);
    if (end) break;
    if (value) buf += decoder.decode(value, { stream: true });
    for (const line of buf.split("\n")) {
      if (!line.startsWith("data:")) continue;
      try {
        const ev = JSON.parse(line.slice(5));
        if (ev.type === "tool_start" && ev.name) tools.push(ev.name);
        if (ev.type === "text_delta" && ev.text) text += ev.text;
        if (ev.type === "status" && ev.status === "idle" && (tools.length || text)) done = true;
      } catch {}
    }
    buf = buf.slice(buf.lastIndexOf("\n") + 1);
  }
  await reader.cancel().catch(() => {});
  check("agent used SearchNotes", tools.some((t) => t.includes("SearchNotes")), tools.join(","));
  check("answer carries the note's fact", text.includes("82"), text.slice(0, 160).replace(/\n/g, " "));
} finally {
  for (const acc of [A, B]) {
    const doc = await (await users()).findOne({ _id: new ObjectId(acc.id) });
    try { if (doc) await deleteAccount(doc, "member"); } catch (e) { out.push(`FAIL cleanup: ${(e as Error).message}`); }
  }
  console.log(out.join("\n"));
  process.exit(out.some((l) => l.startsWith("FAIL")) ? 1 : 0);
}

