import assert from "node:assert/strict";
import { mkdtempSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { cleanNotePath, readNote, searchNotes, storeNotes, summarize, deleteNotes, MAX_FILES } from "./server/notes.ts";

const root = mkdtempSync(join(tmpdir(), "notes-"));
const space = { userId: "t", home: join(root, "home"), root, keychainService: "x" };
try {
  assert.equal(cleanNotePath("a/../b.md"), null);
  assert.equal(cleanNotePath(".obsidian/app.md"), null);
  assert.equal(cleanNotePath("C:\\x\\y.md"), null);
  assert.equal(cleanNotePath("img.png"), null);
  assert.equal(cleanNotePath("CON.md"), null);
  assert.equal(cleanNotePath("sub/aux.md"), null);
  assert.equal(cleanNotePath("\\SD\\출하 규칙.md"), "SD/출하 규칙.md");
  const r = storeNotes(space, [
    { path: "SD/출하 규칙.md", text: "# 출하\nZSDR24730 은 컨테이너 단위로 묶어요. VBELN 생성." },
    { path: "MM/구매.md", text: "구매오더 승인 전략 release strategy" },
    { path: "../escape.md", text: "x" },
    { path: ".obsidian/workspace.md", text: "x" },
    { path: "dir.md/inner.md", text: "inside a folder named dir.md" },
    { path: "dir.md", text: "same name as that folder" },
  ], true);
  assert.ok(r.ok && r.summary.count === 3 && r.skipped === 3, JSON.stringify(r));
  assert.ok(!existsSync(join(root, "escape.md")));
  assert.equal(readNote(space, "dir.md"), null, "a folder is not a note");
  const hits = searchNotes(space, "ZSDR24730 컨테이너");
  assert.equal(hits[0]?.path, "SD/출하 규칙.md");
  assert.ok(hits[0].snippet.includes("ZSDR24730"));
  assert.equal(searchNotes(space, "a").length, 0);
  assert.ok(readNote(space, "MM/구매.md")?.includes("release"));
  assert.equal(readNote(space, "../../etc/passwd.md"), null);
  const again = storeNotes(space, [{ path: "new.md", text: "BLUEFALCON" }], true);
  assert.ok(again.ok && again.summary.count === 1, "reset replaces");
  assert.equal(searchNotes(space, "ZSDR24730").length, 0, "cache dropped after a new upload");
  assert.equal(searchNotes(space, "bluefalcon")[0]?.path, "new.md");
  const many = Array.from({ length: MAX_FILES + 1 }, (_, i) => ({ path: `n${i}.md`, text: "x" }));
  assert.ok(!storeNotes(space, many, true).ok, "file cap");
  assert.equal(storeNotes({ ...space, home: undefined }, [], true).ok, false, "operator space refused");
  deleteNotes(space);
  assert.equal(summarize(space).count, 0);
  assert.equal(searchNotes(space, "bluefalcon").length, 0, "cache dropped after delete");
  console.log("notes module: all passed");
} finally {
  rmSync(root, { recursive: true, force: true });
}

