  return `---\n${lines.join("\n")}\n---\n${body.startsWith("\n") ? "" : "\n"}${body}`;
}
function setFront(front: Front, key: string, value: string | string[]): void {
  if (!front.keys.includes(key)) front.keys.push(key);
  front.values.set(key, value);
}

/** Puts this package's generated block into a note, replacing an older one, keeping the rest. */
function mergeNote(existing: string | null, pkg: string, block: string, props: Record<string, string | string[]>, title: string): string {
  const { front, body } = existing ? splitFront(existing) : { front: { keys: [], values: new Map() } as Front, body: `# ${title}\n\n## 메모\n\n` };
  for (const [key, value] of Object.entries(props)) {
    if (key === "packages" && Array.isArray(value)) {
      const had = front.values.get("packages");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])].sort());
    } else if (key === "tags" && Array.isArray(value)) {
      const had = front.values.get("tags");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])]);
