/**
 * The CBO reference graph as an Obsidian vault, and back.
 *
 *   out  graph.json (the plugin's analyze-cbo-obj / package-to-process) →
 *        one note per object, its relations as Dataview inline fields
 *        (`reads:: [[TABL VBAK]]`), so Obsidian's graph view draws them —
 *        plus a note per package and per process (the plugin's `components`).
 *        Zipped for the member to unpack into the vault.
 *   back the vault, uploaded as reference notes (`notes.ts`) → the relations
 *        the member wrote outside the generated blocks: `belongs_to:: [[…]]`,
 *        `not_reads:: [[…]]` to strike a relation the source parse got wrong,
 *        plain `[[links]]` as `mentions`. Merged with every graph of the
 *        account into one knowledge graph the agent queries (`notes.ts`).
 *
 * The generated part of a note sits between `<!-- sc4sap:begin PKG -->` and
 * `<!-- sc4sap:end PKG -->`, one block per package, so exporting again
 * replaces only that block. Everything else — the member's text, their
 * properties, their fields — is kept, provided the vault was uploaded before
 * the export: an export merges into the uploaded copy, then the member
 * unpacks the zip over the vault.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, relative, sep } from "node:path";
import { pathToFileURL } from "node:url";
import type { AccountSpace } from "./accounts.ts";

type GNode = { id: string; type: string; name: string; scope?: string; lines?: number; parent?: string };
type Evidence = { unit?: string; line?: number; text?: string };
type GEdge = { from: string; to: string; kind: string; count?: number; confidence?: string; evidence?: Evidence[] };
type Graph = { package?: string; module?: string; system?: string; builtAt?: string; nodes: GNode[]; edges: GEdge[] };

export type GraphRef = {
  id: string;
  package: string;
  module: string;
  system: string;
  builtAt: string | null;
  nodes: number;
  edges: number;
  file: string;
};

/** What the default export draws. `types` (DDIC typing) alone is over half of a real graph. */
const DEFAULT_KINDS = new Set(["reads", "writes", "calls", "submits", "starts", "launches", "uses"]);
const DETAIL_HIDDEN_TYPES = new Set(["DTEL", "DOMA", "INCL", "DYN", "TTYP", "STRU"]);
const BEGIN = (pkg: string) => `<!-- sc4sap:begin ${pkg} -->`;
const END = (pkg: string) => `<!-- sc4sap:end ${pkg} -->`;
const BLOCK = /<!-- sc4sap:begin ([^ ]+) -->[\s\S]*?<!-- sc4sap:end \1 -->\n?/g;

// ---------- finding the account's graphs ----------

/** Every `cbo/<MODULE>/<PACKAGE>/graph.json` under the account's session folders. */
export function listGraphs(space: AccountSpace): GraphRef[] {
  if (!space.home) return [];
  const found: GraphRef[] = [];
  const visit = (dir: string, depth: number): void => {
    if (depth > 9 || !existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name.startsWith("_prev") || entry.name === "notes") continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) visit(full, depth + 1);
      else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") {
        try {
          const g = JSON.parse(readFileSync(full, "utf8")) as Graph;
          const parts = full.split(sep);
          found.push({
            id: createHash("sha1").update(relative(space.root, full)).digest("hex").slice(0, 12),
            package: g.package ?? parts[parts.length - 2],
            module: g.module ?? parts[parts.length - 3],
            system: g.system ?? "SAP",
            builtAt: g.builtAt ?? null,
            nodes: g.nodes.length,
            edges: g.edges.length,
            file: full,
          });
        } catch {
          // A half-written or foreign graph.json is not one of ours.
        }
      }
    }
  };
  visit(join(space.root, "ws"), 0);
  return found.sort((a, b) => (a.system + a.package).localeCompare(b.system + b.package));
}

// ---------- names and tiny YAML ----------

/** `PROG:ZX` → `PROG ZX` — the note's file name and its link target. */
export function noteFile(id: string): string {
  const at = id.indexOf(":");
  const type = at > 0 ? id.slice(0, at) : "NOTE";
  const name = at > 0 ? id.slice(at + 1) : id;
  return `${type} ${name}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();
}
const link = (id: string) => `[[${noteFile(id)}]]`;

type Front = { keys: string[]; values: Map<string, string | string[]> };

/** Front matter of the shape this file writes, and of Obsidian's property editor: scalars and lists. */
export function splitFront(text: string): { front: Front; body: string } {
  const values = new Map<string, string | string[]>();
  const keys: string[] = [];
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
  if (!m) return { front: { keys, values }, body: text };
  let current: string | null = null;
  for (const raw of m[1].split(/\r?\n/)) {
    const item = /^\s+-\s+(.*)$/.exec(raw);
    if (item && current) {
      const list = values.get(current);
      values.set(current, [...(Array.isArray(list) ? list : []), unquote(item[1])]);
      continue;
    }
    const kv = /^([^\s:#][^:]*):\s*(.*)$/.exec(raw);
    if (!kv) continue;
    current = kv[1].trim();
    keys.push(current);
    const v = kv[2].trim();
    if (v === "") values.set(current, []);
    else if (v.startsWith("[") && v.endsWith("]") && !v.startsWith("[[")) {
      values.set(current, v.slice(1, -1).split(",").map((s) => unquote(s.trim())).filter(Boolean));
    } else values.set(current, unquote(v));
  }
  return { front: { keys, values }, body: text.slice(m[0].length) };
}
function unquote(v: string): string {
  return /^".*"$/.test(v) || /^'.*'$/.test(v) ? v.slice(1, -1).replace(/\\"/g, '"') : v;
}
function yamlValue(v: string): string {
  return /^[\w .\-/가-힣]*$/.test(v) && v !== "" && !/^(true|false|null|-|\d)/i.test(v) ? v : JSON.stringify(v);
}
function joinFront(front: Front, body: string): string {
  const lines: string[] = [];
  for (const key of front.keys) {
    const v = front.values.get(key);
    if (Array.isArray(v)) lines.push(v.length ? `${key}:\n${v.map((x) => `  - ${yamlValue(x)}`).join("\n")}` : `${key}: []`);
    else if (v !== undefined) lines.push(`${key}: ${yamlValue(v)}`);
  }
  return `---\n${lines.join("\n")}\n---\n${body.startsWith("\n") ? "" : "\n"}${body}`;
}
function setFront(front: Front, key: string, value: string | string[]): void {
  if (!front.keys.includes(key)) front.keys.push(key);
  front.values.set(key, value);
}

/** Puts this package's generated block into a note, replacing an older one, keeping the rest. */
function mergeNote(existing: string | null, pkg: string, block: string, props: Record<string, string | string[]>, title: string): string {
  const { front, body } = existing ? splitFront(existing) : { front: { keys: [], values: new Map() } as Front, body: `# ${title}\n\n## 메모\n\n` };
  for (const [key, value] of Object.entries(props)) {
    if (key === "packages" && Array.isArray(value)) {
      const had = front.values.get("packages");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])].sort());
    } else if (key === "tags" && Array.isArray(value)) {
      const had = front.values.get("tags");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])]);
    } else setFront(front, key, value);
  }
  const wrapped = `${BEGIN(pkg)}\n${block.trim()}\n${END(pkg)}\n`;
  const own = new RegExp(`${escape(BEGIN(pkg))}[\\s\\S]*?${escape(END(pkg))}\\n?`);
  let next: string;
  if (own.test(body)) next = body.replace(own, wrapped);
  else if (/^## 메모\s*$/m.test(body)) next = body.replace(/^## 메모\s*$/m, `${wrapped}\n## 메모`);
  else next = `${body.trimEnd()}\n\n${wrapped}`;
  return joinFront(front, next);
}
const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// ---------- export ----------

export type VaultOptions = { detail?: boolean; system: string; existing: (path: string) => string | null; components?: Component[] };
type Component = { entries: string[]; members: string[]; writes: string[]; sharedTables: { table: string; writers: string[]; readers: string[] }[] };

function evidenceOf(e: GEdge): string {
  const ev = e.evidence?.[0];
  const where = ev?.unit ? `${ev.unit}${ev.line ? `:${ev.line}` : ""}` : "";
  return [where, e.confidence === "low" ? "low" : "", e.count && e.count > 1 ? `×${e.count}` : ""].filter(Boolean).join(" · ");
}

/** The vault's files for one package graph, merged into what the member already has. */
export function buildVault(graph: Graph, opts: VaultOptions): Map<string, string> {
  const pkg = graph.package ?? "PACKAGE";
  const base = `SC4SAP/${noteFile(`X:${opts.system}`).slice(2)}`;
  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
  const hidden = (id: string) => !opts.detail && DETAIL_HIDDEN_TYPES.has(nodes.get(id)?.type ?? "");
  const edges = graph.edges.filter(
    (e) => (opts.detail ? e.kind !== "dynamic" : DEFAULT_KINDS.has(e.kind)) && !hidden(e.from) && !hidden(e.to),
  );
  const kept = new Set<string>();
  for (const e of edges) kept.add(e.from).add(e.to);
  for (const n of graph.nodes) if (n.scope === "member" && !hidden(n.id) && n.type !== "INCL") kept.add(n.id);

  const out = new Map<string, GEdge[]>();
  for (const e of edges) out.set(e.from, [...(out.get(e.from) ?? []), e]);
  const files = new Map<string, string>();
  const put = (path: string, block: string, props: Record<string, string | string[]>, title: string) =>
    files.set(path, mergeNote(opts.existing(path), pkg, block, props, title));

  for (const id of kept) {
    const n = nodes.get(id) ?? { id, type: id.split(":")[0], name: id.split(":").slice(1).join(":") };
    const rel = (out.get(id) ?? [])
      .sort((a, b) => a.kind.localeCompare(b.kind) || a.to.localeCompare(b.to))
      .map((e) => `- ${e.kind}:: ${link(e.to)}${evidenceOf(e) ? ` — ${evidenceOf(e)}` : ""}`);
    const block = rel.length ? `### ${pkg}\n${rel.join("\n")}` : `### ${pkg}\n(no outgoing relations in the source parse)`;
    put(`${base}/objects/${noteFile(id)}.md`, block, {
      sc4sap_id: id,
      type: n.type,
      scope: n.scope ?? "",
      system: opts.system,
      packages: [pkg],
      ...(n.lines ? { lines: String(n.lines) } : {}),
      tags: [`sc4sap/${n.type.toLowerCase()}`, `sc4sap/${n.scope ?? "other"}`],
    }, n.name);
  }

  const comps = opts.components ?? [];
  comps.forEach((c, i) => {
    const entry = nodes.get(c.entries[0])?.name ?? c.entries[0];
    const path = `${base}/processes/${noteFile(`X:${pkg} P${String(i + 1).padStart(2, "0")} ${entry}`).slice(2)}.md`;
    const lines = [
      `### ${pkg}`,
      `- package:: [[PACKAGE ${pkg}]]`,
      ...c.entries.map((e) => `- entry:: ${link(e)}`),
      ...c.members.filter((m) => kept.has(m)).map((m) => `- member:: ${link(m)}`),
      ...c.sharedTables.map((t) => `- handoff:: ${link(t.table)} — ${t.writers.map((w) => nodes.get(w)?.name ?? w).join(", ")} → ${t.readers.map((r) => nodes.get(r)?.name ?? r).join(", ") || "(written only)"}`),
    ];
    put(path, lines.join("\n"), { sc4sap_id: `PROCESS:${pkg}:${i + 1}`, type: "PROCESS", system: opts.system, packages: [pkg], tags: ["sc4sap/process"] }, `${pkg} P${i + 1} — ${entry}`);
  });

  const byType = new Map<string, string[]>();
  for (const id of kept) {
    const n = nodes.get(id);
    if (n?.scope !== "member") continue;
    byType.set(n.type, [...(byType.get(n.type) ?? []), id]);
  }
  const index = [
    `### ${pkg}`,
    `${graph.module ? `Module ${graph.module} · ` : ""}${kept.size} objects · ${edges.length} relations${opts.detail ? " (detail)" : ""} · built ${graph.builtAt ?? "?"}`,
    ...[...byType.entries()].sort().flatMap(([type, ids]) => [`#### ${type}`, ...ids.sort().map((id) => `- member:: ${link(id)}`)]),
    ...(comps.length ? ["#### Processes", ...comps.map((_, i) => `- process:: [[${pkg} P${String(i + 1).padStart(2, "0")} ${nodes.get(comps[i].entries[0])?.name ?? comps[i].entries[0]}]]`)] : []),
  ];
  put(`${base}/packages/PACKAGE ${noteFile(`X:${pkg}`).slice(2)}.md`, index.join("\n"), { sc4sap_id: `PACKAGE:${pkg}`, type: "PACKAGE", system: opts.system, packages: [pkg], tags: ["sc4sap/package"] }, pkg);

  files.set(`${base}/SC4SAP 사용법.md`, opts.existing(`${base}/SC4SAP 사용법.md`) ?? GUIDE);
  return files;
}

const GUIDE = `# SC4SAP 그래프 사용법

이 폴더는 SC4SAP이 소스를 분석해 만든 관계 그래프예요.

- \`<!-- sc4sap:begin … -->\` 와 \`<!-- sc4sap:end … -->\` 사이는 다시 내보낼 때 바뀌어요. 그 밖에 쓴 내용은 그대로 남아요.
- 관계를 더하려면 그 밖에 한 줄을 써요. 예: \`belongs_to:: [[출하 프로세스]]\`
- 소스 분석이 틀린 관계를 지우려면 \`not_\`을 붙여요. 예: \`not_reads:: [[TABL VBAK]]\`
- 그냥 \`[[링크]]\`를 걸면 "언급" 관계가 돼요.
- 다듬은 뒤 SC4SAP 설정 → 참고 노트에서 볼트 폴더를 다시 올리면 에이전트가 그 관계로 답해요.
- 다시 내보내기 전에도 먼저 올려 주세요. 그래야 메모가 덮이지 않아요.
`;

// ---------- zip (stored, UTF-8 names) ----------

const CRC = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

export function zip(files: Map<string, string>): Buffer {
  const chunks: Buffer[] = [];
  const central: Buffer[] = [];
  let offset = 0;
  for (const [path, text] of files) {
    const name = Buffer.from(path, "utf8");
    const data = Buffer.from(text, "utf8");
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6); // UTF-8 names
    local.writeUInt16LE(0, 8); // stored
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    chunks.push(local, name, data);
    const head = Buffer.alloc(46);
    head.writeUInt32LE(0x02014b50, 0);
    head.writeUInt16LE(20, 4);
    head.writeUInt16LE(20, 6);
    head.writeUInt16LE(0x0800, 8);
    head.writeUInt32LE(crc, 16);
    head.writeUInt32LE(data.length, 20);
    head.writeUInt32LE(data.length, 24);
    head.writeUInt16LE(name.length, 28);
    head.writeUInt32LE(offset, 42);
    central.push(head, name);
    offset += 30 + name.length + data.length;
  }
  const dir = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(files.size, 8);
  end.writeUInt16LE(files.size, 10);
  end.writeUInt32LE(dir.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...chunks, dir, end]);
}

// ---------- back: the member's relations ----------

export type CuratedEdge = { from: string; to: string; kind: string; negated: boolean; note: string };
const OUR_KEYS = new Set(["sc4sap_id", "type", "scope", "system", "packages", "lines", "tags", "created", "source", "skill", "aliases", "cssclasses"]);
const LINK = /\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]/g;

/** The relations the member wrote, from uploaded notes: `{ path, text }` as `notes.ts` stores them. */
export function curatedEdges(notes: readonly { path: string; text: string }[]): { edges: CuratedEdge[]; ids: Map<string, string> } {
  const ids = new Map<string, string>();
  const parsed = notes.map((n) => {
    const { front, body } = splitFront(n.text);
    const file = n.path.split("/").pop()!.replace(/\.md$/i, "");
    const id = typeof front.values.get("sc4sap_id") === "string" ? (front.values.get("sc4sap_id") as string) : `NOTE:${file}`;
    ids.set(file, id);
    return { n, front, body, id };
  });
  const target = (name: string) => ids.get(name.trim()) ?? `NOTE:${name.trim()}`;
  const edges: CuratedEdge[] = [];
  for (const { n, front, body, id } of parsed) {
    const add = (key: string, value: string) => {
      const negated = key.startsWith("not_");
      const kind = negated ? key.slice(4) : key;
      for (const m of value.matchAll(LINK)) edges.push({ from: id, to: target(m[1]), kind, negated, note: n.path });
    };
    for (const key of front.keys) {
      if (OUR_KEYS.has(key)) continue;
      const v = front.values.get(key);
      for (const item of Array.isArray(v) ? v : [v ?? ""]) add(key, item);
    }
    const own = body.replace(BLOCK, "");
    for (const line of own.split(/\r?\n/)) {
      const field = /^\s*(?:[-*]\s*)?([A-Za-z_][\w-]*)::\s*(.+)$/.exec(line);
      if (field) add(field[1], field[2]);
      else for (const m of line.matchAll(LINK)) edges.push({ from: id, to: target(m[1]), kind: "mentions", negated: false, note: n.path });
    }
  }
  return { edges, ids };
}

// ---------- the merged graph the agent asks ----------

export type KEdge = { from: string; to: string; kind: string; source: "code" | "note"; where: string; negated?: boolean };
export type Knowledge = { nodes: Map<string, { id: string; type: string; name: string; scope?: string }>; out: Map<string, KEdge[]>; inc: Map<string, KEdge[]>; edges: number };

export function buildKnowledge(graphs: readonly Graph[], curated: readonly CuratedEdge[]): Knowledge {
  const nodes: Knowledge["nodes"] = new Map();
  const seen = new Map<string, KEdge>();
  for (const g of graphs) {
    for (const n of g.nodes) if (!nodes.has(n.id)) nodes.set(n.id, n);
    for (const e of g.edges) {
      if (e.kind === "dynamic") continue;
      const key = `${e.from}|${e.kind}|${e.to}`;
      if (!seen.has(key)) seen.set(key, { from: e.from, to: e.to, kind: e.kind, source: "code", where: `${g.package ?? ""} ${evidenceOf(e)}`.trim() });
    }
  }
  for (const c of curated) {
    for (const id of [c.from, c.to]) {
      if (!nodes.has(id)) nodes.set(id, { id, type: id.split(":")[0], name: id.split(":").slice(1).join(":") });
    }
    const key = `${c.from}|${c.kind}|${c.to}`;
    if (c.negated) {
      const code = seen.get(key);
      if (code) code.negated = true;
      continue;
    }
    if (!seen.has(key) || seen.get(key)!.source === "code") seen.set(key, { from: c.from, to: c.to, kind: c.kind, source: "note", where: c.note });
  }
  const out: Knowledge["out"] = new Map();
  const inc: Knowledge["inc"] = new Map();
  for (const e of seen.values()) {
    if (e.negated) continue;
    out.set(e.from, [...(out.get(e.from) ?? []), e]);
    inc.set(e.to, [...(inc.get(e.to) ?? []), e]);
  }
  return { nodes, out, inc, edges: [...seen.values()].filter((e) => !e.negated).length };
}

const RANK = ["TRAN", "PROG", "FUGR", "FUNC", "CLAS", "INTF", "TABL", "VIEW", "PROCESS", "NOTE", "PACKAGE", "STRU", "DTEL", "INCL"];
/** `ZSDR24730`, `PROG:ZSDR24730`, `PROG ZSDR24730` or a note's name → a node id. */
export function resolveRef(K: Knowledge, ref: string): string | null {
  const r = ref.trim().replace(/^\[\[|\]\]$/g, "");
  if (K.nodes.has(r)) return r;
  const up = r.toUpperCase();
  if (K.nodes.has(up)) return up;
  const spaced = /^([A-Z]+) (.+)$/.exec(r);
  if (spaced && K.nodes.has(`${spaced[1]}:${spaced[2]}`)) return `${spaced[1]}:${spaced[2]}`;
  if (K.nodes.has(`NOTE:${r}`)) return `NOTE:${r}`;
  const hits = [...K.nodes.values()].filter((n) => n.name === r || n.name.toUpperCase() === up);
  if (!hits.length) return null;
  return hits.sort((a, b) => (a.scope === "member" ? 0 : 1) - (b.scope === "member" ? 0 : 1) || (RANK.indexOf(a.type) + 1 || 99) - (RANK.indexOf(b.type) + 1 || 99))[0].id;
}

/** Loads the account's graphs and its uploaded notes into one graph. */
export function loadKnowledge(space: AccountSpace, notes: readonly { path: string; text: string }[]): Knowledge | null {
  const graphs = listGraphs(space).map((ref) => JSON.parse(readFileSync(ref.file, "utf8")) as Graph);
  const curated = curatedEdges(notes).edges;
  if (graphs.length === 0 && curated.length === 0) return null;
  return buildKnowledge(graphs, curated);
}

/** A signature that changes when any graph file changes — for caching `loadKnowledge`. */
export function graphsSignature(space: AccountSpace): string {
  return listGraphs(space).map((g) => `${g.file}:${statSync(g.file).mtimeMs}`).join("|");
}

/** The plugin's own `components` (process candidates) for one graph. */
export async function componentsOf(pluginPath: string, graph: Graph): Promise<Component[]> {
  try {
    const q = (await import(pathToFileURL(join(pluginPath, "scripts", "graph", "graph-query.mjs")).href)) as {
      loadGraph: (g: Graph) => unknown;
      components: (G: unknown) => { components: Component[] };
    };
    return q.components(q.loadGraph(graph)).components.filter((c) => c.members.length > 1);
  } catch {
    return [];
  }
}

export function readGraph(file: string): Graph {
  return JSON.parse(readFileSync(file, "utf8")) as Graph;
}

toolUseResult.content:
/**
 * The CBO reference graph as an Obsidian vault, and back.
 *
 *   out  graph.json (the plugin's analyze-cbo-obj / package-to-process) →
 *        one note per object, its relations as Dataview inline fields
 *        (`reads:: [[TABL VBAK]]`), so Obsidian's graph view draws them —
 *        plus a note per package and per process (the plugin's `components`).
 *        Zipped for the member to unpack into the vault.
 *   back the vault, uploaded as reference notes (`notes.ts`) → the relations
 *        the member wrote outside the generated blocks: `belongs_to:: [[…]]`,
 *        `not_reads:: [[…]]` to strike a relation the source parse got wrong,
 *        plain `[[links]]` as `mentions`. Merged with every graph of the
 *        account into one knowledge graph the agent queries (`notes.ts`).
 *
 * The generated part of a note sits between `<!-- sc4sap:begin PKG -->` and
 * `<!-- sc4sap:end PKG -->`, one block per package, so exporting again
 * replaces only that block. Everything else — the member's text, their
 * properties, their fields — is kept, provided the vault was uploaded before
 * the export: an export merges into the uploaded copy, then the member
 * unpacks the zip over the vault.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, relative, sep } from "node:path";
import { pathToFileURL } from "node:url";
import type { AccountSpace } from "./accounts.ts";

type GNode = { id: string; type: string; name: string; scope?: string; lines?: number; parent?: string };
type Evidence = { unit?: string; line?: number; text?: string };
type GEdge = { from: string; to: string; kind: string; count?: number; confidence?: string; evidence?: Evidence[] };
type Graph = { package?: string; module?: string; system?: string; builtAt?: string; nodes: GNode[]; edges: GEdge[] };

export type GraphRef = {
  id: string;
  package: string;
  module: string;
  system: string;
  builtAt: string | null;
  nodes: number;
  edges: number;
  file: string;
};

/** What the default export draws. `types` (DDIC typing) alone is over half of a real graph. */
const DEFAULT_KINDS = new Set(["reads", "writes", "calls", "submits", "starts", "launches", "uses"]);
const DETAIL_HIDDEN_TYPES = new Set(["DTEL", "DOMA", "INCL", "DYN", "TTYP", "STRU"]);
const BEGIN = (pkg: string) => `<!-- sc4sap:begin ${pkg} -->`;
const END = (pkg: string) => `<!-- sc4sap:end ${pkg} -->`;
const BLOCK = /<!-- sc4sap:begin ([^ ]+) -->[\s\S]*?<!-- sc4sap:end \1 -->\n?/g;

// ---------- finding the account's graphs ----------

/** Every `cbo/<MODULE>/<PACKAGE>/graph.json` under the account's session folders. */
export function listGraphs(space: AccountSpace): GraphRef[] {
  if (!space.home) return [];
  const found: GraphRef[] = [];
  const visit = (dir: string, depth: number): void => {
    if (depth > 9 || !existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name.startsWith("_prev") || entry.name === "notes") continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) visit(full, depth + 1);
      else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") {
        try {
          const g = JSON.parse(readFileSync(full, "utf8")) as Graph;
          const parts = full.split(sep);
          found.push({
            id: createHash("sha1").update(relative(space.root, full)).digest("hex").slice(0, 12),
            package: g.package ?? parts[parts.length - 2],
            module: g.module ?? parts[parts.length - 3],
            system: g.system ?? "SAP",
            builtAt: g.builtAt ?? null,
            nodes: g.nodes.length,
            edges: g.edges.length,
            file: full,
          });
        } catch {
          // A half-written or foreign graph.json is not one of ours.
        }
      }
    }
  };
  visit(join(space.root, "ws"), 0);
  return found.sort((a, b) => (a.system + a.package).localeCompare(b.system + b.package));
}

// ---------- names and tiny YAML ----------

/** `PROG:ZX` → `PROG ZX` — the note's file name and its link target. */
export function noteFile(id: string): string {
  const at = id.indexOf(":");
  const type = at > 0 ? id.slice(0, at) : "NOTE";
  const name = at > 0 ? id.slice(at + 1) : id;
  return `${type} ${name}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();
}
const link = (id: string) => `[[${noteFile(id)}]]`;

type Front = { keys: string[]; values: Map<string, string | string[]> };

/** Front matter of the shape this file writes, and of Obsidian's property editor: scalars and lists. */
export function splitFront(text: string): { front: Front; body: string } {
  const values = new Map<string, string | string[]>();
  const keys: string[] = [];
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
  if (!m) return { front: { keys, values }, body: text };
  let current: string | null = null;
  for (const raw of m[1].split(/\r?\n/)) {
    const item = /^\s+-\s+(.*)$/.exec(raw);
    if (item && current) {
      const list = values.get(current);
      values.set(current, [...(Array.isArray(list) ? list : []), unquote(item[1])]);
      continue;
    }
    const kv = /^([^\s:#][^:]*):\s*(.*)$/.exec(raw);
    if (!kv) continue;
    current = kv[1].trim();
    keys.push(current);
    const v = kv[2].trim();
    if (v === "") values.set(current, []);
    else if (v.startsWith("[") && v.endsWith("]") && !v.startsWith("[[")) {
      values.set(current, v.slice(1, -1).split(",").map((s) => unquote(s.trim())).filter(Boolean));
    } else values.set(current, unquote(v));
  }
  return { front: { keys, values }, body: text.slice(m[0].length) };
}
function unquote(v: string): string {
  return /^".*"$/.test(v) || /^'.*'$/.test(v) ? v.slice(1, -1).replace(/\\"/g, '"') : v;
}
function yamlValue(v: string): string {
  return /^[\w .\-/가-힣]*$/.test(v) && v !== "" && !/^(true|false|null|-|\d)/i.test(v) ? v : JSON.stringify(v);
}
function joinFront(front: Front, body: string): string {
  const lines: string[] = [];
  for (const key of front.keys) {
    const v = front.values.get(key);
    if (Array.isArray(v)) lines.push(v.length ? `${key}:\n${v.map((x) => `  - ${yamlValue(x)}`).join("\n")}` : `${key}: []`);
    else if (v !== undefined) lines.push(`${key}: ${yamlValue(v)}`);
  }
  return `---\n${lines.join("\n")}\n---\n${body.startsWith("\n") ? "" : "\n"}${body}`;
}
function setFront(front: Front, key: string, value: string | string[]): void {
  if (!front.keys.includes(key)) front.keys.push(key);
  front.values.set(key, value);
}

/** Puts this package's generated block into a note, replacing an older one, keeping the rest. */
function mergeNote(existing: string | null, pkg: string, block: string, props: Record<string, string | string[]>, title: string): string {
  const { front, body } = existing ? splitFront(existing) : { front: { keys: [], values: new Map() } as Front, body: `# ${title}\n\n## 메모\n\n` };
  for (const [key, value] of Object.entries(props)) {
    if (key === "packages" && Array.isArray(value)) {
      const had = front.values.get("packages");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])].sort());
    } else if (key === "tags" && Array.isArray(value)) {
      const had = front.values.get("tags");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])]);
    } else setFront(front, key, value);
  }
  const wrapped = `${BEGIN(pkg)}\n${block.trim()}\n${END(pkg)}\n`;
  const own = new RegExp(`${escape(BEGIN(pkg))}[\\s\\S]*?${escape(END(pkg))}\\n?`);
  let next: string;
  if (own.test(body)) next = body.replace(own, wrapped);
  else if (/^## 메모\s*$/m.test(body)) next = body.replace(/^## 메모\s*$/m, `${wrapped}\n## 메모`);
  else next = `${body.trimEnd()}\n\n${wrapped}`;
  return joinFront(front, next);
}
const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// ---------- export ----------

export type VaultOptions = { detail?: boolean; system: string; existing: (path: string) => string | null; components?: Component[] };
type Component = { entries: string[]; members: string[]; writes: string[]; sharedTables: { table: string; writers: string[]; readers: string[] }[] };

function evidenceOf(e: GEdge): string {
  const ev = e.evidence?.[0];
  const where = ev?.unit ? `${ev.unit}${ev.line ? `:${ev.line}` : ""}` : "";
  return [where, e.confidence === "low" ? "low" : "", e.count && e.count > 1 ? `×${e.count}` : ""].filter(Boolean).join(" · ");
}

/** The vault's files for one package graph, merged into what the member already has. */
export function buildVault(graph: Graph, opts: VaultOptions): Map<string, string> {
  const pkg = graph.package ?? "PACKAGE";
  const base = `SC4SAP/${noteFile(`X:${opts.system}`).slice(2)}`;
  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
  const hidden = (id: string) => !opts.detail && DETAIL_HIDDEN_TYPES.has(nodes.get(id)?.type ?? "");
  const edges = graph.edges.filter(
    (e) => (opts.detail ? e.kind !== "dynamic" : DEFAULT_KINDS.has(e.kind)) && !hidden(e.from) && !hidden(e.to),
  );
  const kept = new Set<string>();
  for (const e of edges) kept.add(e.from).add(e.to);
  for (const n of graph.nodes) if (n.scope === "member" && !hidden(n.id) && n.type !== "INCL") kept.add(n.id);

  const out = new Map<string, GEdge[]>();
  for (const e of edges) out.set(e.from, [...(out.get(e.from) ?? []), e]);
  const files = new Map<string, string>();
  const put = (path: string, block: string, props: Record<string, string | string[]>, title: string) =>
    files.set(path, mergeNote(opts.existing(path), pkg, block, props, title));

  for (const id of kept) {
    const n = nodes.get(id) ?? { id, type: id.split(":")[0], name: id.split(":").slice(1).join(":") };
    const rel = (out.get(id) ?? [])
      .sort((a, b) => a.kind.localeCompare(b.kind) || a.to.localeCompare(b.to))
      .map((e) => `- ${e.kind}:: ${link(e.to)}${evidenceOf(e) ? ` — ${evidenceOf(e)}` : ""}`);
    const block = rel.length ? `### ${pkg}\n${rel.join("\n")}` : `### ${pkg}\n(no outgoing relations in the source parse)`;
    put(`${base}/objects/${noteFile(id)}.md`, block, {
      sc4sap_id: id,
      type: n.type,
      scope: n.scope ?? "",
      system: opts.system,
      packages: [pkg],
      ...(n.lines ? { lines: String(n.lines) } : {}),
      tags: [`sc4sap/${n.type.toLowerCase()}`, `sc4sap/${n.scope ?? "other"}`],
    }, n.name);
  }

  const comps = opts.components ?? [];
  comps.forEach((c, i) => {
    const entry = nodes.get(c.entries[0])?.name ?? c.entries[0];
    const path = `${base}/processes/${noteFile(`X:${pkg} P${String(i + 1).padStart(2, "0")} ${entry}`).slice(2)}.md`;
    const lines = [
      `### ${pkg}`,
      `- package:: [[PACKAGE ${pkg}]]`,
      ...c.entries.map((e) => `- entry:: ${link(e)}`),
      ...c.members.filter((m) => kept.has(m)).map((m) => `- member:: ${link(m)}`),
      ...c.sharedTables.map((t) => `- handoff:: ${link(t.table)} — ${t.writers.map((w) => nodes.get(w)?.name ?? w).join(", ")} → ${t.readers.map((r) => nodes.get(r)?.name ?? r).join(", ") || "(written only)"}`),
    ];
    put(path, lines.join("\n"), { sc4sap_id: `PROCESS:${pkg}:${i + 1}`, type: "PROCESS", system: opts.system, packages: [pkg], tags: ["sc4sap/process"] }, `${pkg} P${i + 1} — ${entry}`);
  });

  const byType = new Map<string, string[]>();
  for (const id of kept) {
    const n = nodes.get(id);
    if (n?.scope !== "member") continue;
    byType.set(n.type, [...(byType.get(n.type) ?? []), id]);
  }
  const index = [
    `### ${pkg}`,
    `${graph.module ? `Module ${graph.module} · ` : ""}${kept.size} objects · ${edges.length} relations${opts.detail ? " (detail)" : ""} · built ${graph.builtAt ?? "?"}`,
    ...[...byType.entries()].sort().flatMap(([type, ids]) => [`#### ${type}`, ...ids.sort().map((id) => `- member:: ${link(id)}`)]),
    ...(comps.length ? ["#### Processes", ...comps.map((_, i) => `- process:: [[${pkg} P${String(i + 1).padStart(2, "0")} ${nodes.get(comps[i].entries[0])?.name ?? comps[i].entries[0]}]]`)] : []),
  ];
  put(`${base}/packages/PACKAGE ${noteFile(`X:${pkg}`).slice(2)}.md`, index.join("\n"), { sc4sap_id: `PACKAGE:${pkg}`, type: "PACKAGE", system: opts.system, packages: [pkg], tags: ["sc4sap/package"] }, pkg);

  files.set(`${base}/SC4SAP 사용법.md`, opts.existing(`${base}/SC4SAP 사용법.md`) ?? GUIDE);
  return files;
}

const GUIDE = `# SC4SAP 그래프 사용법

이 폴더는 SC4SAP이 소스를 분석해 만든 관계 그래프예요.

- \`<!-- sc4sap:begin … -->\` 와 \`<!-- sc4sap:end … -->\` 사이는 다시 내보낼 때 바뀌어요. 그 밖에 쓴 내용은 그대로 남아요.
- 관계를 더하려면 그 밖에 한 줄을 써요. 예: \`belongs_to:: [[출하 프로세스]]\`
- 소스 분석이 틀린 관계를 지우려면 \`not_\`을 붙여요. 예: \`not_reads:: [[TABL VBAK]]\`
- 그냥 \`[[링크]]\`를 걸면 "언급" 관계가 돼요.
- 다듬은 뒤 SC4SAP 설정 → 참고 노트에서 볼트 폴더를 다시 올리면 에이전트가 그 관계로 답해요.
- 다시 내보내기 전에도 먼저 올려 주세요. 그래야 메모가 덮이지 않아요.
`;

// ---------- zip (stored, UTF-8 names) ----------

const CRC = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

export function zip(files: Map<string, string>): Buffer {
  const chunks: Buffer[] = [];
  const central: Buffer[] = [];
  let offset = 0;
  for (const [path, text] of files) {
    const name = Buffer.from(path, "utf8");
    const data = Buffer.from(text, "utf8");
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6); // UTF-8 names
    local.writeUInt16LE(0, 8); // stored
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    chunks.push(local, name, data);
    const head = Buffer.alloc(46);
    head.writeUInt32LE(0x02014b50, 0);
    head.writeUInt16LE(20, 4);
    head.writeUInt16LE(20, 6);
    head.writeUInt16LE(0x0800, 8);
    head.writeUInt32LE(crc, 16);
    head.writeUInt32LE(data.length, 20);
    head.writeUInt32LE(data.length, 24);
    head.writeUInt16LE(name.length, 28);
    head.writeUInt32LE(offset, 42);
    central.push(head, name);
    offset += 30 + name.length + data.length;
  }
  const dir = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(files.size, 8);
  end.writeUInt16LE(files.size, 10);
  end.writeUInt32LE(dir.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...chunks, dir, end]);
}

// ---------- back: the member's relations ----------

export type CuratedEdge = { from: string; to: string; kind: string; negated: boolean; note: string };
const OUR_KEYS = new Set(["sc4sap_id", "type", "scope", "system", "packages", "lines", "tags", "created", "source", "skill", "aliases", "cssclasses"]);
const LINK = /\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]/g;

/** The relations the member wrote, from uploaded notes: `{ path, text }` as `notes.ts` stores them. */
export function curatedEdges(notes: readonly { path: string; text: string }[]): { edges: CuratedEdge[]; ids: Map<string, string> } {
  const ids = new Map<string, string>();
  const parsed = notes.map((n) => {
    const { front, body } = splitFront(n.text);
    const file = n.path.split("/").pop()!.replace(/\.md$/i, "");
    const id = typeof front.values.get("sc4sap_id") === "string" ? (front.values.get("sc4sap_id") as string) : `NOTE:${file}`;
    ids.set(file, id);
    return { n, front, body, id };
  });
  const target = (name: string) => ids.get(name.trim()) ?? `NOTE:${name.trim()}`;
  const edges: CuratedEdge[] = [];
  for (const { n, front, body, id } of parsed) {
    const add = (key: string, value: string) => {
      const negated = key.startsWith("not_");
      const kind = negated ? key.slice(4) : key;
      for (const m of value.matchAll(LINK)) edges.push({ from: id, to: target(m[1]), kind, negated, note: n.path });
    };
    for (const key of front.keys) {
      if (OUR_KEYS.has(key)) continue;
      const v = front.values.get(key);
      for (const item of Array.isArray(v) ? v : [v ?? ""]) add(key, item);
    }
    const own = body.replace(BLOCK, "");
    for (const line of own.split(/\r?\n/)) {
      const field = /^\s*(?:[-*]\s*)?([A-Za-z_][\w-]*)::\s*(.+)$/.exec(line);
      if (field) add(field[1], field[2]);
      else for (const m of line.matchAll(LINK)) edges.push({ from: id, to: target(m[1]), kind: "mentions", negated: false, note: n.path });
    }
  }
  return { edges, ids };
}

// ---------- the merged graph the agent asks ----------

export type KEdge = { from: string; to: string; kind: string; source: "code" | "note"; where: string; negated?: boolean };
export type Knowledge = { nodes: Map<string, { id: string; type: string; name: string; scope?: string }>; out: Map<string, KEdge[]>; inc: Map<string, KEdge[]>; edges: number };

export function buildKnowledge(graphs: readonly Graph[], curated: readonly CuratedEdge[]): Knowledge {
  const nodes: Knowledge["nodes"] = new Map();
  const seen = new Map<string, KEdge>();
  for (const g of graphs) {
    for (const n of g.nodes) if (!nodes.has(n.id)) nodes.set(n.id, n);
    for (const e of g.edges) {
      if (e.kind === "dynamic") continue;
      const key = `${e.from}|${e.kind}|${e.to}`;
      if (!seen.has(key)) seen.set(key, { from: e.from, to: e.to, kind: e.kind, source: "code", where: `${g.package ?? ""} ${evidenceOf(e)}`.trim() });
    }
  }
  for (const c of curated) {
    for (const id of [c.from, c.to]) {
      if (!nodes.has(id)) nodes.set(id, { id, type: id.split(":")[0], name: id.split(":").slice(1).join(":") });
    }
    const key = `${c.from}|${c.kind}|${c.to}`;
    if (c.negated) {
      const code = seen.get(key);
      if (code) code.negated = true;
      continue;
    }
    if (!seen.has(key) || seen.get(key)!.source === "code") seen.set(key, { from: c.from, to: c.to, kind: c.kind, source: "note", where: c.note });
  }
  const out: Knowledge["out"] = new Map();
  const inc: Knowledge["inc"] = new Map();
  for (const e of seen.values()) {
    if (e.negated) continue;
    out.set(e.from, [...(out.get(e.from) ?? []), e]);
    inc.set(e.to, [...(inc.get(e.to) ?? []), e]);
  }
  return { nodes, out, inc, edges: [...seen.values()].filter((e) => !e.negated).length };
}

const RANK = ["TRAN", "PROG", "FUGR", "FUNC", "CLAS", "INTF", "TABL", "VIEW", "PROCESS", "NOTE", "PACKAGE", "STRU", "DTEL", "INCL"];
/** `ZSDR24730`, `PROG:ZSDR24730`, `PROG ZSDR24730` or a note's name → a node id. */
export function resolveRef(K: Knowledge, ref: string): string | null {
  const r = ref.trim().replace(/^\[\[|\]\]$/g, "");
  if (K.nodes.has(r)) return r;
  const up = r.toUpperCase();
  if (K.nodes.has(up)) return up;
  const spaced = /^([A-Z]+) (.+)$/.exec(r);
  if (spaced && K.nodes.has(`${spaced[1]}:${spaced[2]}`)) return `${spaced[1]}:${spaced[2]}`;
  if (K.nodes.has(`NOTE:${r}`)) return `NOTE:${r}`;
  const hits = [...K.nodes.values()].filter((n) => n.name === r || n.name.toUpperCase() === up);
  if (!hits.length) return null;
  return hits.sort((a, b) => (a.scope === "member" ? 0 : 1) - (b.scope === "member" ? 0 : 1) || (RANK.indexOf(a.type) + 1 || 99) - (RANK.indexOf(b.type) + 1 || 99))[0].id;
}

/** Loads the account's graphs and its uploaded notes into one graph. */
export function loadKnowledge(space: AccountSpace, notes: readonly { path: string; text: string }[]): Knowledge | null {
  const graphs = listGraphs(space).map((ref) => JSON.parse(readFileSync(ref.file, "utf8")) as Graph);
  const curated = curatedEdges(notes).edges;
  if (graphs.length === 0 && curated.length === 0) return null;
  return buildKnowledge(graphs, curated);
}

/** A signature that changes when any graph file changes — for caching `loadKnowledge`. */
export function graphsSignature(space: AccountSpace): string {
  return listGraphs(space).map((g) => `${g.file}:${statSync(g.file).mtimeMs}`).join("|");
}

/** The plugin's own `components` (process candidates) for one graph. */
export async function componentsOf(pluginPath: string, graph: Graph): Promise<Component[]> {
  try {
    const q = (await import(pathToFileURL(join(pluginPath, "scripts", "graph", "graph-query.mjs")).href)) as {
      loadGraph: (g: Graph) => unknown;
      components: (G: unknown) => { components: Component[] };
    };
    return q.components(q.loadGraph(graph)).components.filter((c) => c.members.length > 1);
  } catch {
    return [];
  }
}

export function readGraph(file: string): Graph {
  return JSON.parse(readFileSync(file, "utf8")) as Graph;
}

