/** The notes as `vault.ts` reads them back — the same cached copy search uses. */
export function notesOf(space: AccountSpace): readonly { path: string; text: string }[] {
  return space.home ? loaded(notesDir(space)) : [];
}

/** One knowledge graph per account folder, rebuilt when a graph file or the notes change. */
const knowledgeCache = new Map<string, { signature: string; notes: readonly unknown[]; graph: Knowledge | null }>();

export function knowledgeOf(space: AccountSpace): Knowledge | null {
  if (!space.home) return null;
  const notes = notesOf(space);
  const signature = graphsSignature(space);
  const hit = knowledgeCache.get(space.root);
  if (hit && hit.signature === signature && hit.notes === notes) return hit.graph;
  const graph = loadKnowledge(space, notes);
  knowledgeCache.set(space.root, { signature, notes, graph });
  return graph;
}

const text = (body: string) => ({ content: [{ type: "text" as const, text: body }] });
const LIST_LIMIT = 80;

function describe(K: Knowledge, e: KEdge, toward: "out" | "in"): string {
  const other = toward === "out" ? e.to : e.from;
  const arrow = toward === "out" ? `→ ${e.kind}` : `← ${e.kind} (by)`;
  return `${arrow} ${other}  [${e.source}: ${e.where}]`;
}

/**
 * The session's `notes` MCP server. Built per session over that session's
 * account only:
 *   SearchNotes / ReadNote      when the account has uploaded notes
 *   GraphNeighbors / Impact / Path  when it has a CBO graph or relations in its notes
 * `null` when there is nothing for either — a tool that can only ever answer
 * "nothing" is noise in the agent's tool list.
 */
export function notesServer(space: AccountSpace): { server: ReturnType<typeof createSdkMcpServer>; tools: string[] } | null {
  if (!space.home) return null;
  const hasNotes = summarize(space).count > 0;
  const hasGraph = knowledgeOf(space) !== null;
  if (!hasNotes && !hasGraph) return null;

  const tools = [];
  if (hasNotes) {
    tools.push(
      tool(
        "SearchNotes",
        "Search the member's own reference notes (Markdown uploaded from their Obsidian vault: internal design notes, conventions, process descriptions). Returns note paths with a short snippet; read a note in full with ReadNote. Use it when the question may depend on this company's own documents. Try other words if nothing matches.",
        { query: z.string().describe("Words to look for, e.g. a program name, table, process or term") },
        async ({ query }) => {
          const hits = searchNotes(space, query);
          return text(
            hits.length
              ? hits.map((hit) => `- ${hit.path}\n  ${hit.snippet}`).join("\n")
              : "No note matches. Try other words, or answer without the notes.",
          );
        },
      ),
      tool(
        "ReadNote",
        "Read one of the member's reference notes in full, by the path SearchNotes returned.",
        { path: z.string().describe("Path exactly as SearchNotes listed it") },
        async ({ path }) => {
          const body = readNote(space, path);
          return { ...text(body ?? `No note at ${path}.`), ...(body === null ? { isError: true } : {}) };
        },
      ),
    );
  }
  if (hasGraph) {
    const object = z.string().describe("An object: ZSDR24730, PROG:ZSDR24730, TABL:VBAK, a TCode, or a note's name such as 출하 프로세스");
    const need = (ref: string) => {
      const K = knowledgeOf(space);
      const id = K ? resolveRef(K, ref) : null;
      return { K, id };
    };
    tools.push(
      tool(
        "GraphNeighbors",
        "The member's knowledge graph of their SAP custom code: relations parsed from ABAP source (reads, writes, calls, submits, starts, launches, uses, types, include) merged with relations the member added in Obsidian (any name, e.g. belongs_to; struck ones removed). Lists one object's direct relations with where each comes from — a source line or a note. Use it before guessing how programs, tables and processes connect.",
        {
          object,
          direction: z.enum(["out", "in", "both"]).optional().describe("out = what it uses, in = what uses it; default both"),
          kinds: z.string().optional().describe("Comma-separated relation kinds to keep, e.g. reads,writes"),
        },
        async ({ object: ref, direction = "both", kinds }) => {
          const { K, id } = need(ref);
          if (!K || !id) return text(`No object ${ref} in the graph.`);
          const keep = kinds ? new Set(kinds.split(",").map((k) => k.trim()).filter(Boolean)) : null;
          const pick = (list: KEdge[] | undefined) => (list ?? []).filter((e) => !keep || keep.has(e.kind));
          const lines = [
            ...(direction !== "in" ? pick(K.out.get(id)).map((e) => describe(K, e, "out")) : []),
            ...(direction !== "out" ? pick(K.inc.get(id)).map((e) => describe(K, e, "in")) : []),
          ];
          const shown = lines.slice(0, LIST_LIMIT);
          return text(`${id}\n${shown.join("\n") || "(no relations)"}${lines.length > shown.length ? `\n… ${lines.length - shown.length} more; narrow with kinds` : ""}`);
        },
      ),
      tool(
        "GraphImpact",
        "What would be affected by changing an object: everything that reaches it through the member's knowledge graph (incoming relations, transitively), nearest first, with the relation each step goes through. DDIC typing is left out unless asked.",
        {
          object,
          depth: z.number().int().min(1).max(6).optional().describe("How many steps back; default 3"),
          includeTypes: z.boolean().optional().describe("Also follow DDIC typing (types); default false"),
        },
        async ({ object: ref, depth = 3, includeTypes = false }) => {
          const { K, id } = need(ref);
          if (!K || !id) return text(`No object ${ref} in the graph.`);
          const seen = new Map<string, { d: number; via: string }>([[id, { d: 0, via: "" }]]);
          let frontier = [id];
          for (let d = 1; d <= depth && frontier.length; d++) {
            const next: string[] = [];
            for (const at of frontier) {
              for (const e of K.inc.get(at) ?? []) {
                if (!includeTypes && e.kind === "types") continue;
                if (seen.has(e.from)) continue;
                seen.set(e.from, { d, via: `${e.kind} ${at} [${e.source}]` });
                next.push(e.from);
              }
            }
            frontier = next;
          }
          const rows = [...seen.entries()].filter(([x]) => x !== id).sort((a, b) => a[1].d - b[1].d);
          const shown = rows.slice(0, LIST_LIMIT * 2).map(([x, v]) => `${v.d}  ${x}  via ${v.via}`);
          return text(`${id} — ${rows.length} affected within ${depth}\n${shown.join("\n")}${rows.length > shown.length ? `\n… ${rows.length - shown.length} more` : ""}`);
        },
      ),
      tool(
        "GraphPath",
        "How two objects connect in the member's knowledge graph: the shortest chain of relations between them, in either direction, up to 6 steps.",
        { from: object, to: object },
        async ({ from, to }) => {
          const a = need(from);
          const b = need(to);
          if (!a.K || !a.id || !b.id) return text(`Unknown object: ${!a.id ? from : to}`);
          const K = a.K;
          const prev = new Map<string, { at: string; edge: KEdge; forward: boolean } | null>([[a.id, null]]);
          let frontier = [a.id];
          for (let d = 0; d < 6 && frontier.length && !prev.has(b.id); d++) {
            const next: string[] = [];
            for (const at of frontier) {
              const steps = [
                ...(K.out.get(at) ?? []).map((edge) => ({ to: edge.to, edge, forward: true })),
                ...(K.inc.get(at) ?? []).map((edge) => ({ to: edge.from, edge, forward: false })),
              ];
              for (const s of steps) {
                if (prev.has(s.to)) continue;
                prev.set(s.to, { at, edge: s.edge, forward: s.forward });
                next.push(s.to);
              }
            }
            frontier = next;
          }
          if (!prev.has(b.id)) return text(`No path within 6 steps between ${a.id} and ${b.id}.`);
          const chain: string[] = [];
          for (let at = b.id; prev.get(at); at = prev.get(at)!.at) {
            const p = prev.get(at)!;
            chain.unshift(p.forward ? `${p.at} —${p.edge.kind}→ ${at} [${p.edge.source}]` : `${at} —${p.edge.kind}→ ${p.at} [${p.edge.source}]`);
          }
          return text(chain.join("\n"));
        },
      ),
    );
  }
  return {
    server: createSdkMcpServer({ name: "notes", version: "1.1.0", tools }),
    tools: [
      ...(hasNotes ? ["mcp__notes__SearchNotes", "mcp__notes__ReadNote"] : []),
      ...(hasGraph ? ["mcp__notes__GraphNeighbors", "mcp__notes__GraphImpact", "mcp__notes__GraphPath"] : []),
    ],
  };
}
