                ...(K.out.get(at) ?? []).map((edge) => ({ to: edge.to, edge, forward: true })),
                ...(K.inc.get(at) ?? []).map((edge) => ({ to: edge.from, edge, forward: false })),
              ];
              for (const s of steps) {
                if (prev.has(s.to)) continue;
                prev.set(s.to, { at, edge: s.edge, forward: s.forward });
                next.push(s.to);
              }
            }
            frontier = next;
          }
          if (!prev.has(b.id)) return text(`No path within 6 steps between ${a.id} and ${b.id}.`);
          const chain: string[] = [];
          for (let at = b.id; prev.get(at); at = prev.get(at)!.at) {
            const p = prev.get(at)!;
            chain.unshift(
              p.forward
                ? `${p.at} —${p.edge.kind}→ ${at} [${p.edge.source}]`
                : `${at} —${p.edge.kind}→ ${p.at} [${p.edge.source}]`,
            );
          }
          return text(chain.join("\n"));
        },
      ),
    );
  }
  return {
    server: createSdkMcpServer({ name: "notes", version: "1.1.0", tools }),
    tools: [
      ...(hasNotes ? ["mcp__notes__SearchNotes", "mcp__notes__ReadNote"] : []),
      ...(hasGraph ? ["mcp__notes__GraphNeighbors", "mcp__notes__GraphImpact", "mcp__notes__GraphPath"] : []),
    ],
  };
}

