// Throwaway round-trip check of vault.ts on a real graph (read-only on it).
import assert from "node:assert/strict";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { buildKnowledge, buildVault, componentsOf, curatedEdges, readGraph, resolveRef, zip } from "./server/vault.ts";

const GRAPH = process.argv[2]!;
const OUT = process.argv[3]!;
const PLUGIN = join(process.cwd(), "plugin_module");

const graph = readGraph(GRAPH);
let t = Date.now();
const components = await componentsOf(PLUGIN, graph);
console.log(`components ${components.length} in ${Date.now() - t} ms`);
t = Date.now();
const first = buildVault(graph, { system: "HKT-DEV", existing: () => null, components });
console.log(`vault ${first.size} notes in ${Date.now() - t} ms`);

const prog = [...first.keys()].find((p) => p.includes("/objects/PROG ZSDR24730.md"))!;
assert.ok(prog, "ZSDR24730 note exists");
const progText = first.get(prog)!;
assert.match(progText, /^---\nsc4sap_id: PROG:ZSDR24730/);
assert.match(progText, /<!-- sc4sap:begin ZSD400 -->/);
const readLine = progText.split("\n").find((l) => l.startsWith("- reads:: [[TABL "))!;
assert.ok(readLine, "has a reads relation");
const readTarget = /\[\[(TABL [^\]]+)\]\]/.exec(readLine)![1]!;
console.log("sample:", readLine.slice(0, 90));

// The member edits in Obsidian.
const edited = progText.replace("## 메모", `## 메모\n\n이 프로그램은 수출 컨테이너 출하용이에요.\nbelongs_to:: [[출하 프로세스]]\nnot_reads:: [[${readTarget}]]\n예시: \`calls:: [[FUNC FAKE]]\`\n`);
const processNote = { path: "SC4SAP/HKT-DEV/출하 프로세스.md", text: "# 출하 프로세스\n\nstep:: [[PROG ZSDR24730]]\n관련 메모 [[PACKAGE ZSD400]]\n" };
const uploaded = [{ path: prog, text: edited }, processNote, ...[...first.entries()].filter(([p]) => p !== prog).slice(0, 50).map(([path, text]) => ({ path, text }))];

const { edges } = curatedEdges(uploaded);
const mine = edges.filter((e) => e.from === "PROG:ZSDR24730");
assert.ok(mine.some((e) => e.kind === "belongs_to" && e.to === "NOTE:출하 프로세스" && !e.negated), "belongs_to read");
assert.ok(mine.some((e) => e.kind === "reads" && e.negated), "not_reads read as a strike");
assert.ok(!edges.some((e) => e.to.includes("FAKE")), "code span ignored");
assert.ok(!edges.some((e) => e.note === prog && e.kind === "calls"), "generated block not read back");
assert.ok(edges.some((e) => e.from === "NOTE:출하 프로세스" && e.kind === "step" && e.to === "PROG:ZSDR24730"), "free note relation");
assert.ok(edges.some((e) => e.from === "NOTE:출하 프로세스" && e.kind === "mentions" && e.to === "PACKAGE:ZSD400"), "plain link = mentions");

const K = buildKnowledge([graph], edges);
const struck = readTarget.replace(" ", ":");
assert.ok(!(K.out.get("PROG:ZSDR24730") ?? []).some((e) => e.kind === "reads" && e.to === struck), "struck relation removed");
assert.ok((K.out.get("PROG:ZSDR24730") ?? []).some((e) => e.kind === "belongs_to" && e.source === "note"), "note relation merged");
assert.equal(resolveRef(K, "ZSDR24730"), "PROG:ZSDR24730");
assert.equal(resolveRef(K, "출하 프로세스"), "NOTE:출하 프로세스");
console.log(`knowledge: ${K.nodes.size} nodes, ${K.edges} edges`);

// Export again over the uploaded copy: the member's lines survive, the block is regenerated.
const second = buildVault(graph, { system: "HKT-DEV", existing: (p) => (p === prog ? edited : null), components });
const again = second.get(prog)!;
assert.ok(again.includes("belongs_to:: [[출하 프로세스]]") && again.includes("수출 컨테이너"), "member text kept");
assert.equal(again.match(/<!-- sc4sap:begin ZSD400 -->/g)?.length, 1, "one block, replaced not stacked");

const bytes = zip(first);
writeFileSync(OUT, bytes);
console.log(`zip ${(bytes.length / 1024 / 1024).toFixed(1)} MB`);
console.log("vault round trip: all passed");

