// Throwaway end-to-end check: graph → vault zip → edited note uploaded → agent uses the merged graph.
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { copyFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { ObjectId } from "mongodb";
import { sessions, users } from "./src/lib/mongo.ts";
import { saveConnection } from "./src/lib/setup-store.ts";
import { EMPTY_DRAFT } from "./src/lib/setup.ts";
import { PRIVACY_VERSION, TERMS_VERSION } from "./src/lib/consent.ts";
import { deleteAccount } from "./src/lib/retention.ts";

const APP = "http://localhost:3000";
const ACCOUNTS = join(process.cwd(), "..", "accounts");
const GRAPH = join(process.cwd(), "..", "..", ".sc4sap", "work", "HKT-DEV", "cbo", "SD", "ZSD400", "graph.json");
const now = new Date();
const out: string[] = [];
const check = (name: string, ok: boolean, detail = "") => out.push(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);

for (const old of await (await users()).find({ email: "graph-a@example.test" }).toArray()) await deleteAccount(old, "member");
const _id = new ObjectId();
const id = String(_id);
await (await users()).insertOne({
  _id, email: "graph-a@example.test", displayEmail: "graph-a@example.test", lastName: "그래프", firstName: "A", createdAt: now,
  consents: { terms: TERMS_VERSION, privacy: PRIVACY_VERSION, age: true, agreedAt: now, marketing: false, marketingAt: null, overseas: true },
} as never);
await saveConnection(id, { ...EMPTY_DRAFT, adtUrl: "http://g.sap.invalid:50000", sapUser: "G_A", sapPassword: randomBytes(12).toString("base64url"), abapRelease: "758", client: "100" });
const token = randomBytes(32).toString("base64url");
await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(token).digest("hex"), userId: id, createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
const call = async (path: string, init: RequestInit = {}) => {
  const r = await fetch(APP + path, { ...init, headers: { ...(init.body ? { "content-type": "application/json" } : {}), cookie: `sc4sap_session=${token}` } });
  return r;
};

try {
  // As if analyze-cbo-obj had run in one of the account's sessions.
  const dir = join(ACCOUNTS, id, "ws", "p-G-100", ".sc4sap", "work", "G-100", "cbo", "SD", "ZSD400");
  mkdirSync(dir, { recursive: true });
  copyFileSync(GRAPH, join(dir, "graph.json"));

  const list = (await (await call("/api/graphs")).json()) as { graphs: { id: string; package: string; nodes: number }[] };
  check("graph listed", list.graphs.length === 1 && list.graphs[0]?.package === "ZSD400", JSON.stringify(list.graphs).slice(0, 120));
  const zipRes = await call(`/api/graphs/${list.graphs[0]!.id}/vault.zip`);
  const bytes = Buffer.from(await zipRes.arrayBuffer());
  check("vault zip downloads", zipRes.ok && zipRes.headers.get("content-type") === "application/zip" && bytes.readUInt32LE(0) === 0x04034b50, `${(bytes.length / 1048576).toFixed(1)} MB`);

  // The member's edit in Obsidian, uploaded back (just two notes are enough).
  const note = "---\nsc4sap_id: \"PROG:ZSDR24730\"\ntype: PROG\n---\n# ZSDR24730\n\n## 메모\n\nbelongs_to:: [[수출 컨테이너 출하]]\n";
  const proc = "# 수출 컨테이너 출하\n\n담당: 물류팀. 컨테이너 최소 적재율 82%.\n";
  const up = await call("/api/notes", { method: "POST", body: JSON.stringify({ reset: true, files: [
    { path: "SC4SAP/G-100/objects/PROG ZSDR24730.md", text: note },
    { path: "SC4SAP/G-100/수출 컨테이너 출하.md", text: proc },
  ] }) });
  const upBody = (await up.json()) as { relations?: number };
  check("notes uploaded, relation read", up.ok && (upBody.relations ?? 0) >= 1, JSON.stringify(upBody).slice(0, 120));

  const s = await (await call("/api/sessions", { method: "POST", body: JSON.stringify({ model: "claude-haiku-4-5" }) })).json() as { session: { id: string } };
  const sid = s.session.id;
  const sent = await call(`/api/sessions/${sid}/messages`, { method: "POST", body: JSON.stringify({ text: "GraphNeighbors 도구로 ZSDR24730 의 belongs_to 관계를 확인해서, 이 프로그램이 속한 프로세스 이름만 한 줄로 답해 주세요. SAP 도구는 쓰지 마세요." }) });
  check("message accepted", sent.status === 202, String(sent.status));

  const stream = await fetch(`${APP}/api/sessions/${sid}/stream`, { headers: { cookie: `sc4sap_session=${token}` } });
  const reader = stream.body!.getReader();
  const decoder = new TextDecoder();
  let buf = "", text = "", done = false;
  const tools: string[] = [];
  const deadline = Date.now() + 150_000;
  while (!done && Date.now() < deadline) {
    const { value, done: end } = await Promise.race([reader.read(), new Promise<any>((r) => setTimeout(() => r({ value: undefined, done: false }), 5000))]);
    if (end) break;
    if (value) buf += decoder.decode(value, { stream: true });
    for (const line of buf.split("\n")) {
      if (!line.startsWith("data:")) continue;
      try {
        const raw = JSON.parse(line.slice(5)); const ev = raw.event ?? raw;
        if (ev.type === "tool_start" && ev.name) tools.push(ev.name);
        if (ev.type === "text_delta" && ev.text) text += ev.text;
        if (ev.type === "status" && ev.status === "idle" && (tools.length || text)) done = true;
      } catch {}
    }
    buf = buf.slice(buf.lastIndexOf("\n") + 1);
  }
  await reader.cancel().catch(() => {});
  check("agent used GraphNeighbors", tools.some((t) => t.includes("GraphNeighbors")), tools.join(","));
  check("answer names the member's process", text.includes("수출 컨테이너 출하"), text.slice(0, 160).replace(/\n/g, " "));
} finally {
  const doc = await (await users()).findOne({ _id });
  try { if (doc) await deleteAccount(doc, "member"); } catch (e) { out.push(`FAIL cleanup: ${(e as Error).message}`); }
  console.log(out.join("\n"));
  process.exit(out.some((l) => l.startsWith("FAIL")) ? 1 : 0);
}

