51	// ---------- finding the account's graphs ----------
52	
53	/** Every `cbo/<MODULE>/<PACKAGE>/graph.json` under the account's session folders. */
54	export function listGraphs(space: AccountSpace): GraphRef[] {
55	  if (!space.home) return [];
56	  const found: GraphRef[] = [];
57	  const visit = (dir: string, depth: number): void => {
58	    if (depth > 9 || !existsSync(dir)) return;
59	    for (const entry of readdirSync(dir, { withFileTypes: true })) {
60	      if (entry.name === "node_modules" || entry.name.startsWith("_prev") || entry.name === "notes") continue;
61	      const full = join(dir, entry.name);
62	      if (entry.isDirectory()) visit(full, depth + 1);
63	      else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") {
64	        try {
65	          const g = JSON.parse(readFileSync(full, "utf8")) as Graph;
66	          const parts = full.split(sep);
67	          found.push({
68	            id: createHash("sha1").update(relative(space.root, full)).digest("hex").slice(0, 12),
69	            package: g.package ?? parts[parts.length - 2] ?? "PACKAGE",
70	            module: g.module ?? parts[parts.length - 3] ?? "",
71	            system: g.system ?? "SAP",
72	            builtAt: g.builtAt ?? null,
73	            nodes: g.nodes.length,
74	            edges: g.edges.length,
75	            file: full,
76	          });
77	        } catch {
78	          // A half-written or foreign graph.json is not one of ours.
79	        }
80	      }
81	    }
82	  };
83	  visit(join(space.root, "ws"), 0);
84	  return found.sort((a, b) => (a.system + a.package).localeCompare(b.system + b.package));
85	}
86	
87	// ---------- names and tiny YAML ----------
88	
89	/** `PROG:ZX` → `PROG ZX` — the note's file name and its link target. */
90	export function noteFile(id: string): string {
91	  const at = id.indexOf(":");
92	  const type = at > 0 ? id.slice(0, at) : "NOTE";
93	  const name = at > 0 ? id.slice(at + 1) : id;
94	  return `${type} ${name}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();
95	}
96	const link = (id: string) => `[[${noteFile(id)}]]`;
97	/** A process note's name — one function, so the file and the links to it agree. */
98	const processName = (pkg: string, i: number, entry: string) =>
99	  `${pkg} P${String(i + 1).padStart(2, "0")} ${entry}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();
100	
101	type Front = { keys: string[]; values: Map<string, string | string[]> };
102	
103	/** Front matter of the shape this file writes, and of Obsidian's property editor: scalars and lists. */
104	export function splitFront(text: string): { front: Front; body: string } {
105	  const values = new Map<string, string | string[]>();
106	  const keys: string[] = [];
107	  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
108	  if (!m) return { front: { keys, values }, body: text };
109	  let current: string | null = null;
110	  for (const raw of (m[1] ?? "").split(/\r?\n/)) {
111	    const item = /^\s+-\s+(.*)$/.exec(raw);
112	    if (item && current) {
113	      const list = values.get(current);
114	      values.set(current, [...(Array.isArray(list) ? list : []), unquote(item[1] ?? "")]);
115	      continue;
116	    }
117	    const kv = /^([^\s:#][^:]*):\s*(.*)$/.exec(raw);
118	    if (!kv) continue;
119	    current = (kv[1] ?? "").trim();
120	    keys.push(current);
121	    const v = (kv[2] ?? "").trim();
122	    if (v === "") values.set(current, []);
123	    else if (v.startsWith("[") && v.endsWith("]") && !v.startsWith("[[")) {
124	      values.set(current, v.slice(1, -1).split(",").map((s) => unquote(s.trim())).filter(Boolean));
125	    } else values.set(current, unquote(v));
126	  }
127	  return { front: { keys, values }, body: text.slice(m[0].length) };
128	}
129	function unquote(v: string): string {
130	  return /^".*"$/.test(v) || /^'.*'$/.test(v) ? v.slice(1, -1).replace(/\\"/g, '"') : v;
131	}
132	function yamlValue(v: string): string {
133	  return /^[\w .\-/가-힣]*$/.test(v) && v !== "" && !/^(true|false|null|-|\d)/i.test(v) ? v : JSON.stringify(v);
134	}
135	function joinFront(front: Front, body: string): string {
136	  const lines: string[] = [];
137	  for (const key of front.keys) {
138	    const v = front.values.get(key);
139	    if (Array.isArray(v)) lines.push(v.length ? `${key}:\n${v.map((x) => `  - ${yamlValue(x)}`).join("\n")}` : `${key}: []`);
140	    else if (v !== undefined) lines.push(`${key}: ${yamlValue(v)}`);
141	  }
142	  return `---\n${lines.join("\n")}\n---\n${body.startsWith("\n") ? "" : "\n"}${body}`;
143	}
144	function setFront(front: Front, key: string, value: string | string[]): void {
145	  if (!front.keys.includes(key)) front.keys.push(key);
146	  front.values.set(key, value);
147	}
148	
149	/** Puts this package's generated block into a note, replacing an older one, keeping the rest. */
150	function mergeNote(existing: string | null, pkg: string, block: string, props: Record<string, string | string[]>, title: string): string {
151	  const { front, body } = existing ? splitFront(existing) : { front: { keys: [], values: new Map() } as Front, body: `# ${title}\n\n## 메모\n\n` };
152	  for (const [key, value] of Object.entries(props)) {
153	    if (key === "packages" && Array.isArray(value)) {
154	      const had = front.values.get("packages");
155	      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])].sort());
156	    } else if (key === "tags" && Array.isArray(value)) {
157	      const had = front.values.get("tags");
158	      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])]);
159	    } else setFront(front, key, value);
160	  }
161	  const wrapped = `${BEGIN(pkg)}\n${block.trim()}\n${END(pkg)}\n`;
162	  const own = new RegExp(`${escape(BEGIN(pkg))}[\\s\\S]*?${escape(END(pkg))}\\n?`);
163	  let next: string;
164	  if (own.test(body)) next = body.replace(own, wrapped);
165	  else if (/^## 메모\s*$/m.test(body)) next = body.replace(/^## 메모\s*$/m, `${wrapped}\n## 메모`);
166	  else next = `${body.trimEnd()}\n\n${wrapped}`;
167	  return joinFront(front, next);
168	}
169	const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
170	
171	// ---------- export ----------
172	
173	export type VaultOptions = { detail?: boolean; system: string; existing: (path: string) => string | null; components?: Component[] };
174	type Component = { entries: string[]; members: string[]; writes: string[]; sharedTables: { table: string; writers: string[]; readers: string[] }[] };
175	
176	function evidenceOf(e: GEdge): string {
177	  const ev = e.evidence?.[0];
178	  const where = ev?.unit ? `${ev.unit}${ev.line ? `:${ev.line}` : ""}` : "";
179	  return [where, e.confidence === "low" ? "low" : "", e.count && e.count > 1 ? `×${e.count}` : ""].filter(Boolean).join(" · ");
180	}
181	
182	/** The vault's files for one package graph, merged into what the member already has. */
183	export function buildVault(graph: Graph, opts: VaultOptions): Map<string, string> {
184	  const pkg = graph.package ?? "PACKAGE";
185	  const base = `SC4SAP/${noteFile(`X:${opts.system}`).slice(2)}`;
186	  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
187	  const hidden = (id: string) => !opts.detail && DETAIL_HIDDEN_TYPES.has(nodes.get(id)?.type ?? "");
188	  const edges = graph.edges.filter(
189	    (e) => (opts.detail ? e.kind !== "dynamic" : DEFAULT_KINDS.has(e.kind)) && !hidden(e.from) && !hidden(e.to),
190	  );
191	  const kept = new Set<string>();
192	  for (const e of edges) kept.add(e.from).add(e.to);
193	  for (const n of graph.nodes) if (n.scope === "member" && !hidden(n.id) && n.type !== "INCL") kept.add(n.id);
194	
195	  const out = new Map<string, GEdge[]>();
196	  for (const e of edges) out.set(e.from, [...(out.get(e.from) ?? []), e]);
197	  const files = new Map<string, string>();
198	  const put = (path: string, block: string, props: Record<string, string | string[]>, title: string) =>
199	    files.set(path, mergeNote(opts.existing(path), pkg, block, props, title));
200	
201	  for (const id of kept) {
202	    const n = nodes.get(id) ?? { id, type: id.split(":")[0] ?? "NOTE", name: id.split(":").slice(1).join(":") };
203	    const rel = (out.get(id) ?? [])
204	      .sort((a, b) => a.kind.localeCompare(b.kind) || a.to.localeCompare(b.to))
205	      .map((e) => `- ${e.kind}:: ${link(e.to)}${evidenceOf(e) ? ` — ${evidenceOf(e)}` : ""}`);
206	    const block = rel.length ? `### ${pkg}\n${rel.join("\n")}` : `### ${pkg}\n(no outgoing relations in the source parse)`;
207	    put(`${base}/objects/${noteFile(id)}.md`, block, {
208	      sc4sap_id: id,
209	      type: n.type,
210	      scope: n.scope ?? "",
211	      system: opts.system,
212	      packages: [pkg],
213	      ...(n.lines ? { lines: String(n.lines) } : {}),
214	      tags: [`sc4sap/${n.type.toLowerCase()}`, `sc4sap/${n.scope ?? "other"}`],
215	    }, n.name);
216	  }
217	
218	  const comps = opts.components ?? [];
219	  comps.forEach((c, i) => {
220	    const first = c.entries[0] ?? "";
221	    const entry = nodes.get(first)?.name ?? first;
222	    const path = `${base}/processes/${processName(pkg, i, entry)}.md`;
223	    const lines = [
224	      `### ${pkg}`,
225	      `- package:: [[PACKAGE ${pkg}]]`,
226	      ...c.entries.map((e) => `- entry:: ${link(e)}`),
227	      ...c.members.filter((m) => kept.has(m)).map((m) => `- member:: ${link(m)}`),
228	      ...c.sharedTables.map((t) => `- handoff:: ${link(t.table)} — ${t.writers.map((w) => nodes.get(w)?.name ?? w).join(", ")} → ${t.readers.map((r) => nodes.get(r)?.name ?? r).join(", ") || "(written only)"}`),
229	    ];
230	    put(path, lines.join("\n"), { sc4sap_id: `PROCESS:${pkg}:${i + 1}`, type: "PROCESS", system: opts.system, packages: [pkg], tags: ["sc4sap/process"] }, `${pkg} P${i + 1} — ${entry}`);
231	  });
232	
233	  const byType = new Map<string, string[]>();
234	  for (const id of kept) {
235	    const n = nodes.get(id);
236	    if (n?.scope !== "member") continue;
237	    byType.set(n.type, [...(byType.get(n.type) ?? []), id]);
238	  }
239	  const index = [
240	    `### ${pkg}`,
241	    `${graph.module ? `Module ${graph.module} · ` : ""}${kept.size} objects · ${edges.length} relations${opts.detail ? " (detail)" : ""} · built ${graph.builtAt ?? "?"}`,
242	    ...[...byType.entries()].sort().flatMap(([type, ids]) => [`#### ${type}`, ...ids.sort().map((id) => `- member:: ${link(id)}`)]),
243	    ...(comps.length ? ["#### Processes", ...comps.map((c, i) => `- process:: [[${processName(pkg, i, nodes.get(c.entries[0] ?? "")?.name ?? c.entries[0] ?? "")}]]`)] : []),
244	  ];
245	  put(`${base}/packages/PACKAGE ${noteFile(`X:${pkg}`).slice(2)}.md`, index.join("\n"), { sc4sap_id: `PACKAGE:${pkg}`, type: "PACKAGE", system: opts.system, packages: [pkg], tags: ["sc4sap/package"] }, pkg);
246	
247	  files.set(`${base}/SC4SAP 사용법.md`, opts.existing(`${base}/SC4SAP 사용법.md`) ?? GUIDE);
248	  return files;
249	}
250	
251	const GUIDE = `# SC4SAP 그래프 사용법
252	
253	이 폴더는 SC4SAP이 소스를 분석해 만든 관계 그래프예요.
254	
255	- \`<!-- sc4sap:begin … -->\` 와 \`<!-- sc4sap:end … -->\` 사이는 다시 내보낼 때 바뀌어요. 그 밖에 쓴 내용은 그대로 남아요.
256	- 관계를 더하려면 그 밖에 한 줄을 써요. 예: \`belongs_to:: [[출하 프로세스]]\`
257	- 소스 분석이 틀린 관계를 지우려면 \`not_\`을 붙여요. 예: \`not_reads:: [[TABL VBAK]]\`
258	- 그냥 \`[[링크]]\`를 걸면 "언급" 관계가 돼요.
259	- 다듬은 뒤 SC4SAP 설정 → 참고 노트에서 볼트 폴더를 다시 올리면 에이전트가 그 관계로 답해요.

