          found.push({
            id: createHash("sha1").update(relative(space.root, full)).digest("hex").slice(0, 12),
            package: g.package ?? parts[parts.length - 2] ?? "PACKAGE",
            module: g.module ?? parts[parts.length - 3] ?? "",
            system: g.system ?? "SAP",
            builtAt: g.builtAt ?? null,
            nodes: g.nodes.length,
