// ---------- names and tiny YAML ----------

/** `PROG:ZX` → `PROG ZX` — the note's file name and its link target. */
export function noteFile(id: string): string {
  const at = id.indexOf(":");
  const type = at > 0 ? id.slice(0, at) : "NOTE";
  const name = at > 0 ? id.slice(at + 1) : id;
  return `${type} ${name}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();
}
const link = (id: string) => `[[${noteFile(id)}]]`;
/** A process note's name — one function, so the file and the links to it agree. */
const processName = (pkg: string, i: number, entry: string) =>
  `${pkg} P${String(i + 1).padStart(2, "0")} ${entry}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();

type Front = { keys: string[]; values: Map<string, string | string[]> };

/** Front matter of the shape this file writes, and of Obsidian's property editor: scalars and lists. */
export function splitFront(text: string): { front: Front; body: string } {
  const values = new Map<string, string | string[]>();
  const keys: string[] = [];
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
  if (!m) return { front: { keys, values }, body: text };
  let current: string | null = null;
  for (const raw of (m[1] ?? "").split(/\r?\n/)) {
    const item = /^\s+-\s+(.*)$/.exec(raw);
    if (item && current) {
      const list = values.get(current);
      values.set(current, [...(Array.isArray(list) ? list : []), unquote(item[1] ?? "")]);
      continue;
    }
    const kv = /^([^\s:#][^:]*):\s*(.*)$/.exec(raw);
    if (!kv) continue;
    current = (kv[1] ?? "").trim();
    keys.push(current);
    const v = (kv[2] ?? "").trim();
    if (v === "") values.set(current, []);
    else if (v.startsWith("[") && v.endsWith("]") && !v.startsWith("[[")) {
      values.set(current, v.slice(1, -1).split(",").map((s) => unquote(s.trim())).filter(Boolean));
    } else values.set(current, unquote(v));
  }
  return { front: { keys, values }, body: text.slice(m[0].length) };
}
function unquote(v: string): string {
  return /^".*"$/.test(v) || /^'.*'$/.test(v) ? v.slice(1, -1).replace(/\\"/g, '"') : v;
}
function yamlValue(v: string): string {
  return /^[\w .\-/가-힣]*$/.test(v) && v !== "" && !/^(true|false|null|-|\d)/i.test(v) ? v : JSON.stringify(v);
}
function joinFront(front: Front, body: string): string {
  const lines: string[] = [];
  for (const key of front.keys) {
    const v = front.values.get(key);
    if (Array.isArray(v)) lines.push(v.length ? `${key}:\n${v.map((x) => `  - ${yamlValue(x)}`).join("\n")}` : `${key}: []`);
    else if (v !== undefined) lines.push(`${key}: ${yamlValue(v)}`);
  }
  return `---\n${lines.join("\n")}\n---\n${body.startsWith("\n") ? "" : "\n"}${body}`;
}
function setFront(front: Front, key: string, value: string | string[]): void {
  if (!front.keys.includes(key)) front.keys.push(key);
  front.values.set(key, value);
}

/** Puts this package's generated block into a note, replacing an older one, keeping the rest. */
function mergeNote(existing: string | null, pkg: string, block: string, props: Record<string, string | string[]>, title: string): string {
  const { front, body } = existing ? splitFront(existing) : { front: { keys: [], values: new Map() } as Front, body: `# ${title}\n\n## 메모\n\n` };
  for (const [key, value] of Object.entries(props)) {
    if (key === "packages" && Array.isArray(value)) {
      const had = front.values.get("packages");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])].sort());
    } else if (key === "tags" && Array.isArray(value)) {
      const had = front.values.get("tags");
      setFront(front, key, [...new Set([...(Array.isArray(had) ? had : []), ...value])]);
    } else setFront(front, key, value);
  }
  const wrapped = `${BEGIN(pkg)}\n${block.trim()}\n${END(pkg)}\n`;
  const own = new RegExp(`${escape(BEGIN(pkg))}[\\s\\S]*?${escape(END(pkg))}\\n?`);
  let next: string;
  if (own.test(body)) next = body.replace(own, wrapped);
  else if (/^## 메모\s*$/m.test(body)) next = body.replace(/^## 메모\s*$/m, `${wrapped}\n## 메모`);
  else next = `${body.trimEnd()}\n\n${wrapped}`;
  return joinFront(front, next);
}
const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// ---------- export ----------

export type VaultOptions = { detail?: boolean; system: string; existing: (path: string) => string | null; components?: Component[] };
type Component = { entries: string[]; members: string[]; writes: string[]; sharedTables: { table: string; writers: string[]; readers: string[] }[] };

function evidenceOf(e: GEdge): string {
  const ev = e.evidence?.[0];
  const where = ev?.unit ? `${ev.unit}${ev.line ? `:${ev.line}` : ""}` : "";
  return [where, e.confidence === "low" ? "low" : "", e.count && e.count > 1 ? `×${e.count}` : ""].filter(Boolean).join(" · ");
}

/** The vault's files for one package graph, merged into what the member already has. */
export function buildVault(graph: Graph, opts: VaultOptions): Map<string, string> {
  const pkg = graph.package ?? "PACKAGE";
  const base = `SC4SAP/${noteFile(`X:${opts.system}`).slice(2)}`;
  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
  const hidden = (id: string) => !opts.detail && DETAIL_HIDDEN_TYPES.has(nodes.get(id)?.type ?? "");
  const edges = graph.edges.filter(
    (e) => (opts.detail ? e.kind !== "dynamic" : DEFAULT_KINDS.has(e.kind)) && !hidden(e.from) && !hidden(e.to),
  );
  const kept = new Set<string>();
  for (const e of edges) kept.add(e.from).add(e.to);
  for (const n of graph.nodes) if (n.scope === "member" && !hidden(n.id) && n.type !== "INCL") kept.add(n.id);

  const out = new Map<string, GEdge[]>();
  for (const e of edges) out.set(e.from, [...(out.get(e.from) ?? []), e]);
  const files = new Map<string, string>();
  const put = (path: string, block: string, props: Record<string, string | string[]>, title: string) =>
    files.set(path, mergeNote(opts.existing(path), pkg, block, props, title));

  for (const id of kept) {
    const n = nodes.get(id) ?? { id, type: id.split(":")[0] ?? "NOTE", name: id.split(":").slice(1).join(":") };
    const rel = (out.get(id) ?? [])
      .sort((a, b) => a.kind.localeCompare(b.kind) || a.to.localeCompare(b.to))
      .map((e) => `- ${e.kind}:: ${link(e.to)}${evidenceOf(e) ? ` — ${evidenceOf(e)}` : ""}`);
    const block = rel.length ? `### ${pkg}\n${rel.join("\n")}` : `### ${pkg}\n(no outgoing relations in the source parse)`;
    put(`${base}/objects/${noteFile(id)}.md`, block, {
      sc4sap_id: id,
      type: n.type,
      scope: n.scope ?? "",
      system: opts.system,
      packages: [pkg],
      ...(n.lines ? { lines: String(n.lines) } : {}),
      tags: [`sc4sap/${n.type.toLowerCase()}`, `sc4sap/${n.scope ?? "other"}`],
    }, n.name);
  }

  const comps = opts.components ?? [];
  comps.forEach((c, i) => {
    const first = c.entries[0] ?? "";
    const entry = nodes.get(first)?.name ?? first;
    const path = `${base}/processes/${processName(pkg, i, entry)}.md`;
    const lines = [
      `### ${pkg}`,
      `- package:: [[PACKAGE ${pkg}]]`,
      ...c.entries.map((e) => `- entry:: ${link(e)}`),
      ...c.members.filter((m) => kept.has(m)).map((m) => `- member:: ${link(m)}`),
      ...c.sharedTables.map((t) => `- handoff:: ${link(t.table)} — ${t.writers.map((w) => nodes.get(w)?.name ?? w).join(", ")} → ${t.readers.map((r) => nodes.get(r)?.name ?? r).join(", ") || "(written only)"}`),
    ];
    put(path, lines.join("\n"), { sc4sap_id: `PROCESS:${pkg}:${i + 1}`, type: "PROCESS", system: opts.system, packages: [pkg], tags: ["sc4sap/process"] }, `${pkg} P${i + 1} — ${entry}`);
  });

  const byType = new Map<string, string[]>();
  for (const id of kept) {
    const n = nodes.get(id);
    if (n?.scope !== "member") continue;
    byType.set(n.type, [...(byType.get(n.type) ?? []), id]);
  }
  const index = [
    `### ${pkg}`,
    `${graph.module ? `Module ${graph.module} · ` : ""}${kept.size} objects · ${edges.length} relations${opts.detail ? " (detail)" : ""} · built ${graph.builtAt ?? "?"}`,
    ...[...byType.entries()].sort().flatMap(([type, ids]) => [`#### ${type}`, ...ids.sort().map((id) => `- member:: ${link(id)}`)]),
    ...(comps.length ? ["#### Processes", ...comps.map((c, i) => `- process:: [[${processName(pkg, i, nodes.get(c.entries[0] ?? "")?.name ?? c.entries[0] ?? "")}]]`)] : []),
  ];
  put(`${base}/packages/PACKAGE ${noteFile(`X:${pkg}`).slice(2)}.md`, index.join("\n"), { sc4sap_id: `PACKAGE:${pkg}`, type: "PACKAGE", system: opts.system, packages: [pkg], tags: ["sc4sap/package"] }, pkg);

  files.set(`${base}/SC4SAP 사용법.md`, opts.existing(`${base}/SC4SAP 사용법.md`) ?? GUIDE);
  return files;
}

const GUIDE = `# SC4SAP 그래프 사용법

이 폴더는 SC4SAP이 소스를 분석해 만든 관계 그래프예요.

- \`<!-- sc4sap:begin … -->\` 와 \`<!-- sc4sap:end … -->\` 사이는 다시 내보낼 때 바뀌어요. 그 밖에 쓴 내용은 그대로 남아요.
- 관계를 더하려면 그 밖에 한 줄을 써요. 예: \`belongs_to:: [[출하 프로세스]]\`
- 소스 분석이 틀린 관계를 지우려면 \`not_\`을 붙여요. 예: \`not_reads:: [[TABL VBAK]]\`
- 그냥 \`[[링크]]\`를 걸면 "언급" 관계가 돼요.
- 다듬은 뒤 SC4SAP 설정 → 참고 노트에서 볼트 폴더를 다시 올리면 에이전트가 그 관계로 답해요.

