/** Every `cbo/<MODULE>/<PACKAGE>/graph.json` under the account's session folders, with its mtime. Stat only. */
function graphFiles(space: AccountSpace): { file: string; mtime: number }[] {
  if (!space.home) return [];
  const found: { file: string; mtime: number }[] = [];
  const visit = (dir: string, depth: number): void => {
    if (depth > 9 || !existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name.startsWith("_prev") || entry.name === "notes") continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) visit(full, depth + 1);
      else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") {
        found.push({ file: full, mtime: statSync(full).mtimeMs });
      }
    }
  };
  visit(join(space.root, "ws"), 0);
  return found;
}

/**
 * Parsed graphs, kept while their file is unchanged: a real package graph is
 * tens of MB of JSON, and parsing it on every tool call would stall every
 * session's stream.
 */
const parsed = new Map<string, { mtime: number; graph: Graph | null }>();
function graphAt(file: string, mtime: number): Graph | null {
  const hit = parsed.get(file);
  if (hit && hit.mtime === mtime) return hit.graph;
  let graph: Graph | null = null;
  try {
    graph = JSON.parse(readFileSync(file, "utf8")) as Graph;
  } catch {
    // A half-written or foreign graph.json is not one of ours.
  }
  parsed.set(file, { mtime, graph });
  return graph;
}

/** The account's graphs, described. */
export function listGraphs(space: AccountSpace): GraphRef[] {
  const found: GraphRef[] = [];
  for (const { file, mtime } of graphFiles(space)) {
    const g = graphAt(file, mtime);
    if (!g) continue;
    const parts = file.split(sep);
    found.push({
      id: createHash("sha1").update(relative(space.root, file)).digest("hex").slice(0, 12),
      package: g.package ?? parts[parts.length - 2] ?? "PACKAGE",
      module: g.module ?? parts[parts.length - 3] ?? "",
      system: g.system ?? "SAP",
      builtAt: g.builtAt ?? null,
      nodes: g.nodes.length,
      edges: g.edges.length,
      file,
    });
  }
  return found.sort((a, b) => (a.system + a.package).localeCompare(b.system + b.package));
}

const graphs = graphFiles(space)
  .map(({ file, mtime }) => graphAt(file, mtime))
  .filter((g): g is Graph => g !== null);
const curated = curatedEdges(notes).edges;

