/**
 * A process note's name — one function, so the file and the links to it agree.
 * Named after its first entry, not numbered: components come back ordered by
 * size, and a number would move to another process when the graph changes,
 * leaving the member's notes on the wrong one.
 */
const processName = (pkg: string, entry: string) =>
  `PROCESS ${pkg} ${entry}`.replace(/[\\/:*?"<>|#^[\]]/g, "_").trim();

type Front = { keys: string[]; values: Map<string, string | string[]> };

/** The front matter block, empty or not, and what follows it. */
const FRONT = /^---\r?\n(?:([\s\S]*?)\r?\n)?---[ \t]*(?:\r?\n|$)/;

/**
 * Front matter read for its values — scalars and lists, which is what this
 * file writes and what Obsidian's property editor writes. Reading only: a
 * note's front matter is never rebuilt from this, so a shape it does not
 * understand (nested maps, block strings, comments) costs nothing.
 */
export function splitFront(text: string): { front: Front; body: string } {
  const values = new Map<string, string | string[]>();
  const keys: string[] = [];
  const m = FRONT.exec(text);
  if (!m) return { front: { keys, values }, body: text };
  let current: string | null = null;
  for (const raw of (m[1] ?? "").split(/\r?\n/)) {
    const item = /^\s*-\s+(.*)$/.exec(raw);
    if (item && current) {
      const list = values.get(current);
      values.set(current, [...(Array.isArray(list) ? list : []), unquote(item[1] ?? "")]);
      continue;
    }
    const kv = /^([^\s:#-][^:]*):\s*(.*)$/.exec(raw);
    if (!kv) continue;
    current = (kv[1] ?? "").trim();
    keys.push(current);
    const v = (kv[2] ?? "").trim();
    if (v === "") values.set(current, []);
    else if (v.startsWith("[") && v.endsWith("]") && !v.startsWith("[[")) {
      values.set(current, v.slice(1, -1).split(",").map((x) => unquote(x.trim())).filter(Boolean));
    } else values.set(current, unquote(v));
  }
  return { front: { keys, values }, body: text.slice(m[0].length) };
}
function unquote(v: string): string {
  if (/^".*"$/.test(v)) {
    try {
      return JSON.parse(v) as string;
    } catch {
      return v.slice(1, -1);
    }
  }
  return /^'.*'$/.test(v) ? v.slice(1, -1).replace(/''/g, "'") : v;
}
function yamlValue(v: string): string {
  return /^[\w .\-/가-힣]*$/.test(v) && v !== "" && !/^(true|false|null|-|\d)/i.test(v) ? v : JSON.stringify(v);
}

/** The properties this file owns. Every one is prefixed, so none is ever a member's. */
const OWN_KEY = /^sc4sap_[\w-]*\s*:/;

/** The member's front matter, verbatim, minus the `sc4sap_*` keys (and their list items). */
function withoutOwnKeys(yaml: string): string {
  const out: string[] = [];
  let skipping = false;
  for (const line of yaml.split(/\r?\n/)) {
    if (OWN_KEY.test(line)) {
      skipping = true;
      continue;
    }
    // A list item or continuation under one of ours; a new key ends it.
    if (skipping && (/^\s/.test(line) || /^-\s/.test(line))) continue;
    skipping = false;
    out.push(line);
  }
  return out.join("\n").replace(/\n+$/, "");
}

function ownYaml(props: Record<string, string | string[]>): string {
  return Object.entries(props)
    .map(([key, v]) =>
      Array.isArray(v)
        ? v.length ? `${key}:\n${v.map((x) => `  - ${yamlValue(x)}`).join("\n")}` : `${key}: []`
        : `${key}: ${yamlValue(v)}`,
    )
    .join("\n");
}

/**
 * Puts this package's generated block into a note, replacing an older one.
 * The member's own front matter and text are kept byte for byte; only the
 * `sc4sap_*` properties are rewritten, `sc4sap_packages` as the union with
 * what the note already listed. `tags` are written on a new note only — once
 * it exists, its tags are the member's.
 */
function mergeNote(
  existing: string | null,
  pkg: string,
  block: string,
  props: Record<string, string | string[]>,
  tags: string[],
  title: string,
): string {
  const m = existing ? FRONT.exec(existing) : null;
  const memberYaml = m ? withoutOwnKeys(m[1] ?? "") : existing ? "" : `tags:\n${tags.map((t) => `  - ${t}`).join("\n")}`;
  const body = existing ? existing.slice(m ? m[0].length : 0) : `# ${title}\n\n## 메모\n\n`;
  const had = existing ? splitFront(existing).front.values.get("sc4sap_packages") : undefined;
  const packages = [...new Set([...(Array.isArray(had) ? had : []), pkg])].sort();
  const yaml = [memberYaml, ownYaml({ ...props, sc4sap_packages: packages })].filter((x) => x !== "").join("\n");

  const wrapped = `${BEGIN(pkg)}\n${block.trim()}\n${END(pkg)}\n`;
  const own = new RegExp(`${escape(BEGIN(pkg))}[\\s\\S]*?${escape(END(pkg))}\\n?`);
  let next: string;
  if (own.test(body)) next = body.replace(own, () => wrapped);
  else if (/^## 메모\s*$/m.test(body)) next = body.replace(/^## 메모\s*$/m, () => `${wrapped}\n## 메모`);
  else next = `${body.trimEnd()}\n\n${wrapped}`;
  return `---\n${yaml}\n---\n${next.startsWith("\n") ? "" : "\n"}${next}`;
}

