// Throwaway round-trip check of vault.ts on a real graph (read-only on it).
import assert from "node:assert/strict";
import { join } from "node:path";
import { buildKnowledge, buildVault, componentsOf, curatedEdges, readGraph, resolveRef, splitFront, zip } from "./server/vault.ts";

const graph = readGraph(process.argv[2]!);
const components = await componentsOf(join(process.cwd(), "plugin_module"), graph);
const first = buildVault(graph, { system: "HKT-DEV", existing: () => null, components });
const prog = [...first.keys()].find((p) => p.endsWith("/objects/PROG ZSDR24730.md"))!;
const progText = first.get(prog)!;
assert.equal(splitFront(progText).front.values.get("sc4sap_id"), "PROG:ZSDR24730");
assert.deepEqual(splitFront(progText).front.values.get("tags"), ["sc4sap/prog", "sc4sap/member"], "tags on a new note");
const proc = [...first.keys()].find((p) => p.includes("/processes/PROCESS ZSD400 "))!;
assert.ok(proc, "process note named after its entry");
const pkgNote = [...first.keys()].find((p) => p.endsWith("/packages/PACKAGE ZSD400.md"))!;
assert.ok(pkgNote && first.get(proc)!.includes("- package:: [[PACKAGE ZSD400]]"), "package link matches its file");
assert.ok(first.get(pkgNote)!.includes(`[[${proc.split("/").pop()!.replace(/\.md$/, "")}]]`), "index links the process file");

const readLine = progText.split("\n").find((l) => l.startsWith("- reads:: [[TABL "))!;
const readTarget = /\[\[(TABL [^\]]+)\]\]/.exec(readLine)![1]!;

// A member's front matter with every shape the old writer used to break.
const memberFront = [
  "owner: 물류팀",
  "# a comment",
  "aliases:",
  "- 컨테이너 출하",
  "- ZSDR24730 별칭",
  "reviewed: true",
  "summary: |",
  "  첫 줄",
  "  둘째 줄",
  "meta:",
  "  team: SD",
  "  level: 2",
  "path: C:\\temp\\x",
].join("\n");
const body = progText.slice(progText.indexOf("\n---\n") + 5);
const edited = `---\n${memberFront}\nsc4sap_id: "PROG:ZSDR24730"\nsc4sap_packages:\n  - OLDPKG\n---\n${body.replace("## 메모", `## 메모\n\n수출 컨테이너 출하용.\nbelongs_to:: [[출하 프로세스]]\nnot_reads:: [[${readTarget}]]\n`)}`;

const second = buildVault(graph, { system: "HKT-DEV", existing: (p) => (p === prog ? edited : null), components });
const again = second.get(prog)!;
assert.ok(again.startsWith(`---\n${memberFront}\n`), "member front matter kept byte for byte");
assert.deepEqual(splitFront(again).front.values.get("sc4sap_packages"), ["OLDPKG", "ZSD400"], "packages unioned");
assert.ok(!splitFront(again).front.values.has("tags"), "no tags added to an existing note");
assert.ok(again.includes("belongs_to:: [[출하 프로세스]]") && again.includes("수출 컨테이너 출하용."), "member text kept");
assert.equal(again.match(/<!-- sc4sap:begin ZSD400 -->/g)?.length, 1, "one block");
const third = buildVault(graph, { system: "HKT-DEV", existing: (p) => (p === prog ? again : null), components }).get(prog)!;
assert.equal(third, again, "a second re-export changes nothing");

const empty = buildVault(graph, { system: "HKT-DEV", existing: (p) => (p === prog ? "---\n---\n# 빈 속성\n" : null), components }).get(prog)!;
assert.equal(empty.match(/^---$/gm)?.length, 2, "empty front matter not doubled");

const { edges } = curatedEdges([{ path: prog, text: again }, { path: "x/출하 프로세스.md", text: "step:: [[PROG ZSDR24730]]\n관련 [[PACKAGE ZSD400]] `calls:: [[FUNC FAKE]]`\n" }]);
assert.ok(edges.some((e) => e.kind === "belongs_to" && e.to === "NOTE:출하 프로세스"));
assert.ok(edges.some((e) => e.kind === "reads" && e.negated));
assert.ok(!edges.some((e) => e.to.includes("FAKE")));
assert.ok(!edges.some((e) => e.kind.startsWith("sc4sap_") || e.kind === "aliases" || e.kind === "meta"), "own and plain properties are not relations");
assert.ok(edges.some((e) => e.kind === "mentions" && e.to === "PACKAGE:ZSD400"));
const K = buildKnowledge([graph], edges);
assert.ok(!(K.out.get("PROG:ZSDR24730") ?? []).some((e) => e.kind === "reads" && e.to === readTarget.replace(" ", ":")), "strike applied");
assert.equal(resolveRef(K, "ZSDR24730"), "PROG:ZSDR24730");
assert.ok(zip(first).length > 0);
console.log(`notes ${first.size}, processes ${components.length}, knowledge ${K.edges} edges`);
console.log("vault round trip: all passed");

