import "server-only";
import { createHash, randomBytes } from "node:crypto";
import { ObjectId } from "mongodb";
import { apiTokens, users } from "@/lib/mongo";
import { toAccount, touchSeen } from "@/lib/auth/users";
import type { Account } from "@/lib/account";

/**
 * Personal tokens for the SC4SAP Obsidian plugin (`obsidian-plugin/`).
 *
 * The plugin runs inside Obsidian, not in a browser tab of this app, so it
 * has no session cookie; it sends `Authorization: Bearer sc4sap_…` instead.
 * One token per account: making a new one replaces the old. Only the SHA-256
 * is stored — the same reasoning as session tokens (`lib/auth/session.ts`):
 * 256 random bits need no slow hash, and a database dump yields no token.
 *
 * A token reaches only `/api/obsidian/*`, which forwards the few graph and
 * notes calls the plugin makes. It cannot open sessions, change settings or
 * pay — those stay behind the signed-in browser.
 */

const PREFIX = "sc4sap_";

const hash = (token: string) => createHash("sha256").update(token).digest("hex");

export async function createToken(userId: string): Promise<string> {
  const token = `${PREFIX}${randomBytes(32).toString("base64url")}`;
  const col = await apiTokens();
  await col.deleteMany({ userId });
  await col.insertOne({ userId, tokenHash: hash(token), createdAt: new Date(), lastUsedAt: null });
  return token;
}

export async function revokeTokens(userId: string): Promise<void> {
  await (await apiTokens()).deleteMany({ userId });
}

export async function tokenStatus(userId: string): Promise<{ createdAt: string; lastUsedAt: string | null } | null> {
  const doc = await (await apiTokens()).findOne({ userId });
  return doc ? { createdAt: doc.createdAt.toISOString(), lastUsedAt: doc.lastUsedAt?.toISOString() ?? null } : null;
}

/** The account behind `Authorization: Bearer …`, or the response to send instead. */
export async function bearerAccount(request: Request): Promise<{ account: Account } | { response: Response }> {
  const header = request.headers.get("authorization") ?? "";
  const token = header.startsWith("Bearer ") ? header.slice(7).trim() : "";
  const refuse = (status: number, error: string) => ({ response: Response.json({ error }, { status }) });
  if (!token.startsWith(PREFIX)) return refuse(401, "Missing or malformed token.");
  try {
    const col = await apiTokens();
    const doc = await col.findOne({ tokenHash: hash(token) });
    if (!doc || !ObjectId.isValid(doc.userId)) return refuse(401, "That token is not valid. Make a new one in SC4SAP Settings → Obsidian.");
    const user = await (await users()).findOne({ _id: new ObjectId(doc.userId) });
    if (!user) return refuse(401, "That account no longer exists.");
    void col.updateOne({ _id: doc._id }, { $set: { lastUsedAt: new Date() } });
    void touchSeen(user);
    const account = toAccount(user);
    if (account.needsConsent) return refuse(403, "Agree to the current terms in SC4SAP first.");
    if (!account.hasConnection) return refuse(403, "Finish setup in SC4SAP first.");
    return { account };
  } catch {
    return refuse(503, "The user store could not be reached.");
  }
}

