import { createToken, revokeTokens, tokenStatus } from "@/lib/auth/api-token";
import { jsonError, signedIn } from "../shared";

/**
 * `/api/account/obsidian-token` — the account's token for the Obsidian plugin.
 *
 *   GET     whether one exists, made when, last used when (never the token)
 *   POST    make one, replacing any other; the token is in this answer only
 *   DELETE  revoke it
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(): Promise<Response> {
  const auth = await signedIn();
  if ("response" in auth) return auth.response;
  return Response.json({ token: await tokenStatus(auth.account.id) });
}

export async function POST(): Promise<Response> {
  const auth = await signedIn();
