import { NextRequest } from "next/server";
import { BACKEND } from "@/lib/backend";
import { bearerAccount } from "@/lib/auth/api-token";
import { ensureSapProfile } from "@/lib/sap-profile-sync";

/**
 * `/api/obsidian/*` — what the SC4SAP Obsidian plugin may reach, with its
 * bearer token (`lib/auth/api-token.ts`), forwarded to the backend as the
 * token's account. A fixed list: graphs and their vault files, and the
 * reference notes. Nothing that opens a session, spends usage or changes a
 * setting.
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const ALLOWED: { method: string; path: RegExp }[] = [
  { method: "GET", path: /^\/graphs$/ },
  { method: "GET", path: /^\/graphs\/[a-f0-9]{12}\/vault\.json$/ },
  { method: "GET", path: /^\/notes$/ },
  { method: "POST", path: /^\/notes$/ },
];

async function forward(request: NextRequest, context: { params: Promise<{ path?: string[] }> }): Promise<Response> {
  const auth = await bearerAccount(request);
  if ("response" in auth) return auth.response;

  const { path = [] } = await context.params;
  const target = new URL(`${BACKEND}/${path.map(encodeURIComponent).join("/")}${request.nextUrl.search}`);
  if (!ALLOWED.some((a) => a.method === request.method && a.path.test(target.pathname))) {
    return Response.json({ error: "Not available to the plugin." }, { status: 404 });
  }

  await ensureSapProfile(auth.account.id);
  const body = request.method === "POST" ? await request.text() : undefined;
  try {
    const upstream = await fetch(target, {
      method: request.method,
      headers: {
        "x-sc4sap-user": auth.account.id,
        ...(body ? { "content-type": "application/json" } : {}),
      },
      body,
      cache: "no-store",
    });
    return new Response(upstream.body, {
      status: upstream.status,
      headers: { "content-type": upstream.headers.get("content-type") ?? "application/json", "cache-control": "no-store" },
    });
  } catch {
    return Response.json({ error: "The SC4SAP backend is not reachable." }, { status: 502 });
  }
}

export { forward as GET, forward as POST };

