/*
 * SC4SAP Sync — the Obsidian side of SC4SAP's graph round trip.
 *
 *   Sync   uploads the notes under the SC4SAP folder (so the server knows what
 *          the member wrote), then pulls every CBO graph of the account as
 *          notes and writes them into the vault. The server merges: only the
 *          `<!-- sc4sap:begin … -->` blocks and `sc4sap_*` properties change,
 *          everything the member wrote stays.
 *   Upload just the first half — after editing relations
 *          (`belongs_to:: [[…]]`, `not_reads:: [[…]]`), so the agent answers
 *          from them.
 *
 * Talks only to `<server>/api/obsidian/*` with a personal token made in
 * SC4SAP → Settings → Obsidian. Plain JavaScript, no build step.
 */
const { Plugin, PluginSettingTab, Setting, Notice, requestUrl, normalizePath, TFile } = require("obsidian");

const DEFAULTS = { server: "http://localhost:3000", token: "", folder: "SC4SAP", detail: false };
const BATCH_BYTES = 4 * 1024 * 1024;

module.exports = class SC4SAPSync extends Plugin {
  async onload() {
    this.settings = Object.assign({}, DEFAULTS, await this.loadData());
    this.addSettingTab(new SC4SAPSettingTab(this.app, this));
    this.addRibbonIcon("refresh-cw", "SC4SAP: sync graphs", () => this.run(() => this.sync()));
    this.addCommand({ id: "sync", name: "Sync graphs (upload notes, then pull graphs)", callback: () => this.run(() => this.sync()) });
    this.addCommand({ id: "upload", name: "Upload notes only", callback: () => this.run(() => this.upload()) });
  }

  async save() {
    await this.saveData(this.settings);
  }

  /** One job at a time, with its outcome or failure as a notice. */
  async run(job) {
    if (this.busy) return new Notice("SC4SAP: already working…");
    if (!this.settings.token) return new Notice("SC4SAP: set the server and token in Settings → SC4SAP first.");
    this.busy = true;
    try {
      await job();
    } catch (err) {
      new Notice(`SC4SAP: ${err.message}`, 10000);
    } finally {
      this.busy = false;
    }
  }

  async api(path, method = "GET", body) {
    const response = await requestUrl({
      url: `${this.settings.server.replace(/\/+$/, "")}/api/obsidian${path}`,
      method,
      headers: { authorization: `Bearer ${this.settings.token}`, ...(body ? { "content-type": "application/json" } : {}) },
      body: body ? JSON.stringify(body) : undefined,
      throw: false,
    });
    let json = null;
    try {
      json = response.json;
    } catch (_) {
      // Not JSON: the status is all there is.
    }
    if (response.status >= 400) throw new Error((json && json.error) || `server answered ${response.status}`);
    return json;
  }

  /** The Markdown files the member keeps under the sync folder ("" = the whole vault). */
  scope() {
    const folder = normalizePath(this.settings.folder || "/").replace(/^\/$/, "");
    return this.app.vault
      .getMarkdownFiles()
      .filter((f) => !folder || f.path === folder || f.path.startsWith(`${folder}/`));
  }

  async upload() {
    const files = this.scope();
    if (files.length === 0) {
      new Notice("SC4SAP: nothing to upload yet — the folder has no notes.");
      return 0;
    }
