const { Plugin, PluginSettingTab, Setting, Notice, requestUrl, normalizePath, TFile } = require("obsidian");

const DEFAULTS = { server: "http://localhost:3000", token: "", folder: "SC4SAP", detail: false };
const BATCH_BYTES = 4 * 1024 * 1024;

