  async onload() {
    this.settings = Object.assign({}, DEFAULTS, await this.loadData());
    this.addSettingTab(new SC4SAPSettingTab(this.app, this));
    this.addRibbonIcon("refresh-cw", "SC4SAP: sync graphs", () => this.run(() => this.sync()));
    this.addCommand({ id: "sync", name: "Sync graphs (upload notes, then pull graphs)", callback: () => this.run(() => this.sync()) });
    this.addCommand({ id: "upload", name: "Upload notes only", callback: () => this.run(() => this.upload()) });
  }

  async save() {
    await this.saveData(this.settings);
  }

  /** One job at a time, with its outcome or failure as a notice. */
  async run(job) {
    if (this.busy) return new Notice("SC4SAP: already working…");
    if (!this.settings.token) return new Notice("SC4SAP: set the server and token in Settings → SC4SAP first.");
    this.busy = true;
    try {
      await job();
    } catch (err) {
      new Notice(`SC4SAP: ${err.message}`, 10000);
    } finally {
      this.busy = false;
    }
  }

  async api(path, method = "GET", body) {
