toolUseResult.content:
"use client";

/**
 * The account's knowledge graph, one object at a time.
 *
 * The merged graph the agent queries (`GET /graph` on the backend: every CBO
 * graph of the account plus the relations written in its Obsidian notes),
 * drawn as an ego graph: the object in the middle, what it uses on the right,
 * what uses it on the left, coloured by object type. Relations from notes are
 * dashed. Pressing a neighbour moves to it. No graph library — a few hundred
 * nodes around one object is a layout, not a simulation.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Icon } from "@/components/Icon";
import { useLocale } from "@/lib/i18n/client";

type GNode = { id: string; type: string; name: string; scope: string | null };
type GEdge = { from: string; to: string; kind: string; source: "code" | "note"; where: string };
type View = { center: string; nodes: GNode[]; edges: GEdge[]; totals: { out: number; in: number } };

const W = 960;
const H = 560;
const PER_SIDE = 36;
const TYPES = ["PROG", "TRAN", "FUNC", "FUGR", "CLAS", "INTF", "TABL", "VIEW", "STRU", "DTEL", "NOTE", "PROCESS", "PACKAGE"];

async function api<T>(query: string): Promise<T> {
  const r = await fetch(`/api/graph?${query}`);
  const body = (await r.json().catch(() => null)) as (T & { error?: string }) | null;
  if (!r.ok) throw new Error(body?.error ?? String(r.status));
  return body as T;
}

export function GraphExplorer() {
  const { t: messages } = useLocale();
  const t = messages.graph;
  const [q, setQ] = useState("");
  const [hits, setHits] = useState<GNode[]>([]);
  const [view, setView] = useState<View | null>(null);
  const [empty, setEmpty] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [kinds, setKinds] = useState<Set<string>>(new Set());
  const trail = useRef<string[]>([]);

  const open = useCallback(async (object: string, push = true) => {
    setError(null);
    try {
      const v = await api<View & { empty?: boolean }>(`object=${encodeURIComponent(object)}`);
      if (v.empty) return setEmpty(true);
      if (push && view) trail.current.push(view.center);
      setView(v);
      setKinds(new Set());
      setHits([]);
      const url = new URL(window.location.href);
      url.searchParams.set("object", v.center);
      window.history.replaceState(null, "", url);
    } catch (err) {
      setError((err as Error).message);
    }
  }, [view]);

  useEffect(() => {
    const start = new URLSearchParams(window.location.search).get("object");
    if (start) void open(start, false);
    else void api<{ empty?: boolean }>("q=Z").then((r) => r.empty && setEmpty(true)).catch(() => {});
    // Mount only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (q.trim().length < 2) return setHits([]);
    const timer = setTimeout(() => {
      void api<{ hits?: GNode[]; empty?: boolean }>(`q=${encodeURIComponent(q.trim())}`)
        .then((r) => (r.empty ? setEmpty(true) : setHits(r.hits ?? [])))
        .catch((err: Error) => setError(err.message));
    }, 250);
    return () => clearTimeout(timer);
  }, [q]);

  const present = useMemo(() => [...new Set(view?.edges.map((e) => e.kind) ?? [])].sort(), [view]);
  const shown = useMemo(
    () => (view?.edges ?? []).filter((e) => kinds.size === 0 || kinds.has(e.kind)),
    [view, kinds],
  );

  const layout = useMemo(() => {
    if (!view) return null;
    const byId = new Map(view.nodes.map((n) => [n.id, n]));
    const outs = [...new Set(shown.filter((e) => e.from === view.center).map((e) => e.to))];
    const ins = [...new Set(shown.filter((e) => e.to === view.center && e.from !== view.center).map((e) => e.from))].filter(
      (x) => !outs.includes(x),
    );
    const place = (ids: string[], side: 1 | -1) =>
      ids.slice(0, PER_SIDE).map((id, i, all) => {
        const a = ((i + 1) / (all.length + 1)) * Math.PI - Math.PI / 2;
        return { id, x: W / 2 + side * Math.cos(a) * (W / 2 - 150), y: H / 2 + Math.sin(a) * (H / 2 - 40) };
      });
    const points = [...place(outs, 1), ...place(ins, -1)];
    return {
      byId,
      points,
      at: new Map(points.map((p) => [p.id, p])),
      more: { out: Math.max(0, outs.length - PER_SIDE), in: Math.max(0, ins.length - PER_SIDE) },
    };
  }, [view, shown]);

  const typeClass = (type: string) => `g-node g-${TYPES.includes(type) ? type : "OTHER"}`;
  const label = (n: GNode | undefined, id: string) => {
    const name = n?.name ?? id;
    return name.length > 22 ? `${name.slice(0, 21)}…` : name;
  };

  return (
    <section className="panel graph-panel">
      <div className="graph-search">
        <Icon name="magnifying-glass" />
        <input type="search" value={q} onChange={(e) => setQ(e.target.value)} placeholder={t.search} aria-label={t.search} />
        {trail.current.length > 0 && (
          <button type="button" className="ghost" onClick={() => void open(trail.current.pop()!, false)}>
            <Icon name="arrow-left" /> {t.back}
          </button>
        )}
      </div>
      {hits.length > 0 && (
        <ul className="graph-hits">
          {hits.map((h) => (
            <li key={h.id}>
              <button type="button" onClick={() => void open(h.id)}>
                <span className={`g-chip g-${TYPES.includes(h.type) ? h.type : "OTHER"}`}>{h.type}</span> {h.name}
                {h.scope === "member" && <small> · {t.member}</small>}
              </button>
            </li>
          ))}
        </ul>
      )}
      {error && <p className="auth-status is-error">{error}</p>}
      {empty && <p className="graph-empty">{t.empty}</p>}

      {view && layout && (
        <>
          <div className="graph-head">
            <strong>{view.center}</strong>
            <span>{t.totals(view.totals.out, view.totals.in)}</span>
            <span className="graph-kinds">
              {present.map((k) => (
                <button
                  key={k}
                  type="button"
                  className={kinds.has(k) ? "is-on" : undefined}
                  onClick={() => setKinds((cur) => {
                    const next = new Set(cur);
                    if (next.has(k)) next.delete(k);
                    else next.add(k);
                    return next;
                  })}
                >
                  {k}
                </button>
              ))}
            </span>
          </div>
          <svg className="graph-svg" viewBox={`0 0 ${W} ${H}`} role="img" aria-label={view.center}>
            <text x={W / 2 + 140} y={20} className="g-side">{t.uses}</text>
            <text x={W / 2 - 140} y={20} className="g-side" textAnchor="end">{t.usedBy}</text>
            {shown.map((e, i) => {
              const other = e.from === view.center ? e.to : e.from;
              const p = layout.at.get(other);
              if (!p) return null;
              return (
                <line
                  key={i}
                  x1={W / 2}
                  y1={H / 2}
                  x2={p.x}
                  y2={p.y}
                  className={`g-edge g-k-${e.kind.replace(/[^a-z_]/gi, "")}${e.source === "note" ? " is-note" : ""}`}
                >
                  <title>{`${e.from} —${e.kind}→ ${e.to} [${e.source}: ${e.where}]`}</title>
                </line>
              );
            })}
            {layout.points.map((p) => {
              const n = layout.byId.get(p.id);
              const right = p.x > W / 2;
              return (
                <g key={p.id} className="g-point" onClick={() => void open(p.id)} role="button" tabIndex={0}>
                  <circle cx={p.x} cy={p.y} r={7} className={typeClass(n?.type ?? "")} />
                  <text x={p.x + (right ? 11 : -11)} y={p.y + 4} textAnchor={right ? "start" : "end"} className="g-label">
                    {label(n, p.id)}
                  </text>
                  <title>{p.id}</title>
                </g>
              );
            })}
            <circle cx={W / 2} cy={H / 2} r={13} className={typeClass(layout.byId.get(view.center)?.type ?? "")} />
            <text x={W / 2} y={H / 2 + 32} textAnchor="middle" className="g-label g-center">
              {label(layout.byId.get(view.center), view.center)}
            </text>
            {layout.more.out > 0 && <text x={W - 20} y={H - 10} textAnchor="end" className="g-side">{t.more(layout.more.out)}</text>}
            {layout.more.in > 0 && <text x={20} y={H - 10} className="g-side">{t.more(layout.more.in)}</text>}
          </svg>
          <p className="graph-legend">
            {TYPES.map((type) => (
              <span key={type}>
                <span className={`g-chip g-${type}`}>{type}</span>
              </span>
            ))}
            <span className="graph-legend-note">{t.legend}</span>
          </p>
          <table className="graph-table">
            <thead>
              <tr>
                <th>{t.relation}</th>
                <th>{t.object}</th>
                <th>{t.source}</th>
              </tr>
            </thead>
            <tbody>
              {shown.map((e, i) => {
                const outgoing = e.from === view.center;
                const other = outgoing ? e.to : e.from;
                return (
                  <tr key={i}>
                    <td>{outgoing ? `→ ${e.kind}` : `← ${e.kind}`}</td>
                    <td>
                      <button type="button" className="link-button" onClick={() => void open(other)}>
                        {other}
                      </button>
                    </td>
                    <td className={e.source === "note" ? "is-note" : undefined}>
                      {e.source === "note" ? t.fromNote : t.fromCode} {e.where}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </>
      )}
    </section>
  );
}

/**
 * Graph — the account's knowledge graph of its SAP custom code, one object at
 * a time. The frame only; `GraphExplorer` is the client island that searches
 * and draws (`GET /graph` on the backend, through the proxy).
 */
import type { Metadata } from "next";
import { requireAccount } from "@/lib/auth/session";
import { GraphExplorer } from "@/components/GraphExplorer";
import { readMessages } from "@/lib/i18n/server";

export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const { t } = await readMessages();
  return { title: `${t.graph.title} · SC4SAP` };
}

export default async function GraphPage() {
  await requireAccount();
  const { t } = await readMessages();
  return (
    <div className="page graph">
      <header className="page-head rise">
        <div>
          <p className="eyebrow">{t.graph.eyebrow}</p>
          <h1>{t.graph.title}</h1>
          <p className="page-lede">{t.graph.lede}</p>
        </div>
      </header>
      <div className="rise" style={{ "--delay": "80ms" } as React.CSSProperties}>
        <GraphExplorer />
      </div>
    </div>
  );
}

