// Just enough of Obsidian's API for SC4SAP Sync's main.js to run in Node.
class TAbstractFile { constructor(path) { this.path = path; } }
class TFile extends TAbstractFile { constructor(path, vault) { super(path); this.vault = vault; } get stat() { return { size: Buffer.byteLength(this.vault.files.get(this.path) || "") }; } }
class TFolder extends TAbstractFile {}
class Vault {
  constructor() { this.files = new Map(); this.folders = new Set(); }
  getMarkdownFiles() { return [...this.files.keys()].filter((p) => p.endsWith(".md")).map((p) => new TFile(p, this)); }
  async cachedRead(f) { return this.files.get(f.path); }
  async read(f) { return this.files.get(f.path); }
  async modify(f, text) { this.files.set(f.path, text); }
  async create(path, text) { if (this.files.has(path)) throw new Error("exists " + path); this.files.set(path, text); return new TFile(path, this); }
  async createFolder(path) { this.folders.add(path); }
  getAbstractFileByPath(path) { return this.files.has(path) ? new TFile(path, this) : this.folders.has(path) ? new TFolder(path) : null; }
}
const notices = [];
class Notice { constructor(msg) { notices.push(msg); } }
class Plugin {
  constructor(app) { this.app = app; this.commands = []; this.data = null; }
  async loadData() { return this.data; }
  async saveData(d) { this.data = d; }
  addSettingTab() {}
  addRibbonIcon() {}
  addCommand(c) { this.commands.push(c); }
}
class PluginSettingTab { constructor(app) { this.app = app; } }
class Setting {}
async function requestUrl({ url, method, headers, body }) {
  const r = await fetch(url, { method, headers, body });
  const text = await r.text();
  let json = null; try { json = JSON.parse(text); } catch {}
  return { status: r.status, text, json };
}
const normalizePath = (p) => p.replace(/\\/g, "/").replace(/\/+/g, "/").replace(/^\/|\/$/g, "") || "/";
module.exports = { Plugin, PluginSettingTab, Setting, Notice, requestUrl, normalizePath, TFile, TFolder, Vault, notices };

