// Throwaway check: graph tab API, plugin tokens, and the real plugin main.js driven against the app.
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { copyFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";
import { ObjectId } from "mongodb";
import { sessions, users } from "./src/lib/mongo.ts";
import { saveConnection } from "./src/lib/setup-store.ts";
import { EMPTY_DRAFT } from "./src/lib/setup.ts";
import { PRIVACY_VERSION, TERMS_VERSION } from "./src/lib/consent.ts";
import { deleteAccount } from "./src/lib/retention.ts";

const SIM = process.argv[2]!;
const APP = "http://localhost:3000";
const ACCOUNTS = join(process.cwd(), "..", "accounts");
const GRAPH = join(process.cwd(), "..", "..", ".sc4sap", "work", "HKT-DEV", "cbo", "SD", "ZAPVB", "graph.json");
const now = new Date();
const out: string[] = [];
const check = (name: string, ok: boolean, detail = "") => out.push(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);

for (const old of await (await users()).find({ email: "plugin-a@example.test" }).toArray()) await deleteAccount(old, "member");
const _id = new ObjectId();
const id = String(_id);
await (await users()).insertOne({
  _id, email: "plugin-a@example.test", displayEmail: "plugin-a@example.test", lastName: "플러그인", firstName: "A", createdAt: now,
  consents: { terms: TERMS_VERSION, privacy: PRIVACY_VERSION, age: true, agreedAt: now, marketing: false, marketingAt: null, overseas: true },
} as never);
await saveConnection(id, { ...EMPTY_DRAFT, adtUrl: "http://p.sap.invalid:50000", sapUser: "P_A", sapPassword: randomBytes(12).toString("base64url"), abapRelease: "758", client: "100" });
const cookie = randomBytes(32).toString("base64url");
await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(cookie).digest("hex"), userId: id, createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
const web = (path: string, init: RequestInit = {}) => fetch(APP + path, { ...init, headers: { cookie: `sc4sap_session=${cookie}`, ...(init.headers ?? {}) } });

try {
  const dir = join(ACCOUNTS, id, "ws", "p-P-100", ".sc4sap", "work", "P-100", "cbo", "SD", "ZAPVB");
  mkdirSync(dir, { recursive: true });
  copyFileSync(GRAPH, join(dir, "graph.json"));

  // Graph tab.
  const search = (await (await web("/api/graph?q=ZAP")).json()) as { hits?: { id: string }[] };
  check("graph search finds objects", (search.hits?.length ?? 0) > 0, search.hits?.slice(0, 3).map((h) => h.id).join(","));
  const first = search.hits![0]!.id;
  const view = (await (await web(`/api/graph?object=${encodeURIComponent(first)}`)).json()) as { center?: string; nodes?: unknown[]; edges?: unknown[] };
  check("graph view for an object", view.center === first && (view.edges?.length ?? 0) > 0, `${view.nodes?.length} nodes, ${view.edges?.length} edges`);
  const page = await web("/graph");
  check("graph page renders", page.status === 200 && (await page.text()).includes("graph-panel") === false ? true : page.status === 200, String(page.status));

  // Tokens.
  const made = (await (await web("/api/account/obsidian-token", { method: "POST" })).json()) as { token: string };
  check("token made", made.token?.startsWith("sc4sap_"));
  const bearer = (path: string, init: RequestInit = {}) => fetch(APP + path, { ...init, headers: { authorization: `Bearer ${made.token}`, ...(init.headers ?? {}) } });
  check("bad token refused", (await fetch(`${APP}/api/obsidian/graphs`, { headers: { authorization: "Bearer sc4sap_nope" } })).status === 401);
  check("no token refused", (await fetch(`${APP}/api/obsidian/graphs`)).status === 401);
  check("sessions not reachable with a token", (await bearer("/api/obsidian/sessions", { method: "POST", body: "{}", headers: { "content-type": "application/json" } })).status === 404);
  check("token cannot use the cookie proxy", (await bearer("/api/sessions")).status === 401);

  // The real plugin, in a stand-in Obsidian.
  const req = createRequire(join(SIM, "main.js"));
  const obsidian = req("obsidian");
  const Plugin = req("./main.js");
  const vault = new obsidian.Vault();
  vault.files.set("SC4SAP/내 메모.md", "# 내 메모\nbelongs_to:: [[수출 프로세스]]\n");
  vault.files.set("다른 폴더/비밀.md", "upload me not");
  const plugin = new Plugin({ vault });
  plugin.data = { server: APP, token: made.token, folder: "SC4SAP", detail: false };
  await plugin.onload();
  await plugin.run(() => plugin.sync());
  const failed = obsidian.notices.filter((n: string) => /answered|not valid|reach|Finish|Agree/.test(n));
  check("plugin sync ran without errors", failed.length === 0, obsidian.notices.slice(-2).join(" | "));
  const written = [...vault.files.keys()].filter((p: string) => p.startsWith("SC4SAP/P-100/"));
  check("plugin wrote graph notes", written.length > 10, `${written.length} notes`);
  const notes = (await (await bearer("/api/obsidian/notes")).json()) as { count: number; relations: number };
  check("plugin uploaded only its folder", notes.count === 1 && notes.relations === 1, JSON.stringify(notes));

  // Member edits a generated note, syncs again: the edit survives, nothing else changes.
  const target = written.find((p: string) => p.includes("/objects/"))!;
  vault.files.set(target, vault.files.get(target)!.replace("## 메모", "## 메모\n\n내가 쓴 줄\nowner:: [[물류팀]]"));
  obsidian.notices.length = 0;
  await plugin.run(() => plugin.sync());
  check("member edit survives a second sync", vault.files.get(target)!.includes("내가 쓴 줄"), obsidian.notices.slice(-1)[0]);
  check("second sync changes nothing else", /0 new, 0 updated/.test(obsidian.notices.slice(-1)[0] ?? ""), obsidian.notices.slice(-1)[0]);
  const after = (await (await web("/api/graph?object=" + encodeURIComponent(target.split("/").pop()!.replace(/\.md$/, "")))).json()) as { edges?: { kind: string; source: string }[] };
  check("graph tab shows the member's relation", (after.edges ?? []).some((e) => e.kind === "owner" && e.source === "note"));

  check("revoke works", (await web("/api/account/obsidian-token", { method: "DELETE" })).ok && (await bearer("/api/obsidian/graphs")).status === 401);
} finally {
  const doc = await (await users()).findOne({ _id });
  try { if (doc) await deleteAccount(doc, "member"); } catch (e) { out.push(`FAIL cleanup: ${(e as Error).message}`); }
  console.log(out.join("\n"));
  process.exit(out.some((l) => l.startsWith("FAIL")) ? 1 : 0);
}

