    for (const graph of graphs) {
      new Notice(`SC4SAP: pulling ${graph.system} · ${graph.package}…`);
      const { files } = await this.api(`/graphs/${graph.id}/vault.json${this.settings.detail ? "?detail=1" : ""}`);
      for (const { path, text } of files) {
        const at = safePath(path);
        if (!at) {
          rejected += 1;
          continue;
        }
        const existing = this.app.vault.getAbstractFileByPath(at);
        if (existing instanceof TFile) {
          if ((await this.app.vault.read(existing)) === text) same += 1;
          else {
            await this.app.vault.modify(existing, text);
            updated += 1;
          }
        } else {
          await this.folder(at.split("/").slice(0, -1).join("/"));
          await this.app.vault.create(at, text);
          created += 1;
        }
      }
    }
    await this.colorGroups();
    new Notice(`SC4SAP: ${graphs.length} graph(s) — ${created} new, ${updated} updated, ${same} unchanged.${rejected ? ` ${rejected} refused (path outside SC4SAP/).` : ""}`, 8000);
    if (!this.app.plugins?.enabledPlugins?.has?.("dataview")) {
      new Notice("SC4SAP: install the Dataview plugin to see the dashboards (Settings → Community plugins → Dataview).", 10000);
    }
  }

  /**
   * The graph view's colours by SC4SAP type, the same as the web's graph tab.
   * Groups whose query is one of ours are replaced; the member's own are kept,
   * after ours. Applied the next time the graph view opens.
   */
  async colorGroups() {
    const path = `${this.app.vault.configDir}/graph.json`;
    const adapter = this.app.vault.adapter;
    let graph = {};
    try {
      if (await adapter.exists(path)) graph = JSON.parse(await adapter.read(path));
    } catch (_) {
      return; // An unreadable graph.json is the member's to fix, not ours to replace.
    }
    const ours = COLOR_GROUPS.map(([query, rgb]) => ({ query, color: { a: 1, rgb } }));
    const theirs = (graph.colorGroups || []).filter((g) => !COLOR_GROUPS.some(([q]) => q === g.query));
    graph.colorGroups = [...ours, ...theirs];
    await adapter.write(path, JSON.stringify(graph, null, 2));
  }

  async folder(path) {
    let at = "";
    for (const part of path.split("/").filter(Boolean)) {
      at = at ? `${at}/${part}` : part;
      if (!this.app.vault.getAbstractFileByPath(at)) await this.app.vault.createFolder(at);
    }
  }
};

class SC4SAPSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    const s = this.plugin.settings;
    containerEl.empty();
    containerEl.createEl("h2", { text: "SC4SAP Sync" });
    new Setting(containerEl)
      .setName("Server")
      .setDesc("The SC4SAP web address, e.g. http://localhost:3000")
      .addText((t) => t.setValue(s.server).onChange(async (v) => ((s.server = v.trim()), await this.plugin.save())));
    new Setting(containerEl)
      .setName("Token")
      .setDesc("SC4SAP → Settings → Obsidian → Make token")
      .addText((t) => {
        t.inputEl.type = "password";
        t.setValue(s.token).onChange(async (v) => ((s.token = v.trim()), await this.plugin.save()));
      });
    new Setting(containerEl)
      .setName("Folder")
      .setDesc("Uploaded on sync, and where graphs land. Empty = the whole vault (up to 1,000 notes).")
      .addText((t) => t.setValue(s.folder).onChange(async (v) => ((s.folder = v.trim()), await this.plugin.save())));
    new Setting(containerEl)
      .setName("Include DDIC typing")
      .setDesc("Also data elements, domains, structures and includes. Many more notes.")
      .addToggle((t) => t.setValue(s.detail).onChange(async (v) => ((s.detail = v), await this.plugin.save())));
    new Setting(containerEl)
      .setName("Check the connection")
      .addButton((b) =>
        b.setButtonText("Test").onClick(() =>
          this.plugin.run(async () => {
            const { graphs } = await this.plugin.api("/graphs");
            new Notice(`SC4SAP: connected — ${graphs.length} graph(s).`);
          }),
        ),
      );
  }
}

