// Throwaway: re-check the round trip with bracketed fields, then refresh the member's vault copy.
import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { buildKnowledge, buildVault, componentsOf, curatedEdges, readGraph } from "./server/vault.ts";

const graph = readGraph(process.argv[2]!);
const VAULT = process.argv[3]!;
const components = await componentsOf(join(process.cwd(), "plugin_module"), graph);
const fresh = buildVault(graph, { system: "HKT-DEV", existing: () => null, components });
const prog = [...fresh.keys()].find((p) => p.endsWith("/objects/PROG ZSDR24730.md"))!;
const line = fresh.get(prog)!.split("\n").find((l) => l.startsWith("- [reads:: [[TABL "))!;
assert.ok(/^- \[reads:: \[\[TABL [^\]]+\]\]\]( · .+)?$/.test(line), line);

const edited = fresh.get(prog)!.replace("## 메모", "## 메모\n\n[belongs_to:: [[수출 출하]]] 그리고 (owner:: [[물류팀]])\nnot_calls:: [[FUNC X]]\n");
const { edges } = curatedEdges([{ path: prog, text: edited }]);
assert.ok(edges.some((e) => e.kind === "belongs_to" && e.to === "NOTE:수출 출하"), "bracketed field");
assert.ok(edges.some((e) => e.kind === "owner" && e.to === "NOTE:물류팀"), "parenthesised field");
assert.ok(edges.some((e) => e.kind === "calls" && e.negated), "line field strike");
assert.ok(!edges.some((e) => e.kind === "mentions"), "field links are not also mentions");
assert.ok(buildKnowledge([graph], edges).edges > 0);

// Refresh the vault copy: merge into what is there, keep any edit.
const existing = (p: string) => (existsSync(join(VAULT, p)) ? readFileSync(join(VAULT, p), "utf8") : null);
const merged = buildVault(graph, { system: "HKT-DEV", existing, components });
let changed = 0;
for (const [p, text] of merged) {
  const at = join(VAULT, p);
  if (existing(p) === text) continue;
  mkdirSync(dirname(at), { recursive: true });
  writeFileSync(at, text, "utf8");
  changed += 1;
}
console.log(`vault refreshed: ${changed} of ${merged.size} notes rewritten`);
console.log("bracketed fields: all passed");

