import { existsSync, mkdirSync, utimesSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { gunzipSync, gzipSync } from "node:zlib";
import { Binary, MongoClient, type Collection, type Db } from "mongodb";
import type { AccountSpace } from "./accounts.ts";
import { notesOf, storeNotes, summarize, type NoteFile } from "./notes.ts";
import { listGraphs, readGraph } from "./vault.ts";

type NoteRow = { userId: string; path: string; text: string; size: number; updatedAt: Date };
type GraphRow = {
  userId: string;
  /** `<system>/<package>` — one graph per package and system per account. */
  key: string;
  system: string;
  package: string;
  module: string;
  builtAt: string | null;
  nodes: number;
  edges: number;
  /** The disk file's mtime when uploaded, so an unchanged file is not sent again. */
  sourceMtime: number;
  gz: Binary;
  updatedAt: Date;
};

/** Mongo's document limit is 16 MB; a compressed graph past this stays on disk only. */
const MAX_GZ = 15 * 1024 * 1024;

let connecting: Promise<Db> | null = null;
function database(): Promise<Db> | null {
  const uri = process.env.MONGODB_URI;
  if (!uri) return null;
  connecting ??= MongoClient.connect(uri).then(async (client) => {
    const db = client.db(process.env.MONGODB_DB ?? "sc4sap");
    await db.collection<NoteRow>("kb_notes").createIndex({ userId: 1, path: 1 }, { unique: true, name: "kb_note_path" });
    await db.collection<GraphRow>("kb_graphs").createIndex({ userId: 1, key: 1 }, { unique: true, name: "kb_graph_key" });
    return db;
  });
  connecting.catch(() => {
    connecting = null;
  });
  return connecting;
}
async function notes(): Promise<Collection<NoteRow> | null> {
  const db = database();
  return db ? (await db).collection<NoteRow>("kb_notes") : null;
}
async function graphs(): Promise<Collection<GraphRow> | null> {
  const db = database();
  return db ? (await db).collection<GraphRow>("kb_graphs") : null;
}

/** After a batch was stored on disk: the same batch into the database. */
export async function saveNotesDb(userId: string, files: readonly NoteFile[], reset: boolean, space: AccountSpace): Promise<void> {
  const col = await notes();
  if (!col) return;
  if (reset) await col.deleteMany({ userId });
