/** Uploads the account's disk graphs that the database lacks or has older. */
export async function mirrorGraphs(userId: string, space: AccountSpace): Promise<{ uploaded: number }> {
  const col = await graphs();
  if (!col) return { uploaded: 0 };
  let uploaded = 0;
  for (const ref of listGraphs(space)) {
    const key = `${ref.system}/${ref.package}`;
    const mtime = Math.floor(require_mtime(ref.file));
    const row = await col.findOne({ userId, key }, { projection: { sourceMtime: 1 } });
