// Throwaway: knowledge base in MongoDB — write, lose the disk, restart, hydrate, delete. Synthetic account only.
// Phase given as argv[2]: "write" (then the runner wipes the folder and restarts the backend) or "check".
import assert from "node:assert/strict";
import { createHash, randomBytes } from "node:crypto";
import { copyFileSync, existsSync, mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { MongoClient, ObjectId } from "mongodb";
import { sessions, users } from "./src/lib/mongo.ts";
import { saveConnection } from "./src/lib/setup-store.ts";
import { EMPTY_DRAFT } from "./src/lib/setup.ts";
import { PRIVACY_VERSION, TERMS_VERSION } from "./src/lib/consent.ts";
import { deleteAccount } from "./src/lib/retention.ts";

const phase = process.argv[2];
const STATE = process.argv[3]!;
const APP = "http://localhost:3000";
const ACCOUNTS = join(process.cwd(), "..", "accounts");
const GRAPH = join(process.cwd(), "..", "..", ".sc4sap", "work", "HKT-DEV", "cbo", "SD", "ZAPVB", "graph.json");
const db = (await MongoClient.connect(process.env.MONGODB_URI!)).db(process.env.MONGODB_DB ?? "sc4sap");
const out: string[] = [];
const check = (name: string, ok: boolean, detail = "") => out.push(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);

if (phase === "write") {
  for (const old of await (await users()).find({ email: "kb-a@example.test" }).toArray()) await deleteAccount(old, "member");
  const _id = new ObjectId();
  const id = String(_id);
  const now = new Date();
  await (await users()).insertOne({
    _id, email: "kb-a@example.test", displayEmail: "kb-a@example.test", lastName: "KB", firstName: "A", createdAt: now,
    consents: { terms: TERMS_VERSION, privacy: PRIVACY_VERSION, age: true, agreedAt: now, marketing: false, marketingAt: null, overseas: true },
  } as never);
  await saveConnection(id, { ...EMPTY_DRAFT, adtUrl: "http://k.sap.invalid:50000", sapUser: "K_A", sapPassword: randomBytes(12).toString("base64url"), abapRelease: "758", client: "100" });
  const cookie = randomBytes(32).toString("base64url");
  await (await sessions()).insertOne({ tokenHash: createHash("sha256").update(cookie).digest("hex"), userId: id, createdAt: now, expiresAt: new Date(now.getTime() + 864e5) } as never);
  writeFileSync(STATE, JSON.stringify({ id, cookie }));
  const web = (path: string, init: RequestInit = {}) => fetch(APP + path, { ...init, headers: { cookie: `sc4sap_session=${cookie}`, ...(init.body ? { "content-type": "application/json" } : {}) } });

  const dir = join(ACCOUNTS, id, "ws", "p-K-100", ".sc4sap", "work", "K-100", "cbo", "SD", "ZAPVB");
  mkdirSync(dir, { recursive: true });
  copyFileSync(GRAPH, join(dir, "graph.json"));
  const up = await web("/api/notes", { method: "POST", body: JSON.stringify({ reset: true, files: [{ path: "SC4SAP/a.md", text: "owner:: [[물류팀]]" }, { path: "SC4SAP/b.md", text: "# b" }] }) });
  check("notes stored", up.ok);
  check("notes in MongoDB", (await db.collection("kb_notes").countDocuments({ userId: id })) === 2);
  const g = (await (await web("/api/graphs")).json()) as { graphs: unknown[] };
  check("graph listed", g.graphs.length === 1);
  const row = await db.collection("kb_graphs").findOne({ userId: id });
  check("graph in MongoDB (gzipped)", !!row && row.key === "HKT-DEV/ZAPVB", row ? `${(row.gz.buffer.length / 1024).toFixed(0)} KB` : "none");
} else {
  const { id, cookie } = JSON.parse(readFileSync(STATE, "utf8")) as { id: string; cookie: string };
  const web = (path: string) => fetch(APP + path, { headers: { cookie: `sc4sap_session=${cookie}` } });
  check("disk was wiped", !existsSync(join(ACCOUNTS, id, "notes")));
  const n = (await (await web("/api/notes")).json()) as { count: number; relations: number };
  check("notes hydrated from MongoDB", n.count === 2 && n.relations === 1, JSON.stringify(n));
  const g = (await (await web("/api/graphs")).json()) as { graphs: { package: string }[] };
  check("graph hydrated from MongoDB", g.graphs.length === 1 && g.graphs[0]?.package === "ZAPVB", JSON.stringify(g.graphs).slice(0, 100));
  const v = (await (await web("/api/graph?q=ZAP")).json()) as { hits?: unknown[] };
  check("graph tab works on the hydrated copy", (v.hits?.length ?? 0) > 0);
  const doc = await (await users()).findOne({ _id: new ObjectId(id) });
  await deleteAccount(doc!, "member");
  check("deletion clears kb_notes", (await db.collection("kb_notes").countDocuments({ userId: id })) === 0);
  check("deletion clears kb_graphs", (await db.collection("kb_graphs").countDocuments({ userId: id })) === 0);
  check("deletion clears the folder", !existsSync(join(ACCOUNTS, id)));
}
console.log(out.join("\n"));
process.exit(out.some((l) => l.startsWith("FAIL")) ? 1 : 0);

