pairs=[
("""  const shown = useMemo(
    () => (view?.edges ?? []).filter((e) => kinds.size === 0 || kinds.has(e.kind)),
    [view, kinds],
  );""","""  /**
   * Object types switched off in the legend. Kept across objects — someone
   * who has hidden DTEL wants it hidden on the next object too — and an edge
   * goes when the object at its other end is of a hidden type.
   */
  const [hiddenTypes, setHiddenTypes] = useState<Set<string>>(new Set());
  const shown = useMemo(() => {
    if (!view) return [];
    const typeOf = new Map(view.nodes.map((n) => [n.id, TYPES.includes(n.type) ? n.type : "OTHER"]));
    return view.edges.filter((e) => {
      if (kinds.size > 0 && !kinds.has(e.kind)) return false;
      const other = e.from === view.center ? e.to : e.from;
      return !hiddenTypes.has(typeOf.get(other) ?? "OTHER");
    });
  }, [view, kinds, hiddenTypes]);
  /** How many relations each type holds here, so the legend says what a switch removes. */
  const perType = useMemo(() => {
    const counts = new Map<string, number>();
    if (!view) return counts;
    const typeOf = new Map(view.nodes.map((n) => [n.id, TYPES.includes(n.type) ? n.type : "OTHER"]));
    for (const e of view.edges) {
      const type = typeOf.get(e.from === view.center ? e.to : e.from) ?? "OTHER";
      counts.set(type, (counts.get(type) ?? 0) + 1);
    }
    return counts;
  }, [view]);"""),
("""          <p className="graph-legend">
            {TYPES.map((type) => (
              <span key={type}>
                <span className={`g-chip g-${type}`}>{type}</span>
              </span>
            ))}
            <span className="graph-legend-note">{t.legend}</span>
          </p>""","""          <p className="graph-legend">
            {[...TYPES, "OTHER"].map((type) => {
              const off = hiddenTypes.has(type);
              const n = perType.get(type) ?? 0;
              return (
                <button
                  key={type}
                  type="button"
                  className={`g-chip g-${type}${off ? " is-off" : ""}`}
                  aria-pressed={!off}
                  title={off ? t.showType(type) : t.hideType(type)}
                  disabled={n === 0 && !off}
                  onClick={() =>
                    setHiddenTypes((cur) => {
                      const next = new Set(cur);
                      if (next.has(type)) next.delete(type);
                      else next.add(type);
                      return next;
                    })
                  }
                >
                  {type}
                  {n > 0 && <small> {n}</small>}
                </button>
              );
            })}
            {hiddenTypes.size > 0 && (
              <button type="button" className="link-button" onClick={() => setHiddenTypes(new Set())}>
                {t.showAll}
              </button>
            )}
            <span className="graph-legend-note">{t.legend}</span>
          </p>"""),
]
