  };
  const edges: CuratedEdge[] = [];
  for (const { n, front, body, id } of parsed) {
    const add = (key: string, value: string) => {
      const negated = key.startsWith("not_");
      const kind = negated ? key.slice(4) : key;
      for (const m of value.matchAll(LINK)) edges.push({ from: id, to: target(m[1] ?? ""), kind, negated, note: n.path });
    };
    for (const key of front.keys) {
      if (OUR_KEYS.has(key) || key.startsWith("sc4sap_")) continue;
      const v = front.values.get(key);
      for (const item of Array.isArray(v) ? v : [v ?? ""]) add(key, item);
    }
    // Generated blocks are the source parse, not the member's word; code
    // spans and fences are examples, not relations.
    const own = body.replace(BLOCK, "").replace(/```[\s\S]*?```/g, "").replace(/`[^`\n]*`/g, "");
    for (const raw of own.split(/\r?\n/)) {
      // Dataview's bracketed fields, `[kind:: [[x]]]` or `(kind:: [[x]])`,
      // anywhere in the line; then the whole-line form `kind:: [[x]]`.
      let line = raw.replace(/[[(]([A-Za-z_][\w-]*)::\s*((?:\[\[[^\]]*\]\]|[^\])])*)[\])]/g, (_m, key: string, value: string) => {
        add(key, value);
        return "";
      });
      const field = /^\s*(?:[-*]\s*)?([A-Za-z_][\w-]*)::\s*(.+)$/.exec(line);
      if (field) {
        add(field[1] ?? "", field[2] ?? "");
        line = "";
      }
      for (const m of line.matchAll(LINK)) edges.push({ from: id, to: target(m[1] ?? ""), kind: "mentions", negated: false, note: n.path });
    }
  }
  return { edges, ids };
}

// ---------- the merged graph the agent asks ----------

