input.content:
/**
 * A small ABAP pretty printer for the graph tab's evidence: one statement, as
 * the source parse stored it (joined onto one line, at most 120 characters),
 * laid out the way SE38's pretty printer would — additions on their own
 * lines, one parameter per line, WHERE conditions split at AND / OR — and cut
 * into tokens for colouring. Statement-level only: it has no idea of blocks,
 * and does not need one for a single statement.
 */

/** Additions that start a new line, longest first so `LEFT OUTER JOIN` beats `JOIN`. */
const ADDITIONS = [
  "FOR ALL ENTRIES IN", "LEFT OUTER JOIN", "INNER JOIN", "STARTING NEW TASK", "IN UPDATE TASK", "IN BACKGROUND TASK",
  "ORDER BY", "GROUP BY", "UP TO", "PACKAGE SIZE", "AND RETURN", "VIA SELECTION-SCREEN", "VIA JOB",
  "EXPORTING", "IMPORTING", "TABLES", "CHANGING", "EXCEPTIONS", "RECEIVING", "DESTINATION",
  "FROM", "INTO", "APPENDING", "WHERE", "HAVING", "JOIN", "USING", "WITH", "TRANSPORTING", "INDEX",
];
/** Additions whose content is `name = value` pairs, one per line. */
const PARAMETER_LISTS = new Set(["EXPORTING", "IMPORTING", "TABLES", "CHANGING", "EXCEPTIONS", "RECEIVING"]);

const KEYWORDS = new Set(
  (
    "CALL FUNCTION METHOD PERFORM SUBMIT SELECT SINGLE DISTINCT FROM INTO TABLE CORRESPONDING FIELDS OF WHERE AND OR NOT " +
    "IN IS INITIAL NULL BETWEEN LIKE INSERT UPDATE MODIFY DELETE SET VALUES EXPORTING IMPORTING TABLES CHANGING EXCEPTIONS " +
    "RECEIVING DESTINATION STARTING NEW TASK UPDATE BACKGROUND RETURN VIA SELECTION-SCREEN JOB WITH USING ORDER BY GROUP " +
    "HAVING JOIN INNER LEFT OUTER ON AS UP TO ROWS PACKAGE SIZE FOR ALL ENTRIES APPENDING TRANSACTION LEAVE AND SKIP FIRST " +
    "SCREEN DATA TYPE REF LIKE CREATE OBJECT NEW TYPES INCLUDE STRUCTURE RANGE CONSTANTS VALUE EXPORT IMPORT DATABASE ID " +
    "OPEN CURSOR FETCH NEXT CLOSE INHERITING INTERFACES CATCH RAISING TRY ENDTRY IF ENDIF LOOP AT ENDLOOP READ KEY " +
    "BINARY SEARCH TRANSPORTING INDEX ASCENDING DESCENDING UNION MESSAGE"
