/**
 * The source snippet behind one relation, pretty-printed — the statements the
 * parse matched (or, for a relation written in Obsidian, the note line). A
 * viewer, so a click outside closes it as well as Escape and the button.
 */
function SnippetModal({
  edge,
  onClose,
  t,
}: {
  edge: GEdge;
  onClose: () => void;
  t: { snippetKind: string; close: string; fromNote: string; fromCode: string; snippetCut: string };
}) {
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => event.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  const cut = (edge.evidence ?? []).some((ev) => ev.text?.endsWith("…"));
  return createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal snippet-modal" role="dialog" aria-modal="true" aria-labelledby="snippet-heading" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <span className="modal-kind">{edge.source === "note" ? t.fromNote : t.fromCode}</span>
          <button type="button" className="ghost" onClick={onClose} aria-label={t.close}>
            <Icon name="x" />
          </button>
        </div>
        <h2 id="snippet-heading" className="snippet-title">
          {edge.from} <span>—{edge.kind}→</span> {edge.to}
        </h2>
        {(edge.evidence ?? []).map((ev, i) => (
          <section key={i} className="snippet">
            <p className="snippet-where">
              {ev.unit}
              {ev.line ? `:${ev.line}` : ""}
            </p>
            <pre className="snippet-code">
              {(edge.source === "code" ? prettyAbap(ev.text ?? "") : [ev.text ?? ""]).map((line, n) => (
                <div key={n}>
                  {tokensOf(line).map((tok, k) => (
                    <span key={k} className={`abap-${tok.kind}`}>
                      {tok.text}
                    </span>
                  ))}
                </div>
              ))}
            </pre>
          </section>
        ))}
        {cut && <p className="snippet-note">{t.snippetCut}</p>}
      </div>
    </div>,
    document.body,
  );
}

