p='lib/i18n/messages.ts'
s=open(p,encoding='utf-8',newline='').read()
nl='\r\n' if '\r\n' in s else '\n'
for anchor, lines in [
 ('    showAll: "Show all types",'+nl, ['    snippetKind: "Source",','    close: "Close",','    snippetCut: "The parse keeps the first 120 characters of each statement; “…” marks where it stopped."']),
 ('    showAll: "모두 보기",'+nl, ['    snippetKind: "소스",','    close: "닫기",','    snippetCut: "분석할 때 문장마다 앞 120자만 저장해요. \\"…\\"가 잘린 곳이에요."']),
 ('    showAll: "すべて表示",'+nl, ['    snippetKind: "ソース",','    close: "閉じる",','    snippetCut: "解析時に各文の先頭 120 文字だけを保存しています。「…」が途切れた箇所です。"']),
]:
    assert s.count(anchor)==1, anchor
    s=s.replace(anchor, anchor+(','+nl).join(lines)+','+nl)
open(p,'w',encoding='utf-8',newline='').write(s)
print('ok')
PYEOF
