.snippet-code { margin: 0; padding: 12px 14px; border-radius: 8px; background: #0f172a; color: #e2e8f0; font-size: 13px; line-height: 1.6; overflow-x: auto; font-family: var(--font-mono, ui-monospace, Consolas, monospace); }
