/**
 * A small ABAP pretty printer for the graph tab's evidence: one statement, as
 * the source parse stored it (joined onto one line, at most 120 characters),
 * laid out the way SE38's pretty printer would — additions on their own
 * lines, one parameter per line, WHERE conditions split at AND / OR — and cut
 * into tokens for colouring. Statement-level only: it has no idea of blocks,
 * and does not need one for a single statement.
 */

/** Additions that start a new line, longest first so `LEFT OUTER JOIN` beats `JOIN`. */
const ADDITIONS = [
  "FOR ALL ENTRIES IN", "OPTIONS FROM", "MESSAGES INTO", "LEFT OUTER JOIN", "INNER JOIN", "STARTING NEW TASK", "IN UPDATE TASK", "IN BACKGROUND TASK",
  "ORDER BY", "GROUP BY", "UP TO", "PACKAGE SIZE", "AND RETURN", "VIA SELECTION-SCREEN", "VIA JOB",
  "EXPORTING", "IMPORTING", "TABLES", "CHANGING", "EXCEPTIONS", "RECEIVING", "DESTINATION",
  "FROM", "INTO", "APPENDING", "WHERE", "HAVING", "JOIN", "USING", "WITH", "TRANSPORTING", "INDEX",
];
/** Additions whose content is `name = value` pairs, one per line. */
const PARAMETER_LISTS = new Set(["EXPORTING", "IMPORTING", "TABLES", "CHANGING", "EXCEPTIONS", "RECEIVING"]);

const KEYWORDS = new Set(
  (
    "CALL FUNCTION METHOD PERFORM SUBMIT SELECT SINGLE DISTINCT FROM INTO TABLE CORRESPONDING FIELDS OF WHERE AND OR NOT " +
    "IN IS INITIAL NULL BETWEEN LIKE INSERT UPDATE MODIFY DELETE SET VALUES EXPORTING IMPORTING TABLES CHANGING EXCEPTIONS " +
    "RECEIVING DESTINATION STARTING NEW TASK UPDATE BACKGROUND RETURN VIA SELECTION-SCREEN JOB WITH USING ORDER BY GROUP " +
    "HAVING JOIN INNER LEFT OUTER ON AS UP TO ROWS PACKAGE SIZE FOR ALL ENTRIES APPENDING TRANSACTION LEAVE AND SKIP FIRST " +
    "SCREEN DATA TYPE REF LIKE CREATE OBJECT NEW TYPES INCLUDE STRUCTURE RANGE CONSTANTS VALUE EXPORT IMPORT DATABASE ID " +
    "OPEN CURSOR FETCH NEXT CLOSE INHERITING INTERFACES CATCH RAISING TRY ENDTRY IF ENDIF LOOP AT ENDLOOP READ KEY " +
    "BINARY SEARCH TRANSPORTING INDEX ASCENDING DESCENDING UNION MESSAGE"
  ).split(" "),
);

type Piece = { text: string; quoted: boolean };

/** The statement split into literal and non-literal runs, so layout never breaks inside a string. */
function pieces(statement: string): Piece[] {
  const out: Piece[] = [];
  let i = 0;
  let plain = "";
  while (i < statement.length) {
    const c = statement[i]!;
    if (c === "'" || c === "`" || c === "|") {
      const end = statement.indexOf(c, i + 1);
      const stop = end < 0 ? statement.length : end + 1;
      if (plain) out.push({ text: plain, quoted: false });
      plain = "";
      out.push({ text: statement.slice(i, stop), quoted: true });
      i = stop;
    } else {
      plain += c;
      i += 1;
    }
  }
  if (plain) out.push({ text: plain, quoted: false });
  return out;
}

/** Pretty-printed lines for one statement. */
export function prettyAbap(statement: string): string[] {
  const flat = statement.replace(/\s+/g, " ").trim();
  // Mark breaks in the non-literal runs only.
  const marked = pieces(flat)
    .map((p) => {
      if (p.quoted) return p.text;
      let t = p.text;
      for (const add of ADDITIONS) {
        const re = new RegExp(`(^|\\s)(${add.replace(/ /g, "\\s+")})(?=\\s|$)`, "gi");
        t = t.replace(re, (_m, lead: string, word: string) => `${lead}\u0001${word.toUpperCase()}`);
      }
      return t;
    })
    .join("");
  const parts = marked.split("\u0001").map((s) => s.trim()).filter(Boolean);
  const lines: string[] = [];
  let inWhere = false;
  parts.forEach((part, index) => {
    if (index === 0) {
      // A SELECT list: one field per line, broken after each `… AS alias`.
      if (/^SELECT\s/i.test(part) && /\sAS\s/i.test(part)) {
        const fields = part.split(/(?<=\bAS\s+[\w~-]+)\s+/i);
        lines.push(fields[0]!);
        for (const f of fields.slice(1)) lines.push(`       ${f}`);
        return;
      }
      lines.push(part);
      return;
    }
    const head = ADDITIONS.find((a) => part.toUpperCase().startsWith(a)) ?? "";
    const rest = part.slice(head.length).trim();
    inWhere = head === "WHERE" || head === "HAVING";
    if (PARAMETER_LISTS.has(head) && rest) {
      lines.push(`  ${head}`);
      // `a = b c = d` → one pair per line; `=` inside literals is safe, they are whole pieces.
      const pairs = splitPairs(rest);
      for (const pair of pairs) lines.push(`    ${pair}`);
      return;
    }
    if (inWhere && rest) {
      const conds = rest.split(/\s+(?=(?:AND|OR)\s)/i);
      lines.push(`  ${head} ${conds[0]}`);
      for (const c of conds.slice(1)) lines.push(`    ${c}`);
      return;
    }
    lines.push(`  ${head}${rest ? ` ${rest}` : ""}`);
  });
  if (lines.length) lines[lines.length - 1] = lines[lines.length - 1]!.replace(/\s*\.?\s*$/, (m) => (m.includes(".") ? "." : m.trimEnd()));
  return lines;
}

function splitPairs(text: string): string[] {
  const out: string[] = [];
  const re = /(\S+)\s*=\s*/g;
  const starts: number[] = [];
  let m: RegExpExecArray | null;
  const plain = pieces(text).map((p) => (p.quoted ? " ".repeat(p.text.length) : p.text)).join("");
  while ((m = re.exec(plain))) starts.push(m.index);
  if (starts.length === 0) return [text];
  for (let i = 0; i < starts.length; i++) out.push(text.slice(starts[i], starts[i + 1] ?? text.length).trim());
  if (starts[0]! > 0) out.unshift(text.slice(0, starts[0]).trim());
  return out.filter(Boolean);
}

export type Token = { text: string; kind: "keyword" | "string" | "number" | "comment" | "punct" | "plain" };

/** One line cut into coloured tokens. */
export function tokensOf(line: string): Token[] {
  const out: Token[] = [];
  const re = /('(?:[^']|'')*'?|`[^`]*`?|\|[^|]*\|?)|("[^\n]*$)|(\b\d+\b)|([A-Za-z_][\w\-/]*)|(\s+)|([^\sA-Za-z_\d'`|"]+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    if (m[1]) out.push({ text: m[1], kind: "string" });
    else if (m[2]) out.push({ text: m[2], kind: "comment" });
    else if (m[3]) out.push({ text: m[3], kind: "number" });
    else if (m[4]) out.push({ text: m[4], kind: KEYWORDS.has(m[4].toUpperCase()) ? "keyword" : "plain" });
    else if (m[5]) out.push({ text: m[5], kind: "plain" });
    else if (m[6]) out.push({ text: m[6], kind: "punct" });
  }
  return out;
}

