 * The graph with includes folded into their main programs.
 *
 * TADIR files every include as R3TR PROG, so a package walk lists
 * `PROG:ZX_C` beside the parse's own `INCL:ZX_C` (parent `PROG:ZX`) — the
 * same include twice, the PROG copy with no relations at all. Here the PROG
 * copy is dropped, every relation that ends at an include ends at its main
 * program instead, and `include` relations go: a program and its includes are
 * one thing to the reader. Evidence keeps the include's name and line, which
 * is where the source actually is.
 */
export function mainProgramsOnly(graph: Graph): Graph {
  const parentOf = new Map<string, string | null>();
  for (const n of graph.nodes) if (n.type === "INCL") parentOf.set(n.id, n.parent ?? null);
  const inclName = new Set([...parentOf.keys()].map((id) => id.slice("INCL:".length)));
