type SourceSnippet = { unit: string; from: number; to: number; statement: [number, number]; lines: string[]; total: number };

/**
 * One piece of evidence: the source around it — ten lines either side, line
 * numbers, the statement marked — when the account's knowledge base has the
 * unit (`GET /graph/snippet`); otherwise the stored statement, pretty-printed.
 */
function Evidence({ ev, edge }: { ev: { unit?: string; line?: number; text?: string }; edge: GEdge }) {
  const [source, setSource] = useState<SourceSnippet | null | "none">(null);
  useEffect(() => {
    if (edge.source !== "code" || !edge.system || !ev.unit || !ev.line) return setSource("none");
    const q = new URLSearchParams({ system: edge.system, unit: ev.unit, line: String(ev.line), around: "10" });
    let live = true;
    void fetch(`/api/graph/snippet?${q}`)
      .then((r) => (r.ok ? (r.json() as Promise<SourceSnippet>) : "none"))
      .then((s) => live && setSource(s as SourceSnippet | "none"))
      .catch(() => live && setSource("none"));
    return () => {
      live = false;
    };
  }, [ev.unit, ev.line, edge.source, edge.system]);

  const colour = (line: string) =>
    tokensOf(line).map((tok, k) => (
      <span key={k} className={`abap-${tok.kind}`}>
        {tok.text}
      </span>
    ));
  return (
    <section className="snippet">
      <p className="snippet-where">
        {ev.unit}
        {ev.line ? `:${ev.line}` : ""}
        {source && source !== "none" ? ` · ${source.from}–${source.to} / ${source.total}` : ""}
      </p>
      {source === null ? (
        <pre className="snippet-code">…</pre>
      ) : source === "none" ? (
        <pre className="snippet-code">
          {(edge.source === "code" ? prettyAbap(ev.text ?? "") : [ev.text ?? ""]).map((line, n) => (
            <div key={n}>{colour(line)}</div>
          ))}
        </pre>
      ) : (
        <pre className="snippet-code has-lines">
          {source.lines.map((line, n) => {
            const at = source.from + n;
            const mark = at >= source.statement[0] && at <= source.statement[1];
            return (
              <div key={n} className={mark ? "is-mark" : undefined}>
                <span className="snippet-ln">{at}</span>
                {/^\s*\*/.test(line) ? <span className="abap-comment">{line}</span> : colour(line)}
              </div>
            );
          })}
        </pre>
      )}
    </section>
  );
}

