import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, sep } from "node:path";
import { MongoClient } from "mongodb";
import { loadConfig } from "./config.ts";
import { accountSpace } from "./server/accounts.ts";
import { importGraph } from "./server/kb-store.ts";
import { importSources } from "./server/sources.ts";

function arg(name: string): string | undefined {
  const at = process.argv.indexOf(`--${name}`);
  return at > 0 ? process.argv[at + 1] : undefined;
}

const email = arg("email")?.trim().toLowerCase();
const from = arg("from");
if (!email || !from) {
  console.error("usage: npm run import-graphs -- --email <account e-mail> --from <folder with cbo/…/graph.json>");
  process.exit(2);
}

const config = loadConfig();
const uri = process.env.MONGODB_URI;
if (!uri) {
  console.error("MONGODB_URI is not set");
  process.exit(2);
}
const client = await MongoClient.connect(uri);
const user = await client.db(process.env.MONGODB_DB ?? "sc4sap").collection("users").findOne({ email });
if (!user) {
  console.error(`no account with e-mail ${email}`);
  process.exit(1);
}
const userId = String(user._id);
const space = accountSpace(config.workspace, userId);

const found: string[] = [];
const walk = (dir: string, depth: number): void => {
  if (depth > 8) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith("_prev") || entry.name === "node_modules") continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full, depth + 1);
    else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") found.push(full);
