  if (graph.system && existsSync(srcDir)) {
    const units = new Set(graph.edges.flatMap((e) => (e.evidence ?? []).map((ev) => (ev.unit ?? "").toUpperCase())).filter(Boolean));
    const { imported, bytes } = await importSources(userId, space, graph.system, srcDir, units);
