}
/** The knowledge base database, for the other kb modules (`sources.ts`). `null` without MONGODB_URI. */
export const kbDatabase = (): Promise<Db> | null => database();

async function notes(): Promise<Collection<NoteRow> | null> {
  const db = database();
  return db ? (await db).collection<NoteRow>("kb_notes") : null;
}
async function graphs(): Promise<Collection<GraphRow> | null> {
  const db = database();
  return db ? (await db).collection<GraphRow>("kb_graphs") : null;
}

/** After a batch was stored on disk: the same batch into the database. */
export async function saveNotesDb(userId: string, files: readonly NoteFile[], reset: boolean, space: AccountSpace): Promise<void> {
  const col = await notes();
  if (!col) return;
  if (reset) await col.deleteMany({ userId });
  // What the disk kept is what the database keeps: paths cleaned, refusals dropped.
  const kept = new Map(notesOf(space).map((n) => [n.path, n.text]));
  const wanted = files.map((f) => f.path.replace(/\\/g, "/").split("/").filter((p) => p && p !== ".").join("/"));
  const ops = wanted
    .filter((path) => kept.has(path))
    .map((path) => ({
      updateOne: {
        filter: { userId, path },
        update: { $set: { userId, path, text: kept.get(path)!, size: Buffer.byteLength(kept.get(path)!), updatedAt: new Date() } },
        upsert: true,
      },
    }));
  if (ops.length) await col.bulkWrite(ops, { ordered: false });
}

export async function deleteNotesDb(userId: string): Promise<void> {
  await (await notes())?.deleteMany({ userId });
}

/** Uploads the account's disk graphs that the database lacks or has older. */
export async function mirrorGraphs(userId: string, space: AccountSpace): Promise<{ uploaded: number }> {
  const col = await graphs();
  if (!col) return { uploaded: 0 };
  let uploaded = 0;
  for (const ref of listGraphs(space)) {
    const key = `${ref.system}/${ref.package}`;
    const mtime = Math.floor(statSync(ref.file).mtimeMs);
    const row = await col.findOne({ userId, key }, { projection: { sourceMtime: 1 } });
    if (row && row.sourceMtime >= mtime) continue;
    const gz = gzipSync(JSON.stringify(readGraph(ref.file)));
    if (gz.length > MAX_GZ) continue;
    await col.updateOne(
      { userId, key },
      {
        $set: {
          userId, key, system: ref.system, package: ref.package, module: ref.module, builtAt: ref.builtAt,
          nodes: ref.nodes, edges: ref.edges, sourceMtime: mtime, gz: new Binary(gz), updatedAt: new Date(),
        },
      },
      { upsert: true },
    );
    uploaded += 1;
  }
  return { uploaded };
}

/** Once per account per process: fill an empty disk back from the database. */
const hydrated = new Map<string, Promise<void>>();
export function hydrate(userId: string, space: AccountSpace): Promise<void> {
  if (!space.home || !process.env.MONGODB_URI) return Promise.resolve();
  let done = hydrated.get(userId);
  if (!done) {
    done = (async () => {
      const nc = await notes();
      if (nc && summarize(space).count === 0) {
        const rows = await nc.find({ userId }).toArray();
        if (rows.length) storeNotes(space, rows.map((r) => ({ path: r.path, text: r.text })), true);
      }
      const gc = await graphs();
      if (gc) {
        const onDisk = new Set(listGraphs(space).map((g) => `${g.system}/${g.package}`));
        for (const row of await gc.find({ userId }).toArray()) {
          if (onDisk.has(row.key)) continue;
          const file = join(space.root, "ws", "_kb", "cbo", row.module || "X", row.package, "graph.json");
          if (existsSync(file)) continue;
          mkdirSync(dirname(file), { recursive: true });
          writeFileSync(file, gunzipSync(Buffer.from(row.gz.buffer)));
          // Its mtime is the uploaded one, so mirroring does not send it back.
          utimesSync(file, new Date(), new Date(row.sourceMtime));
        }
      }
    })().catch((err: unknown) => {
      hydrated.delete(userId);
      throw err;
    });
    hydrated.set(userId, done);
  }
  return done;
}

/** Everything of one account in the database — for its deletion. */
export async function deleteAccountKb(userId: string): Promise<void> {
  await (await notes())?.deleteMany({ userId });
  await (await graphs())?.deleteMany({ userId });
  await (await database())?.collection("kb_sources").deleteMany({ userId });
  hydrated.delete(userId);
}

/** For the import script: one graph file into one account, disk and database. */
export async function importGraph(userId: string, space: AccountSpace, source: string, module: string, pkg: string): Promise<string> {
  const target = join(space.root, "ws", "_kb", "cbo", module || "X", pkg, "graph.json");
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, JSON.stringify(readGraph(source)));
  await mirrorGraphs(userId, space);
  return target;
}

