103	    const mtime = Math.floor(statSync(ref.file).mtimeMs);
104	    const row = await col.findOne({ userId, key }, { projection: { sourceMtime: 1 } });
105	    if (row && row.sourceMtime >= mtime) continue;
106	    const gz = gzipSync(JSON.stringify(readGraph(ref.file)));
107	    if (gz.length > MAX_GZ) continue;
108	    await col.updateOne(
109	      { userId, key },
110	      {
111	        $set: {
112	          userId, key, system: ref.system, package: ref.package, module: ref.module, builtAt: ref.builtAt,
113	          nodes: ref.nodes, edges: ref.edges, sourceMtime: mtime, gz: new Binary(gz), updatedAt: new Date(),
114	        },
115	      },
116	      { upsert: true },
117	    );
118	    uploaded += 1;
119	  }
120	  return { uploaded };
