125	export function hydrate(userId: string, space: AccountSpace): Promise<void> {
126	  if (!space.home || !process.env.MONGODB_URI) return Promise.resolve();
127	  let done = hydrated.get(userId);
128	  if (!done) {
129	    done = (async () => {
130	      const nc = await notes();
131	      if (nc && summarize(space).count === 0) {
132	        const rows = await nc.find({ userId }).toArray();
133	        if (rows.length) storeNotes(space, rows.map((r) => ({ path: r.path, text: r.text })), true);
134	      }
135	      const gc = await graphs();
136	      if (gc) {
137	        const onDisk = new Set(listGraphs(space).map((g) => `${g.system}/${g.package}`));
138	        for (const row of await gc.find({ userId }).toArray()) {
139	          if (onDisk.has(row.key)) continue;
140	          const file = join(space.root, "ws", "_kb", "cbo", row.module || "X", row.package, "graph.json");
141	          if (existsSync(file)) continue;
142	          mkdirSync(dirname(file), { recursive: true });
143	          writeFileSync(file, gunzipSync(Buffer.from(row.gz.buffer)));
144	          // Its mtime is the uploaded one, so mirroring does not send it back.
145	          utimesSync(file, new Date(), new Date(row.sourceMtime));
146	        }
147	      }
148	    })().catch((err: unknown) => {
149	      hydrated.delete(userId);
150	      throw err;
151	    });
152	    hydrated.set(userId, done);
153	  }
