/**
 * ABAP source around a relation's evidence — the graph tab's snippet popup.
 *
 * The graph keeps one statement per piece of evidence, cut at 120 characters;
 * reading it in context needs the unit's source. Looked for, in order:
 *
 *   1. the account's own sessions: `GetProgFullCode output:"file"` leaves
 *      `<name>.<kind>.abap` files under `…/mcp-output/src/`
 *   2. the account's knowledge base copy, `ws/_kb/src/<system>/<UNIT>.abap`
 *   3. MongoDB `kb_sources` (gzipped), written back to (2) on the way
 *
 * (2) and (3) are filled by `import-graphs`, which brings each imported
 * graph's units along. Never the live SAP system: the system an account is
 * connected to need not be the one a graph was built on.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { gunzipSync, gzipSync } from "node:zlib";
import { Binary, type Collection } from "mongodb";
import type { AccountSpace } from "./accounts.ts";
import { kbDatabase } from "./kb-store.ts";

type SourceRow = { userId: string; system: string; unit: string; gz: Binary; size: number; updatedAt: Date };

async function sources(): Promise<Collection<SourceRow> | null> {
  const db = kbDatabase();
  if (!db) return null;
  const col = (await db).collection<SourceRow>("kb_sources");
  await col.createIndex({ userId: 1, system: 1, unit: 1 }, { unique: true, name: "kb_source_unit" });
  return col;
}

const FILE = /^([^.]+)\.(incl|prog|func|clas|fugr|intf)\.abap$/i;
/** `zsdr24730c.incl.abap` → `ZSDR24730C`; `#apol#fm_x.func.abap` → `/APOL/FM_X`. */
const unitOf = (file: string) => FILE.exec(file)?.[1]?.replace(/#/g, "/").toUpperCase() ?? null;
const safeUnit = (unit: string) => /^[A-Z0-9_/]{1,60}$/.test(unit);
const kbFile = (space: AccountSpace, system: string, unit: string) =>
  join(space.root, "ws", "_kb", "src", system.replace(/[^\w-]/g, "_"), `${unit.replace(/\//g, "#")}.abap`);

/** Every source file under one folder (and its sub-folders), by unit. */
export function indexSources(dir: string, depth = 0, into = new Map<string, string>()): Map<string, string> {
  if (depth > 3 || !existsSync(dir)) return into;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!entry.name.startsWith("_")) indexSources(full, depth + 1, into);
      continue;
    }
    const unit = unitOf(entry.name);
    // The top level wins over a sub-folder copy of the same unit.
    if (unit && (!into.has(unit) || depth === 0)) into.set(unit, full);
  }
  return into;
}

/** The account's session output folders: `…/mcp-output/src` anywhere in its workspaces. */
function sessionSourceDirs(space: AccountSpace): string[] {
  const found: string[] = [];
  const visit = (dir: string, depth: number): void => {
    if (depth > 7 || !existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (!entry.isDirectory() || entry.name === "node_modules" || entry.name === "_kb") continue;
      const full = join(dir, entry.name);
      if (entry.name === "src" && dir.endsWith("mcp-output")) found.push(full);
      else visit(full, depth + 1);
    }
  };
  visit(join(space.root, "ws"), 0);
  return found;
}

const sessionIndex = new Map<string, { at: number; index: Map<string, string> }>();
function sessionFile(space: AccountSpace, unit: string): string | null {
  const hit = sessionIndex.get(space.root);
  // Re-scanned at most once a minute: a session may have just fetched more.
  if (!hit || Date.now() - hit.at > 60_000) {
    const index = new Map<string, string>();
    for (const dir of sessionSourceDirs(space)) indexSources(dir, 0, index);
    sessionIndex.set(space.root, { at: Date.now(), index });
  }
  return sessionIndex.get(space.root)!.index.get(unit) ?? null;
}

async function sourceText(userId: string, space: AccountSpace, system: string, unit: string): Promise<string | null> {
  const own = sessionFile(space, unit);
  if (own) return readFileSync(own, "utf8");
  const local = kbFile(space, system, unit);
  if (existsSync(local)) return readFileSync(local, "utf8");
  const col = await sources();
  const row = col ? await col.findOne({ userId, system, unit }) : null;
  if (!row) return null;
  const text = gunzipSync(Buffer.from(row.gz.buffer)).toString("utf8");
  mkdirSync(dirname(local), { recursive: true });
  writeFileSync(local, text, "utf8");
  return text;
}

export type Snippet = {
  unit: string;
  system: string;
  /** First and last line shown, 1-based. */
  from: number;
  to: number;
  /** The statement the evidence points at, first and last line. */
  statement: [number, number];
  lines: string[];
  total: number;
};

/** `around` lines before and after the statement starting at `line`. */
export async function snippet(
  userId: string,
  space: AccountSpace,
  system: string,
  unit: string,
  line: number,
  around = 10,
): Promise<Snippet | null> {
  const name = unit.toUpperCase();
  if (!space.home || !safeUnit(name) || !(line > 0)) return null;
  const text = await sourceText(userId, space, system, name);
  if (text === null) return null;
  const all = text.split(/\r?\n/);
  /** A line's code with comments and literals set aside, or "" for a comment line. */
  const code = (n: number) => {
    const raw = all[n - 1] ?? "";
    if (/^\s*\*/.test(raw)) return "";
    return raw.replace(/'[^']*'|`[^`]*`|\|[^|]*\|/g, "''").replace(/".*$/, "").trim();
  };
  const ends = (n: number) => /[.]$/.test(code(n));
  // The parse's line can land inside the statement; its start is the first
  // code line after the previous statement's period.
  let start = Math.min(line, all.length);
  for (let k = start - 1, steps = 0; k >= 1 && steps < 40; k--, steps++) {
    if (ends(k)) break;
    if (code(k)) start = k;
  }
  // And it runs to the first line whose code ends in a period.
  let end = Math.max(start, Math.min(line, all.length));
  for (let i = end; i <= Math.min(all.length, end + 60); i++) {
    if (ends(i)) {
      end = i;
      break;
    }
  }
  const from = Math.max(1, start - around);
  const to = Math.min(all.length, end + around);
  return { unit: name, system, from, to, statement: [start, end], lines: all.slice(from - 1, to), total: all.length };
}

/** For `import-graphs`: the given units of one system's source folder into the account. */
export async function importSources(
  userId: string,
  space: AccountSpace,
  system: string,
  srcDir: string,
  units: ReadonlySet<string>,
): Promise<{ imported: number; bytes: number }> {
  const index = indexSources(srcDir);
  const col = await sources();
  let imported = 0;
  let bytes = 0;
  for (const unit of units) {
    const file = index.get(unit);
    if (!file || statSync(file).size > 8 * 1024 * 1024) continue;
    const text = readFileSync(file, "utf8");
    const local = kbFile(space, system, unit);
    mkdirSync(dirname(local), { recursive: true });
    writeFileSync(local, text, "utf8");
    if (col) {
      const gz = gzipSync(text);
      await col.updateOne(
        { userId, system, unit },
        { $set: { userId, system, unit, gz: new Binary(gz), size: text.length, updatedAt: new Date() } },
        { upsert: true },
      );
      bytes += gz.length;
    }
    imported += 1;
  }
  return { imported, bytes };
}

export async function deleteSourcesDb(userId: string): Promise<void> {
  await (await sources())?.deleteMany({ userId });
}

/**
 * Puts CBO graphs analysed outside the web app — the plugin run in Claude
 * Code, writing `.sc4sap/work/<SYSTEM>/cbo/<MODULE>/<PACKAGE>/graph.json` —
 * into one web account: its disk working copy and its MongoDB knowledge base
 * (`server/kb-store.ts`). The account then sees them in the graph tab, the
 * Obsidian plugin and the agent's graph tools, as if it had run the analysis.
 *
 *   npm run import-graphs -- --email you@example.com --from ../.sc4sap/work
 *
 * Only the named account. `_prev*` snapshots are skipped.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, sep } from "node:path";
import { MongoClient } from "mongodb";
import { loadConfig } from "./config.ts";
import { accountSpace } from "./server/accounts.ts";
import { importGraph } from "./server/kb-store.ts";
import { importSources } from "./server/sources.ts";

function arg(name: string): string | undefined {
  const at = process.argv.indexOf(`--${name}`);
  return at > 0 ? process.argv[at + 1] : undefined;
}

const email = arg("email")?.trim().toLowerCase();
const from = arg("from");
if (!email || !from) {
  console.error("usage: npm run import-graphs -- --email <account e-mail> --from <folder with cbo/…/graph.json>");
  process.exit(2);
}

const config = loadConfig();
const uri = process.env.MONGODB_URI;
if (!uri) {
  console.error("MONGODB_URI is not set");
  process.exit(2);
}
const client = await MongoClient.connect(uri);
const user = await client.db(process.env.MONGODB_DB ?? "sc4sap").collection("users").findOne({ email });
if (!user) {
  console.error(`no account with e-mail ${email}`);
  process.exit(1);
}
const userId = String(user._id);
const space = accountSpace(config.workspace, userId);

const found: string[] = [];
const walk = (dir: string, depth: number): void => {
  if (depth > 8) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith("_prev") || entry.name === "node_modules") continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full, depth + 1);
    else if (entry.name === "graph.json" && full.split(sep).slice(-4, -3)[0] === "cbo") found.push(full);
  }
};
walk(from, 0);

for (const file of found) {
  const parts = file.split(sep);
  const pkg = parts[parts.length - 2]!;
  const module = parts[parts.length - 3]!;
  const target = await importGraph(userId, space, file, module, pkg);
  console.log(`${module}/${pkg} (${(statSync(file).size / 1048576).toFixed(1)} MB) → ${target}`);
  // The units its evidence points at, from the same system's source folder
  // (<SYSTEM>/mcp-output/src beside <SYSTEM>/cbo), so the snippet popup can
  // show them in context.
  const graph = JSON.parse(readFileSync(file, "utf8")) as { system?: string; edges: { evidence?: { unit?: string }[] }[] };
  const srcDir = join(file, "..", "..", "..", "..", "mcp-output", "src");
  if (graph.system && existsSync(srcDir)) {
    const units = new Set(graph.edges.flatMap((e) => (e.evidence ?? []).map((ev) => (ev.unit ?? "").toUpperCase())).filter(Boolean));
    const { imported, bytes } = await importSources(userId, space, graph.system, srcDir, units);
    console.log(`  sources: ${imported} of ${units.size} units (${(bytes / 1048576).toFixed(1)} MB gz)`);
  }
}
console.log(`${found.length} graph(s) imported for ${email}`);
await client.close();
process.exit(0);

/**
 * MongoDB as the home of each account's knowledge base — its reference notes
 * (`kb_notes`) and its CBO graphs (`kb_graphs`, gzipped graph.json) — with
 * the account folder on this machine as the working copy.
 *
 * Why both: the agent's tools and session start read notes and graphs
 * synchronously and often (`notes.ts`, `vault.ts`), which a local file does
 * well; a second server, a rebuilt machine or a wiped disk is what the
 * database is for. So every write goes to both, and an account's first
 * request on a process whose disk has nothing for it fills the disk back from
 * the database (`hydrate`). Graphs are written by plugin skills straight to
 * disk; `mirrorGraphs` uploads any that are new or changed, by mtime.
 *
 * Without `MONGODB_URI` every function here is a no-op and the disk is all
 * there is, exactly as before.
 */
import { existsSync, mkdirSync, statSync, utimesSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { gunzipSync, gzipSync } from "node:zlib";
import { Binary, MongoClient, type Collection, type Db } from "mongodb";
import type { AccountSpace } from "./accounts.ts";
import { notesOf, storeNotes, summarize, type NoteFile } from "./notes.ts";
import { listGraphs, readGraph } from "./vault.ts";

type NoteRow = { userId: string; path: string; text: string; size: number; updatedAt: Date };
type GraphRow = {
  userId: string;
  /** `<system>/<package>` — one graph per package and system per account. */
  key: string;
  system: string;
  package: string;
  module: string;
  builtAt: string | null;
  nodes: number;
  edges: number;
  /** The disk file's mtime when uploaded, so an unchanged file is not sent again. */
  sourceMtime: number;
  gz: Binary;
  updatedAt: Date;
};

/** Mongo's document limit is 16 MB; a compressed graph past this stays on disk only. */
const MAX_GZ = 15 * 1024 * 1024;

let connecting: Promise<Db> | null = null;
function database(): Promise<Db> | null {
  const uri = process.env.MONGODB_URI;
  if (!uri) return null;
  connecting ??= MongoClient.connect(uri).then(async (client) => {
    const db = client.db(process.env.MONGODB_DB ?? "sc4sap");
    await db.collection<NoteRow>("kb_notes").createIndex({ userId: 1, path: 1 }, { unique: true, name: "kb_note_path" });
    await db.collection<GraphRow>("kb_graphs").createIndex({ userId: 1, key: 1 }, { unique: true, name: "kb_graph_key" });
    return db;
  });
  connecting.catch(() => {
    connecting = null;
  });
  return connecting;
}
/** The knowledge base database, for the other kb modules (`sources.ts`). `null` without MONGODB_URI. */
export const kbDatabase = (): Promise<Db> | null => database();

async function notes(): Promise<Collection<NoteRow> | null> {
  const db = database();
  return db ? (await db).collection<NoteRow>("kb_notes") : null;
}
async function graphs(): Promise<Collection<GraphRow> | null> {
  const db = database();
  return db ? (await db).collection<GraphRow>("kb_graphs") : null;
}

/** After a batch was stored on disk: the same batch into the database. */
export async function saveNotesDb(userId: string, files: readonly NoteFile[], reset: boolean, space: AccountSpace): Promise<void> {
  const col = await notes();
  if (!col) return;
  if (reset) await col.deleteMany({ userId });
  // What the disk kept is what the database keeps: paths cleaned, refusals dropped.
  const kept = new Map(notesOf(space).map((n) => [n.path, n.text]));
  const wanted = files.map((f) => f.path.replace(/\\/g, "/").split("/").filter((p) => p && p !== ".").join("/"));
  const ops = wanted
    .filter((path) => kept.has(path))
    .map((path) => ({
      updateOne: {
        filter: { userId, path },
        update: { $set: { userId, path, text: kept.get(path)!, size: Buffer.byteLength(kept.get(path)!), updatedAt: new Date() } },
        upsert: true,
      },
    }));
  if (ops.length) await col.bulkWrite(ops, { ordered: false });
}

export async function deleteNotesDb(userId: string): Promise<void> {
  await (await notes())?.deleteMany({ userId });
}

/** Uploads the account's disk graphs that the database lacks or has older. */
export async function mirrorGraphs(userId: string, space: AccountSpace): Promise<{ uploaded: number }> {
  const col = await graphs();
  if (!col) return { uploaded: 0 };
  let uploaded = 0;
  for (const ref of listGraphs(space)) {
    const key = `${ref.system}/${ref.package}`;
    const mtime = Math.floor(statSync(ref.file).mtimeMs);
    const row = await col.findOne({ userId, key }, { projection: { sourceMtime: 1 } });
    if (row && row.sourceMtime >= mtime) continue;
    const gz = gzipSync(JSON.stringify(readGraph(ref.file)));
    if (gz.length > MAX_GZ) continue;
    await col.updateOne(
      { userId, key },
      {
        $set: {
          userId, key, system: ref.system, package: ref.package, module: ref.module, builtAt: ref.builtAt,
          nodes: ref.nodes, edges: ref.edges, sourceMtime: mtime, gz: new Binary(gz), updatedAt: new Date(),
        },
      },
      { upsert: true },
    );
    uploaded += 1;
  }
  return { uploaded };
}

/** Once per account per process: fill an empty disk back from the database. */
const hydrated = new Map<string, Promise<void>>();
export function hydrate(userId: string, space: AccountSpace): Promise<void> {
  if (!space.home || !process.env.MONGODB_URI) return Promise.resolve();
  let done = hydrated.get(userId);
  if (!done) {
    done = (async () => {
      const nc = await notes();
      if (nc && summarize(space).count === 0) {
        const rows = await nc.find({ userId }).toArray();
        if (rows.length) storeNotes(space, rows.map((r) => ({ path: r.path, text: r.text })), true);
      }
      const gc = await graphs();
      if (gc) {
        const onDisk = new Set(listGraphs(space).map((g) => `${g.system}/${g.package}`));
        for (const row of await gc.find({ userId }).toArray()) {
          if (onDisk.has(row.key)) continue;
          const file = join(space.root, "ws", "_kb", "cbo", row.module || "X", row.package, "graph.json");
          if (existsSync(file)) continue;
          mkdirSync(dirname(file), { recursive: true });
          writeFileSync(file, gunzipSync(Buffer.from(row.gz.buffer)));
          // Its mtime is the uploaded one, so mirroring does not send it back.
          utimesSync(file, new Date(), new Date(row.sourceMtime));
        }
      }
    })().catch((err: unknown) => {
      hydrated.delete(userId);
      throw err;
    });
    hydrated.set(userId, done);
  }
  return done;
}

/** Everything of one account in the database — for its deletion. */
export async function deleteAccountKb(userId: string): Promise<void> {
  await (await notes())?.deleteMany({ userId });
  await (await graphs())?.deleteMany({ userId });
  await (await database())?.collection("kb_sources").deleteMany({ userId });
  hydrated.delete(userId);
}

/** For the import script: one graph file into one account, disk and database. */
export async function importGraph(userId: string, space: AccountSpace, source: string, module: string, pkg: string): Promise<string> {
  const target = join(space.root, "ws", "_kb", "cbo", module || "X", pkg, "graph.json");
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, JSON.stringify(readGraph(source)));
  await mirrorGraphs(userId, space);
  return target;
}

