123	/** Once per account per process: fill an empty disk back from the database. */
124	const hydrated = new Map<string, Promise<void>>();
125	export function hydrate(userId: string, space: AccountSpace): Promise<void> {
126	  if (!space.home || !process.env.MONGODB_URI) return Promise.resolve();
127	  let done = hydrated.get(userId);
128	  if (!done) {
129	    done = (async () => {
130	      const nc = await notes();
131	      if (nc && summarize(space).count === 0) {
132	        const rows = await nc.find({ userId }).toArray();
133	        if (rows.length) storeNotes(space, rows.map((r) => ({ path: r.path, text: r.text })), true);
134	      }
135	      const gc = await graphs();
136	      if (gc) {
137	        const onDisk = new Set(listGraphs(space).map((g) => `${g.system}/${g.package}`));
138	        for (const row of await gc.find({ userId }).toArray()) {
139	          if (onDisk.has(row.key)) continue;
140	          const file = join(space.root, "ws", "_kb", "cbo", row.module || "X", row.package, "graph.json");
141	          if (existsSync(file)) continue;
142	          mkdirSync(dirname(file), { recursive: true });
143	          writeFileSync(file, gunzipSync(Buffer.from(row.gz.buffer)));
144	          // Its mtime is the uploaded one, so mirroring does not send it back.
145	          utimesSync(file, new Date(), new Date(row.sourceMtime));
146	        }
147	      }
148	    })().catch((err: unknown) => {
149	      hydrated.delete(userId);
150	      throw err;
151	    });
152	    hydrated.set(userId, done);
153	  }
154	  return done;
155	}
156	
157	/** Everything of one account in the database — for its deletion. */
158	export async function deleteAccountKb(userId: string): Promise<void> {
159	  await (await notes())?.deleteMany({ userId });
160	  await (await graphs())?.deleteMany({ userId });
161	  await (await database())?.collection("kb_sources").deleteMany({ userId });
162	  hydrated.delete(userId);
163	}
164	
165	/** For the import script: one graph file into one account, disk and database. */
166	export async function importGraph(userId: string, space: AccountSpace, source: string, module: string, pkg: string): Promise<string> {
167	  const target = join(space.root, "ws", "_kb", "cbo", module || "X", pkg, "graph.json");
168	  mkdirSync(dirname(target), { recursive: true });
169	  writeFileSync(target, JSON.stringify(readGraph(source)));
170	  await mirrorGraphs(userId, space);
171	  return target;
172	}
