/**
 * One object and what it touches, in the merged graph the agent queries
 * (`knowledgeOf`: every CBO graph of the account plus the relations written
 * in its notes) — for the web's graph tab. `q` instead of `object` lists
 * matching objects for the search box.
 */
app.get<{ Querystring: { object?: string; q?: string; kinds?: string } }>("/graph", async (request, reply) => {
  const space = spaceOf(request.headers);
  if (!space.home) return reply.code(400).send({ error: "not an account" });
  const K = knowledgeOf(space);
  if (!K) return { empty: true };
  const q = request.query.q?.trim().toUpperCase();
  if (q) {
    const hits = [...K.nodes.values()]
      .filter((n) => n.name.toUpperCase().includes(q) || n.id.toUpperCase().includes(q))
      .sort((a, b) => (a.scope === "member" ? 0 : 1) - (b.scope === "member" ? 0 : 1) || a.name.length - b.name.length)
      .slice(0, 20)
      .map(({ id, type, name, scope }) => ({ id, type, name, scope }));
    return { hits };
  }
  const id = resolveRef(K, request.query.object ?? "");
  if (!id) return reply.code(404).send({ error: "unknown object" });
  const keep = request.query.kinds ? new Set(request.query.kinds.split(",")) : null;
  // The member's own relations first: on a hub they would otherwise fall
  // past the cut behind hundreds of parsed ones.
  const pick = (list: KEdge[] | undefined) =>
    (list ?? [])
      .filter((e) => !keep || keep.has(e.kind))
      .sort((a, b) => (a.source === "note" ? 0 : 1) - (b.source === "note" ? 0 : 1))
      .slice(0, 150);
  const edges = [...pick(K.out.get(id)), ...pick(K.inc.get(id))];
  const ids = new Set([id, ...edges.flatMap((e) => [e.from, e.to])]);
  const node = (x: string) => {
    const n = K.nodes.get(x);
    return { id: x, type: n?.type ?? x.split(":")[0] ?? "NOTE", name: n?.name ?? x, scope: n?.scope ?? null };
  };
  return {
    center: id,
    nodes: [...ids].map(node),
    edges,
    totals: { out: K.out.get(id)?.length ?? 0, in: K.inc.get(id)?.length ?? 0 },
  };
});

