336	   * before and after the statement at `unit`:`line` — see `sources.ts`.
337	   */
338	  app.get<{ Querystring: { system?: string; unit?: string; line?: string; around?: string } }>(
339	    "/graph/snippet",
340	    async (request, reply) => {
341	      const space = spaceOf(request.headers);
342	      if (!space.home) return reply.code(400).send({ error: "not an account" });
343	      const { system = "", unit = "", line = "", around = "10" } = request.query;
344	      const found = await snippet(

250	  const where = ev?.unit ? `${ev.unit}${ev.line ? `:${ev.line}` : ""}` : "";
251	  return [where, e.confidence === "low" ? "low" : "", e.count && e.count > 1 ? `×${e.count}` : ""].filter(Boolean).join(" · ");
252	}
253	
254	/**
255	 * The graph with includes folded into their main programs.
256	 *
257	 * TADIR files every include as R3TR PROG, so a package walk lists
258	 * `PROG:ZX_C` beside the parse's own `INCL:ZX_C` (parent `PROG:ZX`) — the
259	 * same include twice, the PROG copy with no relations at all. Here the PROG
260	 * copy is dropped, every relation that ends at an include ends at its main
261	 * program instead, and `include` relations go: a program and its includes are
262	 * one thing to the reader. Evidence keeps the include's name and line, which
263	 * is where the source actually is.
264	 */
265	export function mainProgramsOnly(graph: Graph): Graph {
266	  const parentOf = new Map<string, string | null>();
267	  for (const n of graph.nodes) if (n.type === "INCL") parentOf.set(n.id, n.parent ?? null);
268	  const inclName = new Set([...parentOf.keys()].map((id) => id.slice("INCL:".length)));
269	  const dropped = (n: GNode) => n.type === "INCL" || (n.type === "PROG" && inclName.has(n.name));
270	  const map = (id: string): string | null => {
271	    if (parentOf.has(id)) return parentOf.get(id) ?? null;
272	    if (id.startsWith("PROG:") && inclName.has(id.slice(5))) return parentOf.get(`INCL:${id.slice(5)}`) ?? null;
273	    return id;
274	  };
275	  const merged = new Map<string, GEdge>();
276	  for (const e of graph.edges) {
277	    if (e.kind === "include") continue;
278	    const from = map(e.from);
279	    const to = map(e.to);
280	    if (!from || !to || from === to) continue;
281	    const key = `${from}|${e.kind}|${to}`;
282	    const had = merged.get(key);
283	    if (had) {
284	      had.count = (had.count ?? 1) + (e.count ?? 1);
285	      had.evidence = [...(had.evidence ?? []), ...(e.evidence ?? [])].slice(0, 5);
286	    } else merged.set(key, { ...e, from, to, evidence: e.evidence ? [...e.evidence] : undefined });
287	  }
288	  return { ...graph, nodes: graph.nodes.filter((n) => !dropped(n)), edges: [...merged.values()] };
289	}
290	
291	/** The vault's files for one package graph, merged into what the member already has. */
292	export function buildVault(source: Graph, opts: VaultOptions): Map<string, string> {
293	  const graph = mainProgramsOnly(source);
294	  const pkg = graph.package ?? "PACKAGE";
295	  // A system named `.` or `..` would climb out of SC4SAP/.
296	  const system = noteFile(`X:${opts.system}`).slice(2).replace(/^\.+$/, "_") || "SAP";
297	  const base = `SC4SAP/${system}`;
298	  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
299	  const hidden = (id: string) => !opts.detail && DETAIL_HIDDEN_TYPES.has(nodes.get(id)?.type ?? "");

580	/** `evidence`: the ABAP statements the parse found (at most 5, from graph.json) or the note line. */
581	export type KEdge = {
582	  from: string;
583	  to: string;
584	  kind: string;
585	  source: "code" | "note";
586	  where: string;
587	  evidence?: Evidence[];
588	  /** The SAP system the graph was built on — where its evidence's source is. */
589	  system?: string;
590	  negated?: boolean;
591	};
592	export type Knowledge = { nodes: Map<string, { id: string; type: string; name: string; scope?: string }>; out: Map<string, KEdge[]>; inc: Map<string, KEdge[]>; edges: number };
593	
594	export function buildKnowledge(graphs: readonly Graph[], curated: readonly CuratedEdge[]): Knowledge {
595	  const nodes: Knowledge["nodes"] = new Map();
596	  const seen = new Map<string, KEdge>();
597	  for (const raw of graphs) {
598	    const g = mainProgramsOnly(raw);
599	    for (const n of g.nodes) if (!nodes.has(n.id)) nodes.set(n.id, n);
600	    for (const e of g.edges) {
601	      if (e.kind === "dynamic") continue;
602	      const key = `${e.from}|${e.kind}|${e.to}`;
603	      if (!seen.has(key)) {
604	        seen.set(key, {
605	          from: e.from, to: e.to, kind: e.kind, source: "code",
606	          where: `${g.package ?? ""} ${evidenceOf(e)}`.trim(),
607	          ...(e.evidence?.length ? { evidence: e.evidence } : {}),
608	          ...(g.system ? { system: g.system } : {}),
609	        });
610	      }
611	    }
612	  }
613	  for (const c of curated) {
614	    for (const id of [c.from, c.to]) {
615	      if (!nodes.has(id)) nodes.set(id, { id, type: id.split(":")[0] ?? "NOTE", name: id.split(":").slice(1).join(":") });
616	    }
617	    const key = `${c.from}|${c.kind}|${c.to}`;
618	    if (c.negated) {
619	      const code = seen.get(key);
620	      if (code) code.negated = true;
621	      continue;
622	    }
623	    if (!seen.has(key) || seen.get(key)!.source === "code") {
624	      seen.set(key, {
625	        from: c.from, to: c.to, kind: c.kind, source: "note", where: c.note,
626	        ...(c.text ? { evidence: [{ unit: c.note, text: c.text }] } : {}),
627	      });
628	    }
629	  }
630	  const out: Knowledge["out"] = new Map();
631	  const inc: Knowledge["inc"] = new Map();
632	  for (const e of seen.values()) {
633	    if (e.negated) continue;
634	    const o = out.get(e.from);
635	    if (o) o.push(e);
636	    else out.set(e.from, [e]);
637	    const i = inc.get(e.to);
638	    if (i) i.push(e);
639	    else inc.set(e.to, [e]);
640	  }
641	  return { nodes, out, inc, edges: [...seen.values()].filter((e) => !e.negated).length };
642	}
643	
644	// A bare name means the program before the TCode that shares it.
645	const RANK = ["PROG", "TRAN","FUGR", "FUNC", "CLAS", "INTF", "TABL", "VIEW", "PROCESS", "NOTE", "PACKAGE", "STRU", "DTEL", "INCL"];
646	/** `ZSDR24730`, `PROG:ZSDR24730`, `PROG ZSDR24730` or a note's name → a node id. */
647	export function resolveRef(K: Knowledge, ref: string): string | null {
648	  const r = ref.trim().replace(/^\[\[|\]\]$/g, "");
649	  if (K.nodes.has(r)) return r;
650	  const up = r.toUpperCase();
651	  if (K.nodes.has(up)) return up;
652	  const spaced = /^([A-Z]+) (.+)$/.exec(r);
653	  if (spaced && K.nodes.has(`${spaced[1]}:${spaced[2]}`)) return `${spaced[1]}:${spaced[2]}`;
654	  if (K.nodes.has(`NOTE:${r}`)) return `NOTE:${r}`;
655	  const hits = [...K.nodes.values()].filter((n) => n.name === r || n.name.toUpperCase() === up);
656	  if (!hits.length) return null;
657	  return hits.sort((a, b) => (a.scope === "member" ? 0 : 1) - (b.scope === "member" ? 0 : 1) || (RANK.indexOf(a.type) + 1 || 99) - (RANK.indexOf(b.type) + 1 || 99))[0]?.id ?? null;
658	}
