const trail = useRef<string[]>([]);
/** The relation whose snippet is in the popup. */
const [snippet, setSnippet] = useState<GEdge | null>(null);
/**
 * The visible part of the drawing: wheel zooms around the pointer, dragging
 * the background pans, the buttons step. Reset whenever another object is
 * opened — a zoom chosen for one neighbourhood means nothing for the next.
 */
const [box, setBox] = useState({ x: 0, y: 0, w: W, h: H });
const svgRef = useRef<SVGSVGElement | null>(null);
const drag = useRef<{ x: number; y: number; box: typeof box; moved: boolean } | null>(null);
const zoomAt = useCallback((factor: number, cx?: number, cy?: number) => {
  setBox((b) => {
    const w = Math.min(W * 4, Math.max(W / 8, b.w * factor));
    const h = (w / W) * H;
    const px = cx ?? b.x + b.w / 2;
    const py = cy ?? b.y + b.h / 2;
    return { x: px - ((px - b.x) / b.w) * w, y: py - ((py - b.y) / b.h) * h, w, h };
  });
}, []);
/** A screen point as a drawing coordinate, for zooming around the pointer. */
const toDrawing = (clientX: number, clientY: number) => {
  const rect = svgRef.current?.getBoundingClientRect();
  if (!rect) return { x: box.x + box.w / 2, y: box.y + box.h / 2 };
  return { x: box.x + ((clientX - rect.left) / rect.width) * box.w, y: box.y + ((clientY - rect.top) / rect.height) * box.h };
