// Spawns an MCP server over stdio, does initialize + tools/list, prints the tool count.
import { spawn } from "node:child_process";

const [launcher] = process.argv.slice(2);
const child = spawn(process.execPath, [launcher, "--transport=stdio"], {
  env: { ...process.env, SAP_URL: "https://sap.invalid:44300", SAP_CLIENT: "100", SAP_USERNAME: "SMOKE", SAP_PASSWORD: "x", SAP_AUTH_TYPE: "basic" },
  stdio: ["pipe", "pipe", "pipe"],
});
let buf = "";
let stderr = "";
const send = (msg) => child.stdin.write(JSON.stringify(msg) + "\n");
const timer = setTimeout(() => {
  console.log("TIMEOUT; stderr tail:\n" + stderr.split("\n").slice(-15).join("\n"));
  child.kill();
  process.exit(1);
}, 60000);
child.stderr.on("data", (d) => (stderr += d));
child.stdout.on("data", (d) => {
  buf += d;
  let i;
  while ((i = buf.indexOf("\n")) >= 0) {
    const line = buf.slice(0, i);
    buf = buf.slice(i + 1);
    let msg;
    try {
      msg = JSON.parse(line);
    } catch {
      continue;
    }
    if (msg.id === 1) {
      console.log("server:", JSON.stringify(msg.result?.serverInfo));
      send({ jsonrpc: "2.0", method: "notifications/initialized" });
      send({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} });
    } else if (msg.id === 2) {
      const names = (msg.result?.tools ?? []).map((t) => t.name);
      console.log("tools:", names.length, ["CreateSmartForm", "GetSmartFormContent", "GetProgram"].map((n) => `${n}=${names.includes(n)}`).join(" "));
      clearTimeout(timer);
      child.kill();
      process.exit(0);
    }
  }
});
